      items: [
        { t: '粘贴 URL 提示「请求失败」？', d: '确认该 URL 可被服务器访问（不要指向需要登录的私有地址）；本站对 localhost 与内网地址是放行的，但仍需目标服务能正常响应。' },
        { t: '外链 404？', d: '检查文件是否被删除、是否属于黑名单，以及渠道配置（域名、桶权限、WebDAV 路径）是否正确。' },
        { t: '带扩展名访问会不会出问题？', d: '不会。扩展名只用于直观展示类型；代理、302、访问源切换都按 File_ID 处理。' },
        { t: '上传很慢？', d: '主渠道是同步上传；可把主渠道换成带宽更好的渠道，或用备份渠道分担。大文件建议使用对象存储渠道（COS / MinIO / R2 / S3）。' },
        { t: '点缩略图为什么不是打开详情页了？', d: 'v2.9.0 起缩略图 / 封面用于「看内容」（灯箱 / 播放器），文件名才是「管文件」（详情页）。想改名、改标签、看链接，请点文件名。' },
        { t: '登记文件提示「源地址不属于存储渠道」？', d: '说明这条地址里找不到所选渠道配置的任何一个域名。请确认：①渠道选对了；②源地址确实带着该渠道的「内网通信域名 / 公开访问域名 / 上传接口地址」之一（可以带端口与路径，但主机名必须一致）。三段都对不上时系统不会建记录 —— 因为建了也加载不出来。' },
        { t: '实例之间数据隔离吗？配置要重复设置吗？', d: '文件（含回收站与历史记录）按实例隔离，普通成员只能看到被加入的实例；存储渠道、上传设置等仍是全局 / 账户级配置，所有实例共用，无需重复设置。' },
        { t: '筛选开了「同时」模式，为什么选了图片 + 视频却没有结果？', d: '「同时」表示不同分区条件要全部命中：单个文件的「文件类型」只有一个值，不可能既是图片又是视频。想同时保留两类文件请改用「任意」，或在「文件类型」里多选。' },
        { t: 'WebP 无损 / 有损怎么选？', d: '无损（默认）画质与原图完全一致，适合截图、设计稿等对画质敏感的场景；有损体积更小（通常再省 20-40%），适合照片类内容。无论哪种模式，转换后体积没有变小都会自动保留原文件。' },
        { t: '本地渠道改了对象前缀，旧文件还能访问吗？', d: '能。对象前缀只影响「之后新上传文件」的落盘目录，已上传文件的记录里保存的是当时的实际路径，外链照常可访问；新旧文件会分处不同目录层级。' },
        { t: '目录 / 标签加密了，为什么外链还要输密码？（v3.0.0）', d: 'v3.0.0 起外链只认「文件自身的加密」：给目录或标签加密码只影响访客图库 / 分享页里的浏览权限，不会让 /file 外链也要求密码。如果外链仍然要密码，说明这个文件自己被单独加密了 —— 在文件详情页解除加密即可。' },
        { t: '对外分享链接打不开怎么排查？（v3.0.0）', d: '按顺序看三处：①该目录 / 标签的「对外分享」开关是否仍为启用（也可能被账户的「对外分享」模块或管理员「分享权限」整体关掉）；②是否已过时限（分享记录页可看到到期时间）；③地址里的实例序号是否正确 —— 0 = 默认实例，1..n 按实例创建时间升序，切换实例后旧地址会指向另一个实例，需按当前实例重新复制链接。若设了访问密码，还需输入正确密码。' },
        { t: '升级时提示 unique constraint 怎么办？（v3.0.0）', d: '不用手动加 --accept-data-loss。v3.0.0 起 db push 前会自动跑 compat-sync 做兼容处理（例如把重复标签合并成一条），推送过程中若仍触发唯一约束告警会自动重试；只有反复失败时才需要看日志确认是哪张表的重复数据，再手动清理。' }
      ]
    },
    {
      id: 'localFiles',
      title: '十六、本地文件系统（v3.0.0 新增）',
      intro: '「本地文件」页用来浏览服务器（或容器挂载目录）上已有的文件：默认只读，勾选后可一键复制进图床转成正常文件记录。',
      items: [
        { t: '新建渠道', d: '系统管理 → 上传设置 → 新建渠道，类型选「本地文件」，只需填「浏览根目录（容器内路径）」，例如 /data；Docker 部署时把宿主机目录挂到这个路径即可。「宿主机映射目录」仅作说明，不参与读写。该类型不参与上传：上传设置、备份渠道、Token 等所有渠道下拉都不会出现它，也不会出现在主渠道 / 备份渠道 / 渠道池里。v3.0.0（R5）起「本地文件」渠道仅管理员可用，不再提供渠道授权。' },
        { t: '谁可以看', d: '「页面切换」里的「本地文件」入口对管理员恒显示（即使还没有建渠道，页面内会提示先去新建）；普通用户一律不可见 —— v3.0.0（R5）起该渠道不再支持授权，只有管理员能使用。' },
        { t: '浏览方式', d: '左侧目录树可收起，支持面包屑、双击进目录、类型筛选（图片 / 视频 / 音频 / 文本 / PDF / 其它）、按名称 / 大小 / 修改时间排序、按文件名或路径搜索，以及分页。右上「设置」可改每页条数（默认 48）、单目录读取上限（默认 500）、在线预览大小上限（默认 500MB）。' },
        { t: '顶栏与吸附（v3.0.0 第七轮）', d: '顶部工具栏：页面切换（含实例）、渠道下拉（选择后记忆，刷新 / 重进沿用，渠道被删或停用自动回落）、右侧依次为「上传到图床」、搜索、类型筛选、排序、升降序、刷新、设置与日间 / 夜间切换。页面向下滚动时顶栏自动上滑隐藏，向上回滚立即吸顶显示；左侧目录树占满视口剩余高度并随页吸顶，不再跟随页面滚动。目录树收起按钮改为固定尺寸的独立小方块，收起后不再被压扁变形。' },
        { t: '视频缩略图与多选（v3.0.0 第七轮）', d: '视频文件直接用画面帧做缩略图（浏览器加载视频元数据后定位到第 0.5 秒画面），不再是灰色图标；每个文件左上角有多选勾选框，勾选后可批量「上传到图床」，点击勾选框不会误触发预览。' },
        { t: '预览与下载', d: '图片 / 视频（支持拖动进度，走 Range）/ 音频 / PDF / 文本（txt、md、json 等，超过 200KB 截断）可直接预览，其它类型点缩略图即下载。预览接口只接受「渠道 ID + 相对路径」，必须登录会话，且不计入文件访问统计。' },
        { t: '上传到图床', d: '勾选文件后点「上传到图床」，选目标渠道 / 归属实例 / 上传目录，逐个文件走主上传链路（MD5 去重 → 压缩或转码 → 写渠道 → 落库 → 签发外链），源文件不做任何修改。结果弹窗逐条列出文件 ID 与外链（可一键复制）、命中去重被跳过的项、失败项（可一键重试）。' },
        { t: '已入库角标', d: '目录里已经上传过的文件会带「已入库」角标：先按文件大小比对，大小相同的再算 MD5，命中即标记，鼠标悬停可看到对应文件 ID。判断只做读取，不会改动源文件。' },
        { t: '安全边界', d: '根目录必须存在且是目录，读取前用 realpath 复核（防符号链接绕过）；所有相对路径都会拒绝「..」与隐藏路径段，越界直接报错。.env、.git、node_modules 以及「#」开头的名称一律不列出、不可访问。本页只读：不提供删除、改名、移动，任何写操作都只发生在「上传到图床」这一条链路上。' },
        { t: '手机端抽屉与分页（v3.0.0 第八轮）', d: '手机上目录树收进左侧抽屉（顶部按钮打开），顶栏改为两行：第一行页面切换与渠道，第二行搜索 / 类型 / 排序 / 刷新，搜索改为按钮展开以省出横向空间。列表默认每页 50 条、单目录最多读取 200 条，超出用底部「加载更多」逐段追加；文件名按「开头 + 结尾」中段省略，扩展名始终可见。' },
      ]
    },
    {
      id: 'whatsnew',
      title: '十七、v1.0.0 更新要点',
      intro: 'v1.0.0 没有新增模块，集中在「隔离性、灯箱体验、返回层级、保存时机」四件事上，全部向后兼容：旧数据库可直接沿用，无需迁移脚本手工介入。',
      items: [
        { t: '目录与标签彻底按「用户 + 实例」隔离', d: '以前「新建目录」的空目录登记只按账户存（settings.extraFolders），没有实例维度 —— 在 A 实例建的目录切到 B 实例也会出现。现在登记键改为「账户::实例」，默认实例沿用旧键，存量数据不用迁移。标签同理：tags 表新增 owner 字段，唯一键从「名称 + 实例」改为「名称 + 实例 + 用户」，查询 / 改名 / 删除 / 合并 / 拆分都只在自己名下进行，不同账户互不可见。' },
        { t: '目录树只在当前实例加载', d: '「上传设置」和「登记文件」里的目录树按钮，现在会带上当前实例（localStorage gohub_instance_id）去请求 /api/directoryTree，不再把其它实例的目录一起列出来。「从目录树选择上传目录」这条悬浮提示按需求已移除，只保留图标按钮。' },
        { t: '筛选 / 标签管理 / 批量打标 / 详情常用标签', d: '这四处过去都不带实例参数（有的还把 instanceId 写死成空串），会把全部实例、全部账户的标签当成候选。现在统一带当前实例，并叠加账户归属过滤。' },
        { t: '文件灯箱：只切同类型', d: '上一页 / 下一页 / 键盘方向键 / 幻灯片都只在「当前文件类型」内循环：图片灯箱只切图片、视频灯箱只切视频，PDF / 文本 / 音频各自独立，不会再翻着翻着跳成别的类型。当前类型只有 1 个文件时不显示左右箭头。上拉随机切换同样只在同类型内随机。' },
        { t: '图片灯箱支持双指缩放', d: '手机上用两根手指在图片上捏合即可放大 / 缩小（0.2x ~ 5x），缩放锚点是两指中点，放大后单指拖动可查看其它区域；松手时若小于适应窗口大小会自动回弹。双指手势期间不会误触发翻页或轻点。' },
        { t: '视频灯箱静默切集与鼠标指针修复', d: '视频播完自动切下一个时保持静默（不弹自定义控件、不动光标），右侧原生播放条照常可用。此前切集后整屏进入 cursor:none 会让鼠标指针消失、点不到控件，现在视频灯箱始终保留系统光标。' },
        { t: '上传设置：离开输入框才保存', d: '「上传目录」「禁止压缩格式」两个输入框改为输入时只更新本地草稿，失焦 / 回车 / 清空 / 关闭弹窗时才真正保存并提示，不再每敲一个字符就存一次、弹一次「保存成功」。开关与滑块仍是即时保存。' },
        { t: '用户编辑页保存按钮统一', d: '/customerConfig/edit/ 的保存改为右下角悬浮按钮，与「系统管理 → 网页设置」完全同一个组件（桌面端与移动端样式一致）；保存成功后自动回到用户管理列表 /customerConfig。' },
        { t: '视频灯箱也支持双指缩放', d: '与图片灯箱同一套手势：两根手指捏合放大 / 缩小视频画面（0.2x ~ 5x），缩放锚点是两指中点，缩到比原始画面还小时松手自动回弹。切到下一个视频、关闭灯箱、切换画面方向都会把缩放复位，不会带到下一个文件上。' },
        { t: '移动端屏幕边缘不再出现「返回」拉动动画', d: '手指从屏幕左右边缘起手横滑时，WebKit / Chromium 会把它当成返回手势并在边缘渲染伸缩动画。现在全站统一拦截：只有「起手点在屏幕边缘 16px 内且横向位移占主导」才吃掉手势，页面内的横向工具条（搜索条、面包屑按钮条、筛选标签页）照常可以左右滑动。文件管理页背景与所有弹窗 / 灯箱都生效。' },
        { t: '返回键与 Esc 改为「一次只关最上面一层」', d: '以前灯箱和叠在它上面的文件详情页各自往历史里压哨兵、各自监听 popstate，按一次返回会被两边同时消费，详情页和灯箱一起关掉。现在两者共用一个浮层栈：移动端的返回键 / 边缘返回、桌面端的 Esc，每次只关栈顶那一层 —— 先关详情页，再按一次才关灯箱，一层一层往下退。' },
        { t: '标签管理精确到「每个用户的每个实例」', d: '标签管理里每个账户只管自己名下、当前实例下的标签：拆分、合并、改名、备注、加密、对外分享、删除全部按（用户 + 实例）校验，管理员也不再代管他人标签。同时修掉两个越权点：标签对外分享不再能匹配到同实例下别人的同名标签，标签筛选 / 自动补全接口在未登录时不再返回该实例的全部标签。' },
      ]
    },
    {
      title: '十八、v1.0.1 更新要点',
      intro: 'v1.0.1 把「自动打标签」从写死改成可配置，并补齐本地存储渠道的安全边界、回收站恢复完整性与灯箱键盘操作。数据库结构无变更，可直接覆盖升级。',
      items: [
        { t: '自动添加标签改为后台可配置', d: '原来写死在代码里的规则（文件类型 / 扩展名 / 渠道简称 / 上传方式 / 年份 + 文件名 #话题提取）已全部移除，改到「系统管理 → 其他设置 → 文件标签添加设置」，紧跟「图片尺寸处理」之后。共有三项：①「设置占位符」用占位符拼标签名，支持 {mime} 文件类型、{ext} 扩展名、{channelName} 渠道简称、{uploadSource} 上传方式、{y} 年、{m} 月、{d} 日、{width} 宽、{height} 高，逗号或换行分隔，每段一个标签，取不到值的占位符自动跳过；②「提取指定内容」按 ["文件名片段":"标签名"] 配置，文件名含该片段就打上对应标签；③「自定义规则」一行一条正则，取第 1 个捕获组作为标签名（默认就是原来的 #话题 规则）。三项可同时生效，结果去重（单标签最多 20 字、单次最多 30 个），非法正则跳过并写入系统日志。' },
        { t: '本地存储渠道的「存储地址」只能在已映射目录中选', d: '「存储地址（容器内路径）」由普通输入框改为可输入筛选的下拉框，选项来自容器内真实的挂载点（/api/manage/channels/mounts 解析 /proc/self/mountinfo，并过滤 /proc、/sys、/dev、/etc/hosts 这类伪挂载）。未映射的路径不会出现在选项里、也无法被选中 —— 因为写进未映射路径的文件只存在于容器可写层，容器一重建就全部丢失。若当前配置的路径不在列表里，下方会显示一行橙色警告。' },
        { t: '本地存储渠道可「同步到本地文件管理」', d: '存储地址后面新增同名开关。开启后该渠道的存储目录会直接出现在「本地文件」页（/localFiles）的渠道选择中，可浏览、预览、批量上传到图床；关闭即从选择列表中移除（不影响已上传的文件）。无需再单独建一条「本地文件」渠道。' },
        { t: '回收站恢复会带回原来的文件夹', d: '删除目录时目录登记与目录属性会被清理，只恢复其中一个文件时，原来那层文件夹仍留在回收站、属性也丢了。现在恢复文件（单个或批量）会自动把「仍在回收站里、且是目标目录祖先」的每一级目录恢复回来：重新登记目录、还原属性快照、并从回收站文件夹列表里摘掉。' },
        { t: '彻底删除后自动回收空目录', d: '本地存储渠道的文件被彻底删除后，若所在目录已经空了，会把该空目录一并删除并逐级向上递归，直到遇到还有内容的目录或渠道根目录为止（渠道根永不删除）。只删「读出来是空」的目录，不会影响并发写入的其它文件；失败只记日志不阻断删除。' },
        { t: '回收站彻底删除也有转圈反馈', d: '在与普通文件软删除一致的卡片 / 列表行遮罩之外，文件详情弹窗里的「恢复 / 彻底删除」按钮现在也会显示转圈并禁用（此前从详情弹窗操作时遮罩被弹窗盖住，点了没有任何反馈）。' },
        { t: '文件夹不再参与勾选', d: '图床文件管理里文件夹一律不可选中：卡片 / 列表行不再显示勾选框，「本页全选」与 Shift 区间选择都只作用于文件，移动端长按菜单选「选择」也会提示「文件夹不支持勾选」。文件夹仍可进入、看属性、复制链接、移动与删除（走目录自身入口）。' },
        { t: '跨实例移动文件会复制标签', d: '文件从一个实例移动到另一个实例时，源实例下的标签会「复制」到目标实例（源实例的标签与关联原样保留）。目标实例已有同名标签则直接复用，不重复创建；标签归属沿用原标签的用户。目录整体跨实例搬家时，目录内文件的标签同样会复制。' },
        { t: '灯箱键盘：↓ 随机切换、↑ 打开详情', d: '桌面端图片 / 视频灯箱里，按 ↓ 在同类型文件之间随机跳一个；按 ↑ 打开文件详情并暂停正在播放的视频 / 音频（详情关闭后灯箱原样保留）。← → 仍是按顺序切上一个 / 下一个，Esc 仍交给浮层栈逐层关闭。' },
        { t: '上传目录输入框恢复浏览器历史记忆', d: '首页上传设置 / 上传页的目录路径输入框统一带上稳定的 name 与 autocomplete="on"，浏览器可以正常记住并补全历史上填过的目录。' },
        { t: '发布目录调整', d: '自 v1.0.1 起，Docker 相关文件（Dockerfile、compose、部署脚本、镜像 tar）统一放在项目根的 docker/ 目录；dist/ 仅保留可发布到 Git 仓库的脱敏生产源码。' },
      ]
    },
    {
      title: '十九、v1.0.2 更新要点',
      intro: 'v1.0.2 把 v1.0.1 里「文件夹不可勾选」的临时限制撤销，并修掉它背后的根因（移动不生效、跨实例搬家丢目录、回收站恢复不成整包），同时把标签确权从「名称 + 实例 + 用户」升级为「实例 + 类型 + 名称」。数据库会自动加一列，直接覆盖升级即可。',
      items: [
        { t: '文件夹恢复可勾选，批量移动 / 删除真正生效', d: '卡片、列表行、本页全选、Shift 区间选择、移动端长按菜单共五处重新支持文件夹：勾选一个文件夹就等于勾选它里面的全部内容。移动是整包搬走（目录连同内部所有文件一起到新位置），删除是整包进回收站。只读共享出来的条目仍然不可勾选。' },
        { t: '回收站里的文件夹可以整包恢复', d: '整包删除的目录在回收站里显示为一条「文件夹」，展开能看到当时一起进去的全部内容；恢复时整包还原，文件与文件夹全部回到原位。若原位已经存在同名目录，则自动合并（一份不丢，也不产生重名目录）。' },
        { t: '跨实例移动同名目录改为合并', d: '以前把文件夹移到另一个实例、而目标实例里已经有同名目录时，会因为目录属性表的唯一约束直接失败。现在改为合并：目录属性沿用目标实例已有的那份，文件按目标目录落位，不再报错也不会新建重复目录。' },
        { t: '空目录被回收后，登记与属性快照一并清掉', d: '彻底删除导致某级目录变空并被物理删除时，「已添加目录」列表里的登记、以及这个目录的属性快照会同步移除，不会再留下一个点进去空空的幽灵目录。清理从最深层往上走，遇到还有内容的目录就停下，渠道根目录永远保留。' },
        { t: '标签按「实例 + 类型 + 名称」确权', d: '标签的唯一性判定从「名称 + 实例 + 用户」改为「实例 + 类型 + 名称」：同一个实例里同名标签只会有一条，所有账户共用，创建人记在 owner 上仅供追溯。标签表新增「类型」列（当前为 file，为后续笔记 / 文章 / 待办 / 导航等类型预留），登录、上传、分享、批量打标、合并拆分全部走同一套查找逻辑。启动时会自动把历史上重复的同名标签合并成一条，只跑一次、可重复执行。' },
        { t: '自定义标签规则改成「三段式」', d: '原来要求手写正则，现在是三个直观的输入项：①起始符集合（如 # 或 @、&），②截断符集合（如空格、逗号、句号、破折号），③最多字数。连续出现多个起始符时以最后一个为准，超长的一律丢弃，遇到空白恒截断。默认值等价于原来的 #话题 规则，升级后无需重新配置。' },
        { t: '渠道简称标签固定取主渠道', d: '开启主备双写时，同一份文件在两条渠道里都存在，此前标签里的渠道简称可能跟随「本次实际落库的渠道」变成备渠道，导致同一批文件的标签忽主忽备。现在只要允许双写就固定取主渠道；明确关闭备份时才按实际落库的渠道打标签。' },
        { t: '改本地存储地址要验管理员密码', d: '本地存储渠道的「存储地址（容器内路径）」保存后再修改，会先要求输入当前管理员密码，验证通过才落库，并写入系统日志。防止有人把存储根目录悄悄指向别处，导致后续上传的文件全部跑到预期之外的位置。' },
        { t: '回收站彻底删除有转圈了', d: '彻底删除（单个或批量）执行期间，整个页面会显示一个带「正在删除…」文字的遮罩并锁定操作，结束（成功或失败）自动收起，不会再出现「点了没反应、以为卡死」的情况。' },
        { t: '灯箱里打开详情页，返回先关详情', d: '在图片 / 视频灯箱上打开文件详情后，返回键、边缘返回、Esc 现在一定先关详情页，再按一次才关灯箱。此前两层的关闭顺序会打架，出现「灯箱关了、详情页还在」的残留。' },
        { t: '两个输入框改成多行文本', d: '本地文件渠道的「宿主机映射目录（可选）」改成多行文本框，一行一个目录，与「浏览目录」按顺序一一对应；「其他设置 → 提取指定内容」也改成多行文本，规则多了可以一行一条，不用再挤在一行里横向滚动。' },
        { t: '会话有效期设置真正生效', d: '修掉「用户管理里把会话有效期设成 90 天，实际一天被登出好几次」的问题：一是任何一次接口返回未登录信号都会立刻清会话跳登录（后端重启、瞬时 502、被反代拦一下都算），现在会先向服务端二次确认，确认确实过期才登出；二是登录时签发的 Cookie 生命周期按账户设置的最大值计算，设置保存后会重新按新值签发。' },
      ]
    },
    {
      title: '二十、v1.0.3 更新要点',
      intro: 'v1.0.3 做三件事：把「文件管理」的数据权限收回到每个账户自己名下、给本地存储与第三方渠道之间加上「转存」能力、补齐回收站的目录层级。数据库会自动加两处索引与一列，升级前会先合并历史重复数据，直接覆盖升级即可。',
      items: [
        { t: '文件管理只显示自己的文件', d: '以前管理员进「图床文件管理」时，不指定用户就等于看到全站所有账户的文件，还能直接改名、移动、删除 —— 这是权限设计上的疏漏。现在每个账户（含管理员）只列出自己上传的文件，批量操作、回收站、目录树、目录导航全部按登录账户收窄；需要跨账户只读，请用「目录共享」或「对外分享」。' },
        { t: '新增「转本地 / 转异地」：不换外链也能换存储', d: '文件详情页「下载」按钮后面新增一个转存按钮：本地存储渠道的文件显示「转异地」，第三方渠道的文件显示「转本地」。选好目标渠道即可把实体文件原样搬过去（不压缩、不转码、不转 webp、不改文件名），外链、文件名、类型、尺寸、分类、标签、上传时间全部不变，只有「存在哪个渠道、用什么地址取、删除时找谁」这些数据跟着换。' },
        { t: '转存时的源件处理', d: '从第三方渠道转回本地时，必须二选一：保留源件（只下载并更新数据，原渠道文件不动）或删除源件（转存成功后删除原渠道文件，不可恢复）。本地转异地则一定删除本地实体文件 —— 否则同一份文件会长期占两份本地空间。登记文件（只登记了地址、没真正上传过的）一律禁止删除源件，因为源文件不在本系统管理范围内。' },
        { t: '回收站按目录层级浏览', d: '回收站不再是一条大平铺：根目录只显示「被删的文件夹」和原本就在根目录的删除文件，要进到对应文件夹里才看得到它内部删掉的东西。顶部显示当前所在目录，带「返回上级」。目录条目支持整包恢复 / 整包彻底删除（含只删了文件、目录本身没删的情况）。' },
        { t: '移动文件 / 文件夹有全屏遮罩', d: '移动（单个或批量）执行期间显示全屏「正在移动…」并锁定操作，结束自动收起，不会再出现「点了没反应、以为卡死」。' },
        { t: '灯箱里打开详情后的返回层级修稳了', d: '以前同一个文件详情弹窗会被登记两次（组件登记一次、自动监听又登记一次），栈顶变成那条兜底记录，移动端返回时走「点关闭按钮 / 派发 Esc」的备用路径 —— 弹窗没有可点的关闭按钮时，这次返回就被白白吃掉，表现为「有时能关、有时关不掉」。现在每个弹窗只登记一次，返回 / Esc 稳定地先关详情、再关灯箱；弹窗里展开的下拉框仍会先收起。' },
        { t: '白天/夜间自动切换时间可配', d: '「系统管理 → 网页设置 → 全局设置」在「背景图透明度」下面新增一项「白天/夜间切换时间」，默认留空即 08:00—20:00（08:00 切白天、20:00 切夜间）。主题切到「自动」后按这个时间判断，不再跟随系统深色偏好；页面挂了一整天也会在整点自动切换。' },
        { t: '标签唯一性下沉到数据库', d: '标签的唯一键正式改为「实例 + 类型 + 名称」，旧键「名称 + 实例 + 创建人」已删除 —— 同一实例里同名标签从此只有一条，不会再出现「明明有这个标签，筛选却漏文件」。升级前会先把历史重复合并成一条，所以不会因为重复数据导致升级失败。' },
        { t: '目录分类也支持类型维度', d: '目录属性表新增「类型」字段，与标签同一套口径：目前只有文件分类，后续笔记 / 文章 / 待办 / 导航接入时各自的分类互不影响，同名路径可以各存一份属性。' },
        { t: '超级管理员会话固定 1 天', d: '用环境变量配置的超级管理员是「应急找回」角色，会话有效期固定为 1 天，不读取「用户管理」里的账户设置、也不提供配置项；普通管理员仍按自己账户里设置的天数生效。' },
      ]
    },
    {
      title: '二十一、v1.0.4 更新要点',
      intro: 'v1.0.4 没有新功能，全部是补齐上一版遗留：文件转存后的归属与副本数量、标签三段式规则的实际生效、移动端回退层级对齐、后台看大图的白等，另外修掉一处缓存头把「登录可见」标成公开的问题。本次没有数据库结构变更，直接覆盖升级即可。',
      items: [
        { t: '转存后主记录落在目标渠道，副本不再越转越多', d: 'v1.0.3 勾选「保留源件」转本地时，转存结果会被塞到备份渠道，主渠道原记录没被替换，详情页还会冒出两个「备份渠道」。根因是全系统存在三套「谁是主副本」的判断口径（副本表的 isPrimary、渠道表的 isMain、以及直接取数组第一条），互不通信。现在统一成一个判定入口：isPrimary 且可用 → isPrimary → 所在渠道是主渠道 → 数组第一条，取源、详情页、随机列表全部改用它。' },
        { t: '转存改为「主副本原地搬迁」', d: '以前每转一次就把所有副本降级、再新增一条，转几次就有几条，永远对不上。现在直接把源副本那一行改写到目标渠道上（含按目标渠道配置重新生成 key），副本总数保持不变；目标渠道已存在同一文件的副本时，覆盖目标那条并删掉源那条，避免一个文件在同一渠道出现两行。' },
        { t: '「备份渠道」只列真正的备份渠道', d: '以前详情页的「备份渠道」等于「除主副本外的所有可用副本」，把普通副本也算进去了 —— 两个备份渠道就是这么来的。现在只认渠道上的备份标记，普通副本单独列在「其它副本」里，两者不再混为一谈。' },
        { t: '保留源件 = 主记录换新、旧渠道留一份兜底', d: '明确语义：不论异地转本地还是本地转异地，主副本永远落在被转去的那个渠道上；勾选「保留源件」只是在新渠道留下一条普通副本作兜底。备份渠道里的数据一个字节都不动。' },
        { t: '标签规则：配了就生效', d: '修掉三处不生效的地方：一是默认截断符的默认值格式不对（按逗号切分后变成多字符记号，单字符匹配永远不命中），不配截断符时规则等于没有；二是起始符框留空现在表示「从文件名开头算起」，并且只在第 0 位生效一次，不会把每一段都收成标签；三是取到文件名结尾的标签会自动剥掉扩展名，不再出现「风景.png」这种结果，也不白吃限长额度。空格恒为截断符，写在应用层、不可配置。' },
        { t: '「本地文件」渠道浏览目录免管理员密码', d: '「存储地址」改动需要管理员密码二次验证这条保留，但范围收窄到「本地存储」渠道。浏览目录只是列一下里面有什么，不写入也不改路径，不再要求输密码。' },
        { t: '移动端回退层级与桌面端一致', d: '上一版修好了「弹窗被登记两次导致返回跳级」的根因，但只在桌面端验证过。移动端另有一套「是不是手机」的判断，三处代码各写一份且标准不同，导致手机上返回直接退到底。现在统一按「设备有没有触摸能力」判定，横竖屏切换时还会校正返回哨兵；桌面端把窗口拉窄也不会再被误判成手机。' },
        { t: '后台看大图不再白等', d: '查出两处原因。其一是每次校验登录状态都在重算一次很耗时的密钥派生（约 120ms），后台一屏三十张缩略图就白等三秒多，现已改为进程内复用。其二是视频与图片的加载方式天生不同：视频边下边播、拿到开头就能出画面，图片必须整份到齐才能解码；加上图片可能在第三方渠道、需要跨公网拉取。界面上补了一层「先用列表已缓存的缩略图铺模糊底、原图到了再淡入替换」，点开瞬间就有画面。' },
        { t: '登录可见的内容不再被标成公开可缓存', d: '后台预览的响应头里已经声明了「私有」，但后面的取流代码又无条件覆盖成「公开、可缓存一天」，站点前面若有共享缓存或反向代理，存在被他人缓存到的可能。现在只在尚未设置时才写默认值，私有保持私有、公开外链保持公开。' },
      ]
    },
    {
      title: '二十二、v1.0.5 更新要点',
      intro: 'v1.0.5 的核心是「文件传上来之后还能再收拾」：图片可以原地裁剪 / 压缩 / 转 WebP，视频可以转码 / 压缩，音频可以压缩，处理完外链一个字都不用改。另外补齐了几处交互（灯箱内上传、移动端返回上一级目录、详情页刷新、裁剪页旋转），把标签规则换成了一句人话，并让「本地文件」渠道支持授权给其他账户。本次没有数据库结构变更，直接覆盖升级即可。',
      items: [
        { t: '详情页原位编辑：图片裁剪 / 压缩 / 转 WebP', d: '当文件的主副本在「本地存储」渠道上时，详情页「转异地」按钮后面会出现裁剪、压缩、转 WebP 三个按钮，显示哪几个由后端探测决定，不按扩展名猜。三条硬约束：只对本地存储渠道上的主副本生效（远端对象存储改不了别人服务器上的东西）；磁盘路径、文件名、扩展名一律不变，这是外链继续有效的唯一保证；只更新大小、MD5、类型、宽高与编辑时间，其余字段不碰。裁剪复用上传时的裁剪组件（含旋转方向），由前端裁好后以 multipart 回传结果图；压缩按「压到原体积的百分比」；转 WebP 可选有损 / 无损。' },
        { t: '视频转码 / 压缩、音频压缩', d: '视频先探测编码，已经是浏览器通用编码（H.264）的直接回「无需转码」，不让你对着一个本来就能播的文件白等几分钟；只有 HEVC 这类真的播不了的才动手转。压缩与转码都受「压缩文件上限时长」「视频转码上限时长」约束，判的是实际执行时间而不是预估时间；超时自动放弃并写系统日志，而且放弃时文件一个字节都不动 —— 不会出现「提示失败了但文件已经被改坏」。' },
        { t: '已经压过一次会先问一句', d: '压缩前若检测到「实际大小与原文件大小不一致」，说明之前压过，前端先弹确认框告知再压会继续损失画质，确认后才带 confirm 提交；后端也做一次兜底校验。已经是 WebP 的图片不再显示转 WebP 按钮，后端同样拒绝。' },
        { t: '上传后自动打标签改走独立队列', d: '原来的后台串行链上同时排着自动打标签和「查 IP 归属地」，后者要访问外部服务，网络一抖就把标签任务全堵住，表现是「刚传完看不出标签，过一会儿自己冒出来」。现在两条队列彻底分开，归属地查询再慢也不影响标签，上传速度本身也不受影响。' },
        { t: '标签规则换成一句人话', d: '从「填一串符号」改成一句话：从 [ ] 为起始、以 [ ] 为截断、获取不超过 [ ] 位数。前面带一个「启用功能」勾选框，整体放在「系统设置 → 其他设置 → 提取指定内容」后面。四条固定规则不再需要配置：空格永远是截断符；连续多个起始符以最后一个为准；超过限定字数整条丢弃而不是截一半；标签跑到文件名末尾会自动剥掉扩展名。老安装若三项都还是旧默认值会自动升级，改过任意一项则原样保留。' },
        { t: '灯箱里可以直接上传，大图不会关掉', d: '「本地文件」页打开大图后，关闭按钮左侧多了上传图标，点它选渠道 / 实例 / 目录即可后台上传，灯箱保持打开。完成后上方浮出结果条，提供「完成」（留在灯箱）与「查看详情」（关灯箱、打开文件详情）两个出口。' },
        { t: '手机上的返回键回上一级目录', d: '以前在「本地文件」里进到很深的目录，手机一滑返回整个页面就退出去了。现在与「图床文件管理」页一致：返回 = 回上一级目录，只在最外层才离开页面。同时排除了三类误判（浮层还开着、程序自己退历史哨兵、灯箱自己退哨兵），不会被这些内部动作顺手带回上一级。' },
        { t: '详情页标题刷新 + 「源」显示真实磁盘路径', d: '标题旁多了刷新按钮，点一下在不关弹窗的前提下重新载入元数据，转圈期间禁用防重复点击。另外主副本在本地存储渠道时，详情页「源」直接显示文件在服务器上的真实路径与固化文件名，排查「到底存哪儿了」不用再猜。' },
        { t: '上传裁剪页可以转方向了', d: '裁剪页多了一组「左转 / 右转 / 复位」按钮与当前角度显示，手机竖拍的歪图可以直接转正。旋转永远从原始文件重新渲染（角度是绝对值而非累加），所以连转四次回到原位画质与原图完全一致，不会因为反复重编码变糊。' },
        { t: '「本地文件」渠道支持授权，入口按授权显隐', d: '渠道卡片「更多」旁边重新出现「授权」按钮，管理员可以把某一个本地方向开放给指定账户（管理员自己无需授权）。普通账户默认在左上角切换菜单里看不到「本地文件」入口，只有名下存在被授权的可加载渠道时才出现。上传弹窗的「目标渠道」只列该账户可用的主渠道（排除备份渠道），「归属实例」只列该账户名下的实例。' },
        { t: '备份渠道不会再被当成转存目标', d: '转存的候选目标渠道列表此前把备份渠道也列了进去，一旦被选中，那条副本会被升级成主副本，永久改变「备份渠道只做镜像」的语义。现在候选列表排除备份渠道，提交时还会再拦一次（防止打开弹窗期间渠道角色被改）。' },
        { t: '菜单入口补齐', d: '首页右上「更多菜单」在「系统管理」后新增「我的账户」，后台「图床文件」更多菜单在语言切换后新增「我的账户」与「系统管理」（仅管理员），都从新标签页打开，桌面端与移动端两套菜单同步。' },
      ]
    },
    {
      title: '二十三、v1.0.6 更新要点',
      intro: 'v1.0.6 的主线是「对外 WebDAV 彻底重做」：它不再借道图床上传链路，而是一块真正的网盘——文件原样落盘、不改名不压缩不转码、不限类型与大小，也不进「图床文件」和「历史记录」。配套给每个普通账户加了「WebDAV 管理」（建渠道、改名称备注、重新生成密钥、删除）与「本地文件」里的 WebDAV 加载项（可重命名、可删除）。其余改动集中在细节：标签提取改为纯符号输入并真正生效，转 WebP 后扩展名与数据同步、外链一律不带扩展名，本地文件页的批量栏与菜单更顺手，另修掉了「浏览器闲置后回到 GoHub 停在空白页」的老毛病。',
      items: [
        { t: '对外 WebDAV 重构：登录名是账户名，密码只认渠道密钥', d: '旧版本可以用账户密码登录 WebDAV，等于把网页登录口令又暴露在一个新协议上。现在登录名仍是账户名，密码必须是该账户在「WebDAV 管理」里创建的某个渠道的访问密钥（16 位大小写字母 + 数字，可随时重新生成，旧密钥立刻失效）；用户密码不再能用于 WebDAV。管理员账户一律禁止使用 WebDAV，只能用普通账户。' },
        { t: '对外 WebDAV 重构：纯网盘，不再当图床用', d: '以前 PUT 交给图床上传链路处理，文件会被命名规则改名，还可能被压缩、转码、转 WebP。现在文件按标准 WebDAV 协议原样落到服务器的 webdav 目录（/app/backend/webdav/{账户名}/{渠道存储路径}），上传时是什么样，落盘就是什么样；文件类型与单个文件大小的限制一并移除。因为不写文件记录表，WebDAV 传的文件不会出现在「图床文件」和「历史记录」，任何页面（含文件详情）也不会给出裁剪、压缩、转码、转 WebP、存异地这些操作。' },
        { t: '对外 WebDAV 重构：每个账户可以挂多个盘', d: '一个账户可以建多个 WebDAV 渠道（数量由管理员设定，默认 2 个），每个渠道有自己的名称、存储路径、访问密钥与备注。名称可改但同一账户下不可重复；存储路径支持多级（如 /文件/工作），一经保存不可修改，且一级目录在同一账户下不能重复——否则两个盘指向同一棵目录树，容易误删。客户端挂载地址统一填 /dav/，后端按密钥反查这次请求落在哪个渠道。' },
        { t: '对外 WebDAV 重构：开关一关，全局停用', d: '「系统管理 → 安全设置 → 对外 WebDAV」的启用开关关闭后，/dav 的所有请求直接 403，连「本地文件」里的 WebDAV 加载项也会一起隐藏——需求是「关闭后所有 WebDAV 文件不可传输和访问」，只堵协议入口不够。这一段的配置存在其他设置分区，旧代码却去安全设置分区读，等于开关从来没生效，本版一并修正。顺带删掉了「根目录前缀」与「只读模式」两项：挂载点固定 /dav/，网盘按标准协议必然可写。' },
        { t: '「本地文件」里的 WebDAV 加载项可改名、可删除', d: '开通 WebDAV 的账户会在「本地文件」页多出一条「WebDAV 文件」加载项，看到的就是自己账户 webdav 目录下的真实内容。卡片与列表右侧有「更多」菜单，可以重命名（同目录内改名，同名会拒绝）与删除（二次确认，真删不进回收站，文件夹连同内容一起删）；后端只对这条虚拟渠道放行写操作，其余本地文件渠道指向用户机器上的原始目录，一律只读，且不允许对渠道根目录动手。' },
        { t: '「本地文件」里的「本地用户默认文件」加载项（v1.0.9 改名）', d: '每个账户都多一条「本地用户默认文件」（v1.0.8.1 时叫「本地默认文件」，v1.0.9 改名以免被误读成「全站公共目录」），指向 uploads/_user/{账户名}/999999 —— 也就是走内置本地存储渠道上传时文件真正落盘的位置。以前这些文件只能在「图床文件」里看，磁盘上的真实目录无从下手；现在能直接浏览、预览、批量下载。目录不存在时按需创建，新账户第一次进来看到的是空列表而不是报错。' },
        { t: '标签提取：纯符号输入，并且真的生效', d: '起止符输入框改成纯符号串（例如 #@&），每个字符就是一个记号，相邻多个起始符以最后一个为准；留空则回落到默认值（起始 #@&，截断为常见中英文标点与括号）。同时修掉「设置里看着对、实际提取不出来」的根因：旧版把默认值存成 JSON 数组字符串，而解析时又按逗号切分，切出来的是多字符记号，逐字符比对永远不命中。现在前端会把历史 JSON 值还原成纯符号串显示，后端在启动时把「从未动过」的旧默认值一次性迁移，改过任意一项则原样保留。' },
        { t: '转 WebP 后扩展名一起改，外链一律不带扩展名', d: '本地存储渠道的图片转 WebP 后，磁盘文件名、渠道内的存储键与展示用的原始文件名一起改成 .webp，数据同步更新。为了让这条改动不影响已经发出去的链接，签发外链改为默认不带扩展名——扩展名本来就只是个装饰，服务端会按「带扩展名 / 去掉扩展名」两种形态查库。' },
        { t: '渠道「自动授权所有用户」', d: '每个渠道的授权弹窗里多了「自动授权所有用户」开关（默认关闭）。打开后该渠道对所有账户开放，包括以后新建的账户——创建即授权，不用再逐个勾。内置本地存储渠道（code 999999）的这个开关强制开启且不可关闭，否则新账户上传就没有落盘地点。另外 999999 的「自定义存储前缀」与「自定义文件命名」改为只读，固定使用默认配置。' },
        { t: '输入框记住最近用过的路径', d: '「上传设置 → 上传目录」与「登记文件 → 文件分类」两个输入框现在有浏览器本地记忆：光标进入就列出最近 5 条，选中即填入。数据只存在这台机器的浏览器里，不上传服务器。' },
        { t: '浏览器闲置后回到页面不再白屏', d: '以前关掉浏览器或长时间闲置后再切回 GoHub，页面停在一片空白，必须手动刷新。根因是复活逻辑把「框架挂载了但渲染出来是空壳」误判成「已经渲染好了」，于是永远不救。现在会先检查页面里是否真的画出了内容，再补上「页面恢复可见」与「动态加载失败」两个触发点；首屏守护时间也从 12 秒收到 9 秒。' },
        { t: '详情页处理链路的手感修正', d: '压缩弹窗默认落在 75%，并加了一行「当前文件实际大小为 xxx」，压过再压的提示字号加大两号；点「开始压缩」后按钮变「正在压缩」且不可再点，完成后变「已完成」再自动关闭。视频转码确认页直接显示当前视频的编码格式，不用再猜。原来的「源」按钮改成弹窗展示地址并带复制按钮。「存异地」取代了原来的「转异地」，音量按钮挪到「下载」后面。移动端详情内容区宽度从 95% 调到背景层的 96%，左右留白更小。' },
        { t: '首页「其他」菜单与本地文件批量栏', d: '首页链接模式下的「外链」收进新的「其他」按钮：桌面端悬停展开、移动端点击展开，下拉里「外链」上方新增「下载」——直接把输入框里的链接取回本地（能直连就用 Blob 下载，跨域被拦时退回新窗口打开）。本地文件页的批量栏文案精简为「x 个 / 取消 / 上传」，并新增「下载」；移动端改成横向滑动不换行，同时移除了顶栏那个重复的「上传到图床」按钮。' },
      ]
    },
    {
      title: '二十四、v1.0.7 更新要点',
      intro: 'v1.0.7 没有数据库变更，主线是「把点了没按预期反应的地方逐个掰正」：首页链接模式的下载按钮不再跳页、文件标签设置不再整块消失、外链彻底去掉扩展名、灯箱里查看详情不再顶掉灯箱、抓拍图上传可以选渠道与目录、WebDAV 的模块与目录项不再被条件静默隐藏。同时把预览与网盘两处性能做了实打实的优化：文件取流加了 ETag 与 304，WebDAV 列目录从串行读文件信息改成并发加短时缓存。图片裁剪的默认框也改成了整张图，转动方向后保存不会再误裁。',
      items: [
        { t: '首页链接模式：下载不再跳页', d: '在「链接」上传方式下粘贴一个外部图片地址，点「其他 → 下载」，以前浏览器会直接打开那张图——因为目标站点没开 CORS，前端拿不到文件内容，只能退回「打开链接」。现在改成由本机服务端中转下载：服务端把远端文件取回后带 attachment 头下发，同源请求必然触发「保存文件」，页面也不会跳走。中转只接受 http/https，超过 2GB 的链接会提示改用原链接。' },
        { t: '「文件标签添加设置」配置项不再消失', d: '以前关掉「启用自动添加标签」之后，下面的「设置占位符 / 提取指定内容 / 按表达式提取文件名内容」三组规则会整块从页面上消失，看起来像配置被清空了，也改不了。现在三组规则始终显示、始终可编辑，关闭状态只在顶部多一行提示说明「规则会保存但不生效」，方便先把规则配好再一键打开开关。' },
        { t: '生成的外链默认不带扩展名', d: '新复制的外链形如 https://你的域名/file/xxxx，不再拖一个 .jpg 尾巴。扩展名在这个地址里本来就只是装饰（服务端带不带都能查到文件），去掉之后的好处是：图片转 WebP、视频转码后文件后缀变化，链接也不会失效。已经发出去的带后缀链接照旧可以打开，不需要改库、不需要换地址。' },
        { t: '图片预览更快：先出小图，再换原图', d: '文件详情页的图片预览现在会先用一张 640 宽的缩略图占位，原图在后台继续加载，到了再无缝替换。外网带宽紧张时不再是整块空白转圈。灯箱本来就是这个机制（列表缩略图先显示，原图随后覆盖）。' },
        { t: '同一张图第二次打开几乎不再耗流量', d: '文件取流接口加了 ETag / Last-Modified 与条件请求：浏览器第二次打开同一张图时会先问「文件变了吗」，没变就直接用本地缓存，服务器一个字节都不发。代理模式下这条判断还会透传给源站，上游说没变同样回 304。' },
        { t: '本地文件灯箱里查看详情，不再把灯箱顶掉', d: '在「本地文件」的灯箱里发起上传，完成后点「查看详情」，详情页会直接盖在灯箱之上；关掉详情还停在原来那张图上，浏览位置不丢。以前是先关灯箱再开详情，看起来像灯箱被踢了出去。' },
        { t: '视频抓拍图上传，可以选渠道、实例和目录了', d: '以前抓拍图只能传到默认渠道的默认目录。现在点「上传到图床」会先弹出选择页：目标渠道 / 归属实例 / 上传目录——和「本地文件」页的上传是同一个界面（同一套组件），选过的值会被记住。抓拍图依旧自动带「视频抓拍」标签。' },
        { t: 'WebDAV：模块和目录项都能看见了', d: '「用户管理 → 编辑账户」里的 WebDAV 卡片以前要三个条件同时满足才出现，缺一个就整块消失且不说原因；现在普通用户账户一律显示，缺哪一项就在卡片里写明（全局开关没开 / 该账户没授权），创建按钮相应置灰。另外「本地文件」里的 WebDAV 加载项改为「授权即出现」——以前必须先建过一个渠道才看得到，等于把入口藏起来了。' },
        { t: 'WebDAV 大目录打开更快', d: '以前列一个目录要对每个文件逐个读一次文件信息（串行），上千个文件时 Finder / 资源管理器会明显卡顿。现在改成并发读取并做 3 秒短时缓存，任何写入（上传、删除、新建目录、移动、复制）都会立刻让缓存失效，不会读到旧列表。目录清单还带了 ETag，客户端重复请求可直接拿到 304。' },
        { t: '裁剪图片：默认框就是整张图', d: '裁剪页打开时选择框默认覆盖整张图。只想转个方向的话直接保存不会裁掉任何像素；而且这种「没裁」的情况不会重新编码——JPG 不掉画质，PNG 不会莫名变大。需要裁剪时自己拖四角即可。' },
        { t: '详情页按钮改名', d: '「转本地」改为「存入本地」，「存异地」改为「转到异地」，与按钮实际含义对齐：前者是把第三方渠道的文件取回本地，后者是把本地文件送到异地渠道。' }
      ]
    },
    {
      title: '二十五、v1.0.8 更新要点',
      intro: 'v1.0.8 没有数据库变更。这一版主要是在收前两版的尾巴：三个「说修好了、实际没好」的问题这次找到了真正原因——文件标签设置整块空白是文案里的 @ 与 | 撞了格式，抓拍上传的下拉框展不开是层级写得一半一半，WebDAV 总开关误报是普通用户读取时被挡在门外却把「读不到」当成了「没打开」。此外把移动端顶栏与第二行的间距收紧到 2px，本地文件灯箱对已入库的文件直接给「详情」，并补上了视频抓拍。',
      items: [
        { t: '「文件标签添加设置」终于能正常显示', d: '前两版都以为是被条件隐藏了，实际是这一块的说明文字里出现了 @ 和 | ——它们在文案格式里是「引用另一条消息」和「复数分隔」的语法符号，解析失败后整块设置渲染中断，表现为连开关都看不见。现在这几条说明改用转义写法，三组规则、开关、输入框、快插按钮全部正常显示，正文里的 #@& 示例也能正常阅读。' },
        { t: '新建文件夹时的不合法提示条', d: '「目录名称不能包含 \ / : * ? " < > |」这条提示里的竖线属于同一类符号冲突，一并改掉了。' },
        { t: '抓拍图上传：目标渠道与归属实例的下拉框能看见了', d: '以前在视频灯箱抓拍后弹出的上传配置窗里，点开下拉框能点、但列表看不见——列表已经渲染出来，只是被压在弹窗底下（弹窗用了手写的固定层级，而下拉列表用的是系统递增层级，两者不同源）。现在弹窗和下拉都交给同一套层级管理，后打开的必然盖住先打开的。' },
        { t: 'WebDAV 总开关：普通用户也能读到真实状态', d: '以前普通用户进自己的账户页，读「对外 WebDAV 总开关」用的是管理员接口，被拒绝后前端把「读不到」当成了「没打开」，于是永远提示「总开关还没打开」，而管理员进同一页面却正常。现在新增了一组只返回本人数据的接口，总开关状态能正确读到，提示不再误报。' },
        { t: 'WebDAV：普通用户可以自助管理自己的渠道', d: '在管理员给账户开通 WebDAV 之后，用户现在可以自己创建渠道、改名称与备注、重新生成访问密钥、删除自己的渠道，不需要管理员代劳。能创建几个仍由管理员在「管理员操作 → 允许创建数量」里设定；管理员账户本身依旧禁止使用 WebDAV。' },
        { t: '「缺哪一层」的提示只给管理员看', d: '账户页里的「总开关没开 / 该账户未授权」这两条提示会暴露管理侧的配置状态，现在只在管理员查看他人账户时显示；普通用户看自己的页面只保留渠道列表与创建入口。' },
        { t: '移动端顶栏更贴顶', d: '手机上图床后台的顶行栏与屏幕顶部的间距从 6px 收到 2px。' },
        { t: '移动端第二行：常态与吸附都贴紧顶栏', d: '「图床文件」页顶部那行全选 / 视图切换按钮，与顶栏的间距从 8px 收到 2px；页面滚动后这行吸附在顶栏下方时同样是 2px，不会出现「一吸顶就多出一段空隙」的跳动。' },
        { t: '本地文件灯箱：已入库的文件按钮变成「详情」', d: '在「本地文件」页浏览时，如果当前文件已经传到过图床，灯箱右上角不再显示「上传」，而是显示「详情」——点开就是它在图床里的文件详情页，灯箱保持打开，关掉详情还停在原来那张图。未入库的文件仍是「上传到图床」。' },
        { t: '灯箱新增「更多」下拉', d: '按钮旁边多了一个「更多」下拉面板，里面是与按钮等价的入口（已入库为「查看详情」，未入库为「上传到图床」），窄屏放不下太多图标时用它更顺手。' },
        { t: '本地文件里的视频也能抓拍了', d: '以前只有「图床文件」页的视频灯箱有抓拍按钮。现在两边一致：打开视频后右上角出现相机图标，抓下当前画面，可以按 v1.0.7 的目标渠道 / 实例 / 目录配置上传，也可以直接下载。' }
      ]
    },
    {
      title: '二十六、v1.0.9 更新要点',
      intro: 'v1.0.9 没有数据库变更，主线是「大文件转存要能善后」与「灯箱上的几个小毛病」：转存改成先登记、再搬字节、后切数据，中途失败会在详情页留下一个「重试转存」，不会再把目标渠道塞出一个几百 MB 的孤儿；取源与写入都改成流式并带重试与校验。灯箱侧去掉了多余的「三点」按钮，抓拍图的「查看」、上传中的提示、上传时暂停视频、下拉打开已落库详情都补齐了。另外禁止了全站横滑触发的返回与边缘拉伸动画，本地存储前缀的一级目录也不再允许以下划线开头。',
      items: [
        { t: '转存失败可以「重试」了', d: '以前文件在两个渠道之间搬，只要中途有一环失败（进程重启、数据库事务超时、远端断流），就可能出现「目标渠道里躺着一个几百 MB 的文件，但数据库还指着源渠道」的悬空状态，只能人工收拾。现在转存开始时会先把这次任务登记到源副本的备注里（目标渠道、方向、尝试次数），实体写进目标渠道后再记一笔「已暂存」，最后才切数据；任一步失败都会保留这份登记，详情页的「存入本地 / 转到异地」按钮直接变成「重试转存」，并说明上次停在哪一步。如果实体已经在目标渠道，重试只补做数据切换，不会重新上传。' },
        { t: '大文件传输更稳，也更省内存', d: '转存的取源与写入都改成了流式：本地文件直接走磁盘、远端文件先流式落到临时文件再写入目标渠道，几百 MB 的文件不再整份读进内存。远端取源做三次重试，并校验落盘字节数是否等于 Content-Length、记录的 MD5 是否一致；写入目标渠道同样三次重试，本地渠道还会再核对一次目标文件的字节数。长度对不上就中止切换，不会写进一条「看起来成功」的记录。' },
        { t: '外链偶发 404 / 502 修好了', d: '取源时判断「这个副本有没有内容」的旧规则只认「渠道内标识」和「完整地址」两种，漏掉了「固化寻址路径」这种形态。某些文件（登记文件、部分渠道转存后）的副本恰好只有固化路径，于是被判成「没有可用副本」，外链直接 404，走代理模式时表现为 502。现在三种形态任有一个就参与取源，同时把这种情况写进系统日志，便于定位。' },
        { t: '「本地文件」页的默认加载项改名', d: '「本地默认文件」改为「本地用户默认文件」。它指向的始终是当前登录账户自己的默认落盘目录（uploads/_user/当前账户/999999），旧名字容易被理解成「所有用户共用的目录」。' },
        { t: '灯箱上的按钮与提示', d: '①关闭按钮左侧那个「三点」下拉入口删掉了 —— 它和「上传 / 详情」是同一件事，顶栏因此出现两个看起来都像上传的图标；②视频抓拍面板里的「查看」现在能真正打开刚上传那张图的详情（以前拿文件名当文件 ID 去查，必然失败）；③在灯箱里提交上传、或在「文件」里勾选文件提交上传时，页面底部会出现「正在上传…」的提示；④在灯箱里点「上传」会先把正在播的视频 / 音频暂停；⑤已落库的文件在灯箱里向下拉，直接打开它在图床里的详情页。' },
        { t: '灯箱里上传成功后点「详情」不再报错', d: '灯箱里上传成功后，页面会把「这个文件已经落库」记在列表项上。以前记的是一个布尔值 true，紧接着顶栏按钮从「上传」变成「详情」，点它却拿 true 去查文件详情，自然查不到。现在记的是上传返回的真实文件 ID。' },
        { t: '本地存储前缀不允许以下划线开头', d: '「自定义存储前缀」的一级目录（去掉开头斜杠之后的第一段）不能以 _ 开头。磁盘上以 _ 开头的目录是系统保留区（_user / _avatars / _ipdata），允许自定义到这些名字下会把文件混进别的链路。前后端都做了校验，前端在提交前就拦下并提示。内置渠道（999999）的前缀按 v1.0.8 保持只读，这条校验实际作用于自建的本地存储渠道。' },
        { t: '全站不再有横滑返回与边缘拉伸动画', d: '手机上左右滑动页面时，浏览器会把它当成「返回上一页」，并在屏幕边缘画一段拉伸预览。现在整页的横向手势由页面自己接管：边缘起手且横向占主导、页面中部明显横滑，都会被吃掉；纵向滚动、页面内可横向滚动的工具条 / 缩略图带、表单控件（输入框、滑块、开关）一律放行。首页「文件」模式的上传区另外只接受纵向手势。' },
        { t: '对外 WebDAV：同名上传直接覆盖', d: '复核了 /dav 的上传实现：文件先写到同目录的临时文件，fsync 之后原子改名到目标名，同名即覆盖；客户端中途断开只会留下临时文件，原文件一个字节都不动。' }
      ]
    },
    {
      title: '二十七、v1.1.0 更新要点',
      intro: 'v1.1.0 没有数据库变更（uploadSource 是字符串列，新增取值不需要迁移）。主线是「把转存这件事记清楚」：文件在两个渠道之间搬过之后，详情页的「上传方式」会写明是异地存入还是本地转出；筛选弹窗同步多出这两个选项，并把不再使用的 WebDAV 选项撤掉。另外修了灯箱里详情页与灯箱的关闭顺序、{filename} 命名的字符清洗口径、去重命中后应以最新文件为准的几处数据，以及标签页在后台放置很久后回来偶发白屏不自动恢复的问题。',
      items: [
        { t: '上传方式新增「异地存入（StoreIn）」「本地转出（StoreOut）」', d: '通过「存入本地」把文件从异地渠道搬到本地渠道，成功后该文件的「上传方式」记为 StoreIn，详情页显示「异地存入（StoreIn）」；通过「转到异地」把文件从本地渠道搬到异地渠道，记为 StoreOut，显示「本地转出（StoreOut）」。写入与渠道副本切换在同一个数据库事务里提交，不会出现「副本已经搬过去、上传方式还写着原来入口」的中间态。同一个文件被反复转存时以最后一次成功的方向为准；如果某次转存失败，上传方式保持原值不变。' },
        { t: '筛选弹窗：上传方式多两个、少一个', d: '「图床文件」的筛选弹窗里，上传方式按 Default → Upload → Fetch → StoreIn（异地存入）→ StoreOut（本地转出）→ API-Web → API-S3 → Record 排列，可以直接筛出「哪些文件是转存进来的、哪个方向」。WebDAV 这一项按需求撤掉；历史 WebDAV 文件的记录本身不受影响，详情页与系统状态的上传方式分布里仍然按原值展示。' },
        { t: '灯箱里的详情页：返回 / Esc 先关详情，再关灯箱', d: '以前在「本地文件」页打开灯箱、再从灯箱里点开文件详情页，手机上从边缘滑动返回会先把灯箱关掉，详情页反而留在屏幕上；桌面上按 Esc 也是同样的顺序。现在详情页作为独立一层压在灯箱之上：移动端一次返回只关最上面那层（详情页），详情页关掉之后再返回才关灯箱；桌面端按 Esc 先关详情页，没有详情页时才关灯箱。' },
        { t: '{filename} 占位符的字符清洗', d: '用「自定义文件命名」里的 {filename} 生成存储文件名时，会先清洗原始文件名：只保留文字（含中文）、字母、数字、“-”“_”“.”，其它符号一律清除；首尾空格去掉，中间的空格替换成“-”。这样文件名在对象存储、下载、转码环节都不会因为特殊符号出问题。清洗只作用于「存到渠道上的文件名」，数据库里的 originalName 仍然是原封不动的原始文件名，详情页与列表显示的都是原名。' },
        { t: '去重命中：以最新文件为准', d: '开启「上传去重」后，同内容文件再次上传不会再耗一份存储，而是复刻一条记录给你。现在复刻时会按最新这次上传更新数据：originalName 用这次上传的文件名（不再沿用旧记录的），标签把旧记录已有的标签与本次按「文件标签添加设置」规则生成的标签合并去重后一起写入，上传时间以本次为准，并在处理记录里加一组「重复文件复刻」，写明重复来源文件名、来源 File_ID 与复刻时间。其余数据（渠道副本、大小、MD5、分类）继续沿用原记录；外链、访问量、评分、备注这类个人状态本来就是新的一份。' },
        { t: '标签页放置久了回来不再白屏', d: '浏览器把标签页挂到后台很久（或手机息屏、电脑睡眠）后再切回来，以前偶尔会出现整页空白、必须手动刷新。现在从后台恢复会做三轮检测（1.2 秒 / 3 秒 / 6 秒），任意一轮发现页面还是空白就自动重载；恢复后如果仍停在加载态，还有一个 9 秒看门狗兜底。同时把「一次会话最多复活 3 次」改为「10 分钟内最多 3 次、页面稳定运行 2 分钟即清零」，正常页面不会被打扰，长时间使用也不会因为次数用完就再也不恢复。' }
      ]
    },
    {
      id: 'notes-moment',
      title: '二十八、v1.1.1 更新要点',
      intro: 'v1.1.1 开始做笔记板块，第一阶段只做不需要编辑器的「瞬间」—— 一段文字加几张图，像朋友圈那样记下此刻，为后面推进文章与编辑器打底。数据库新增 4 张表（notes / note_moments / note_assets / note_tags），只加不改，图床原有的上传、文件管理、标签、分享一行未动。前台只多了一个「记录」入口，笔记大厅与公开阅读页留到后面。',
      items: [
        { t: '新增「笔记管理」页与「记录」入口', d: '后台左上角的页面切换下拉里，「图床文件」下面多了「笔记管理」。页面是两行：第一行是页面切换、实例选择与「发布瞬间」；第二行是类型标签（全部 / 瞬间 / 待办 / 导航 / 文章 / 合集）、搜索、媒体类型、排序、回收站与刷新。排序只保留第二行这一处 —— 两个排序控件互相打架是很常见的坑，这里从一开始就只做一个。待办 / 导航 / 文章 / 合集目前是占位，点进去提示「该类型尚未开放」。前台首页上传方式标签旁边多了「记录」入口，这是本版前台唯一新增的东西。' },
        { t: '发一条瞬间：标题 / 心情 / 天气 / 位置 / 正文 / 附件 / 标签 / 可见性', d: '标题自动填「2026-11-10 周二 00:27」这样的日期时间，可改成任意标题（瞬间不单独占标题列，存在 metas 里）。心情 7 个表情、天气 7 个图标，点一下选中、再点取消。正文上限 500 字（可在设置里改，允许 50~20000），右下角实时计数。附件最多 50 个，可拖拽排序、也可用左右箭头微调，第一张是首图。标签可以从已有标签里选，也可以直接输入新建；新标签的类型是 note，与文件标签天然隔离。可见性选了「公开」后卡片上会显示角标，但本版只做后台自看自发，还没接前台公开列表。' },
        { t: '字数怎么算：只数汉字、字母、数字', d: '标点、空格、换行、emoji 一律不计 —— 写 500 字正文再加一堆标点也不会被拦。计算用按码点遍历的方式，emoji 与生僻字不会被算成 2 个字符。前端用来实时计数与「已超出 N 字」提示，后端做权威校验，两边是逐行等价的两份实现：如果口径不一致，就会出现「前端说没超、后端说超了」这种最难解释的问题。实测 501 字被拒，500 字 + 360 个标点通过。' },
        { t: '九宫格排版与灯箱', d: '1 张是居中的单张大图（4:3，约占宽度 62%）；2 张一行两个；3 张一行三个；4-9 张三列自动换行（4 = 3+1、5 = 3+2、7 = 3+3+1）；超过 9 张只显示前 9 张，第 9 张叠一个「+3」，点开灯箱能翻完全部附件。视频不预加载视频本体，用「播放角标 + 文件名」的封面卡，点开才在灯箱里播；音频是「音乐图标 + 文件名 + 时长」，时长由浏览器读元数据得到（并发 3、8 秒兜底、按 URL 缓存），不需要后端存字段。' },
        { t: '长文字自动收起：无附件 10 行、有附件 5 行', d: '超出才出现「全文」，点开看完整内容，再点「收起」收回去；没超出就不出现这个按钮。判断方式是挂载后临时摘掉 CSS 截断量一次真实高度，再和「行高 × 行数」比较 —— 只用 -webkit-line-clamp 是量不出「到底有没有溢出」的，会导致所有卡片都挂着「全文」（很难看）或者真溢出了却不显示（内容看不到）。窗口 resize 时防抖重测。因为单篇上限 500 字，桌面宽卡片一行能排 80 多字，10 行容量约 800 字，所以这条规则实际只在手机上会触发。' },
        { t: '回收站：彻底删除只删笔记，不删图床文件', d: '卡片右下角的删除是「移入回收站」，随时可以恢复；在回收站里再点「彻底删除」才真的删掉这条记录。彻底删除不会动图床里的那张图 —— 图片还在文件列表里，链接照常能打开。这也是 note_assets 刻意不建指向 files 的外键的原因：删图片不该被「还有笔记引用它」卡住，也不该反过来把笔记引用级联删掉。渲染时按当前有效的文件批量查一次，查不到的格子直接跳过，一条笔记坏一张图不该让整张卡片崩掉。' },
        { t: '附件记的是文件 ID：图床改名后瞬间里的图自动跟随', d: '瞬间的附件存的是 files.id，不是 objectPath、不是 remoteKey、更不是完整 URL。files.id 永不变，而 objectPath / remoteKey 会随转存变化，存完整 URL 等于把域名写死、换域名后历史附件全部 404。渲染时按当前的 FileRecord.name 现拼 /file/&lt;name&gt;，所以在后台把 nana.png 改名之后，瞬间里那张图自动指向新名字：新地址 200、旧地址 404，这一条是专门实测过的。' },
        { t: '实例隔离与权限', d: '和文件一样，瞬间挂在实例下：所有查询的第一行条件就是 instanceId，空串代表默认实例而不是「不过滤」，否则「默认实例」会变成「所有实例」。在别的实例里看不到，切换实例后列表跟着切，通过链接强行访问别的实例的瞬间返回 404。权限上必须登录才能用；普通用户只看得到、只改得动自己的；管理员在当前实例内能看到所有人发的。页面隐藏只是体验，后端才是真正的边界。' },
        { t: '这一版没有做的事', d: '文章 / 合集 / 待办 / 导航四种类型只有占位页签；前台「笔记大厅」「公开阅读页」只留了「记录」入口，进入的仍是同一个后台页；富文本编辑器还没有 —— 瞬间是纯文本，保留换行与连续空格，Vue 插值天然转义，不存在 XSS；公开可见性字段和界面都在，但还没接前台公开列表。' }
      ]
    },
    {
      id: 'notes-moment-112',
      title: '二十九、v1.1.2 更新要点',
      intro: 'v1.1.2 是「瞬间」从能用变成好用的一版：把编辑页与图床之间的往返打磨顺了（发布时上传的东西直接变成附件、链接能转存进来、关掉编辑页草稿还在），把卡片上的操作收进一个「更多」菜单并加了留言，把文件的「引用关系」摆到明面上 —— 被笔记引用的文件不再允许删掉。数据库只加不改：新增 note_comments 一张表，note_moments 补 moodName / weatherName 两列。图床原有的上传、文件管理、标签、分享逻辑一行未动。',
      items: [
        { t: '笔记管理页：顶栏按钮重新排了一遍', d: '顶栏右侧从右到左现在是：更多菜单 → 发布按钮 → 回收站 → 刷新 → 标签管理 → 搜索。回收站从原来的位置挪到「发布」前面，刷新挪到回收站前面，这样「会造成破坏的操作」始终离手边最远的右侧一次点击。搜索在桌面端是把输入框，在移动端收成一个放大镜图标：点一下在下方展开一行输入框，再点一次清空关键字并收起 —— 手机上顶栏本来就只有一条，塞一个常驻输入框会把类型标签挤成两行。' },
        { t: '发布按钮的文案跟着类型走', d: '「全部」和「瞬间」下写「发布瞬间」，「待办」下写「添加待办」，「导航」下写「添加导航」，「文章」下写「发布文章」，「收集」下写「添加收集」。按钮永远在类型选择下拉的左边：先选类型、再点发布，视线不用来回跳。尚未开放的类型按钮置灰并提示「该类型尚未开放」，不会点下去什么都不发生。' },
        { t: '移动端：类型之间左右滑动循环切换', d: '在内容区横向滑动就能在「全部 → 瞬间 → 待办 → 导航 → 文章 → 收集」之间切换，划到头会循环回来，不用去点上面的标签。判定要求位移超过 60px、横向分量至少是纵向的 1.5 倍，并且起手点不能是输入框、下拉框、类型标签条或任何标了 no-hswipe-guard 的元素 —— 否则在输入框里选字、在标签条里横向滚动都会被当成翻页。边缘 30px 内的起手不参与，留给系统的返回手势。' },
        { t: '移动端：两行栏目要滚一下才收起，且过渡与顶栏一致', d: '第二行功能栏随页面滚动收起 / 落回的动画，以前用的是默认过渡，和顶栏那种带一点回弹的曲线对不上，两条栏会有一条快一条慢。现在两处用同一条 transition 曲线。触发阈值也从桌面的 60px 单独拆出一套移动端参数（12px / 位移 1px 即判定），因为手机上一屏内容本来就短，滚 60px 才收栏会让人以为它坏了。' },
        { t: '实例切换移进页面切换下拉，与后台首页同一套', d: '以前实例切换是顶栏上一个独立按钮，笔记页和后台首页长得不一样。现在它作为下拉里的一项，排在页面列表下方、用一条分隔线隔开；每一项的名称前面带实例序号，默认实例不带序号，当前选中的打勾。选完写进 localStorage 的 gohub_instance_id，列表与后续发布都跟着换实例。' },
        { t: '顶栏最后的「更多菜单」', d: '「发布」右边现在是三点图标，菜单里依次是：我的账户、系统管理、一条分隔线、退出登录，最后是配色模式切换。桌面端与移动端是同一个菜单，移动端不再把这几项塞进抽屉里 —— 手机上要找「退出登录」得先点开抽屉、再滚动，实际使用中很难找。' },
        { t: '标签管理：进入后按分类切换，合并 / 拆分 / 属性都在', d: '顶栏新增一个标签图标，点开是标签管理面板：左侧是标签列表（带勾选框，可多选），右侧是选中标签的属性管理 —— 可以改名、写备注、保存；多选两个以上可以「合并」成一个（被合并标签下的笔记全部转到目标标签，数量相加，然后旧标签删掉）；单个标签可以「拆分」成多个（按输入的名字新建，原标签下的笔记同时挂到新标签上）；也可以直接删除（只解除关联，笔记本身不动）。分类上按「文件标签 / 笔记标签」切换，两边的数据完全隔离：文件标签不会出现在笔记上，反之亦然，合并时混类型会被拒绝。' },
        { t: '刷新按钮：以前点了像没反应', d: '根因是刷新直接调用了整页重载，把当页的标签筛选、搜索关键字一起清掉了 —— 你正在看「某个标签下的第 2 页」，点刷新后回到「全部类型第 1 页」，视觉上就是「什么都没发生但内容全变了」。现在刷新只清空列表、页码归 1、重新拉一次当前筛选条件下的数据，筛选条与搜索框原样保留；在标签管理面板里点刷新，重拉的是标签列表。' },
        { t: '瞬间编辑页：高度占窗口 96%，标题不再带时间', d: '编辑页从原来的固定高度改成 96vh 的弹性布局，正文区自己撑开、附件区自己滚动，屏幕越高写得越舒服。标题自动填充从「2026-11-10 周二 00:27」去掉时间点，只留「2026-11-10 周二」—— 瞬间是「一天里的若干条」，标题带分钟会让同一天的几条看起来像不同日子。已经手改过标题的不会被覆盖。' },
        { t: '心情 / 天气：点一下浮出名字，发布时把名字一起存下来', d: '心情是 7 个表情、天气是 7 个图标，光看图标常常分不清「这个云是阴还是多云」。现在点击时在图标上方浮出名称气泡，2 秒后自动消失，不打断连续选择。发布时除了 mood / weather 两个代号，还会把当时的中文名称写进 note_moments 的 moodName / weatherName —— 这一列是为了以后按「下雨天」「心情不好」筛瞬间，光存代号的话，以后改了图标集历史数据就再也解释不出来了。' },
        { t: '正文上限从 500 字提到 1000 字', d: '口径不变：只数中英文与数字，标点、空格、换行、emoji 都不算。上限值前后端各有一份，改的是同一个常量；实测 1001 字被拒（提示「正文超出上限：当前 1001 字，上限 1000 字」），1000 字再加 500 个标点通过。留言单独一套上限 500 字，与正文互不影响。' },
        { t: '位置输入框：保留，但浏览器会记住你输过的', d: '位置是一个可输入的自动补全框：点开就直接列出最近输入过的位置（最多 20 条，按最近使用排序、自动去重），输入几个字就在历史里模糊匹配。这份记忆按实例分开存在浏览器本地（localStorage），发布成功后把这次的位置提到最前面。选择它而不是「删掉输入框只留下拉」，是因为位置本身就是自由文本，硬做成固定选项等于逼用户去改配置。' },
        { t: '「图床选择」与「链接提取」：编辑页里直接拿图', d: '「从图床选择」改名为「图床选择」，按钮旁边新增「链接提取」：粘贴一个 http(s) 链接，服务端把它抓下来、走同一条上传链路存进图床，然后作为附件插进当前这条瞬间。两条路径都会先弹「目标渠道 / 归属实例 / 上传目录」，选完才真正开始，上传来源统一记为「附件上传（Attachment）」，所以事后在文件详情里能一眼看出这张图是随笔记进来的。' },
        { t: '关掉编辑页（含按 Esc）也不再丢草稿', d: '编辑过程中每隔 400ms 把当前内容（标题、心情、天气、位置、正文、附件、标签、可见性）写进浏览器本地，下次打开同一条瞬间的编辑页会提示「已恢复上次未发布的草稿」，可以一键丢弃。发布成功、或者主动点「丢弃草稿」才真正清掉。这条对移动端尤其重要：接个电话、切个应用回来，页面被系统回收过一次，写了一半的内容就没了。' },
        { t: '图床选择面板：96% 高度、滚到底自动加载、视频有缩略图', d: '面板高度与编辑页一致改成 96vh，列表去掉「加载更多」按钮改成滚动到底自动加载（距底部 160px 触发），首屏不满一屏时自动补拉下一页，不会出现「一进去就是空白等着你点按钮」。类型固定四档：图片 / 视频 / 音频 / 其他，默认「图片」——「全部类型」这一档被撤掉，因为它默认把视频和音频也混进来，选图时反而更难找。「其他」是既不是图片也不是视频音频的那些（文档、压缩包等）。视频格现在也显示缩略图：前端用 video 元素在 0.1 秒处抓首帧画到 canvas 上（并发 2、9 秒超时、最长边 480、按 URL 缓存），拿不到就退回原来的封面卡。' },
        { t: '缩略图左下角的小眼睛：按住看大图，放开关掉', d: '每个缩略图左下角有一个眼睛图标，按住（或鼠标按下）弹出 300px 的预览浮层，松开即关。浮层位置按按钮在屏幕上的位置择位：靠右就开在左边，靠左就开在右边，都不合适就居中，不会跑出屏幕。触摸时起手 300ms 内不判定，手指抖动 10px 以内不算移动 —— 手机上「按住」这个动作天然会带一点位移，阈值太紧会一按就取消。' },
        { t: '上传目录默认填 /瞬间/年份/月份', d: '从瞬间编辑页发起的上传，目标选择页的「上传目录」会预填当前的年月（如 /瞬间/2026/11），不用每次手敲。这个目录会跟着上传一起提交，文件列表里就按目录树归到「瞬间 → 2026 → 11」下面。顺带说明一个排查过的疑点：中文目录本身完全可用，早前用命令行测出 400 是因为 query 里的中文没有做 percent-encode（浏览器的 URLSearchParams 一定会编码），真正的请求返回 201，目录也正确落库。' },
        { t: '目标选择页抽成通用函数，以后所有上传都走它', d: '「选渠道 → 选实例 → 选目录 → 确认」这套流程从瞬间编辑页里抽出来，做成可传默认目录参数的通用能力，本地文件上传、灯箱上传、瞬间附件上传（以及以后文章里的上传）都调同一份。上传本身也统一成三个入口：单文件、分片 / 暂存、链接转存，各自只负责取字节，目录、实例、来源标签都由调用方传进来。这样「某个入口忘了带实例」这类问题不会再出现第二次。' },
        { t: '瞬间卡片：四个附件改成两行两个', d: '原来 4 张走三列，排成 3+1 —— 右下角空一格，看着像少了一张。现在 4 张固定两行两列，四宫格方正；其余张数（1 / 2 / 3 / 5~9）的排布不变。' },
        { t: '视频格：缩略图 + 中间不太大的播放图标', d: '卡片上的视频不再是一块纯黑底加文件名，而是显示首帧缩略图，中间叠一个 30px 的半透明圆底播放图标。图标刻意做小：它只是「这是视频」的提示，做大了会挡住画面本身。' },
        { t: '卡片右下角：删除键后多了一个「更多」，编辑和删除都收进去', d: '右键区现在是「更多（三点）」菜单：编辑 / 留言 / 删除，删除在最下面并单独分隔。以前编辑与删除是两个平铺的图标按钮，误触删除的风险不低 —— 删除虽然进回收站，但「点错了」这件事本身不该发生。回收站里的卡片则保留「恢复」「彻底删除」两个平铺按钮（这两个是高频且需要明确的操作），「更多」里只留留言。' },
        { t: '新增留言：每篇上限 500 字', d: '「更多 → 留言」打开留言面板：可以发、可以删自己的，按时间正序分页加载。字数口径与正文一致，只数中英文与数字，上限 500 字，超了即时提示并禁用发送。留言存在新建的 note_comments 表（noteId / content / charCount / author / instanceId / createdAt，按 noteId + createdAt 建索引），跟着笔记一起删、一起进回收站，不单独外露。' },
        { t: '灯箱：右上角「详情」在关闭按钮左侧分隔线之前', d: '灯箱右上角本来就是「…图标组 | 关闭」，现在详情按钮排在分隔线左边、紧挨着关闭，所有类型通用。点它不会关灯箱 —— 详情弹窗经 Element Plus 的层级提升叠在灯箱之上，看完关掉，灯箱还停在原来那一张，不用重新翻。打开详情时正在播放的视频 / 音频会自动暂停。' },
        { t: '灯箱：移动端下拉调出详情，边缘返回逐层关', d: '在灯箱里向下拉（超过 60px、纵向占主导）等于点「详情」，直接调出这张图的文件详情页；向上拉则随机切到同类型的下一条。返回键 / 边缘滑动由统一的浮层栈接管：一次返回只关最上面那一层 —— 详情开着就先关详情，详情关掉再返回才关灯箱，灯箱关掉之后再返回才离开页面。这条以前在笔记页是漏的（详情弹窗没登记到栈里，一返回就把灯箱关了、详情还挂在屏幕上），本版补上。' },
        { t: '文件详情页：新增「附件上传（Attachment）」来源', d: '通过内容发布（瞬间的图床选择、链接提取、本地上传）进来的文件，上传方式记为 Attachment，详情页显示「附件上传（Attachment）」。此前这两条路径因为都带 stagingId 而被一律记成 Fetch，事后完全看不出「这张图是随笔记进来的」。现在白名单内显式声明的来源优先于「暂存即 Fetch」的旧规则，对既有调用方零影响：前端上传页不声明来源仍是 Default，声明 Fetch 的调用方结果也不变。' },
        { t: '文件详情页：新增「文件实名」与「文件引用」', d: '「文件原名」后面多两行。「文件实名」展示 remoteKey 实际写到渠道上的文件名（不含路径）—— 改了存储命名规则之后，只有这一行能告诉你「服务器上那个文件到底叫什么」。「文件引用」显示这个文件被多少篇笔记引用，旁边一个「查看」按钮，新标签页打开引用明细页：列出每一篇引用它的笔记（标题、类型、状态、作者、时间），点标题直接跳到那篇。明细是独立页面而不是弹窗，因为这个列表可能要翻很多条，弹窗里滚很难受。' },
        { t: '删除文件前会检查引用，被引用就删不掉', d: '删除单个文件或整个目录时，若里面有文件正被笔记引用，删除会被拦下并明说「该文件已被笔记引用，无法删除。引用它的笔记：标题 A、标题 B。请先删除对应笔记后再试」。以前的行为是把图删掉、笔记里留一个打不开的空格 —— 一条笔记坏一张图不该由用户在事后发现。批量删除时会把所有被引用的文件一次性列出来，而不是删一半再报错。想删就先删笔记，或者先把附件从笔记里摘掉。' },
        { t: '首页「记录」：从跳转链接改成五个可直接动手的图标', d: '「记录」以前是个链接，点进去还是后台那个笔记页，等于绕一圈。现在它是一块虚线操作区，里面并排五个 1:1 的正方形图标：瞬间 / 待办 / 导航 / 文章 / 收集。点「瞬间」直接在首页弹出瞬间编辑页，发布成功后这条内容立刻出现在下方列表里，刷新页面才清零 —— 这样发完能马上确认「刚才那条长得对不对」，不用再跳去后台。待办 / 导航 / 文章 / 收集四个编辑页还没做，图标降饱和度显示并提示「该类型尚未开放」，不做假的空页面。' },
        { t: '首页三按钮的移动端内边距，以及一条多余的分隔线', d: '「文件 / 链接 / 记录」三个标签在手机上的内边距调小了一档，三个能在一行里排开不用挤。「链接」与「记录」之间原本有一条竖分隔线，而「记录」已经不是页面跳转而是同一页面内的模式切换，这条线会让人以为它们是两类东西，已移除。' },
        { t: '数据库变更：只加不改', d: '新增 note_comments 一张表（留言）；note_moments 补 moodName、weatherName 两列（默认空串，历史数据不受影响）。没有修改或删除任何既有列，图床的上传、文件管理、标签、分享相关表一行未动。升级时 entrypoint 的建表清单已经带上 note_comments，容器起来会自动补齐。' }
      ]
    },
    {
      title: '三十、v1.1.2.1 更新要点',
      intro: 'v1.1.2.1 只做两件事：给笔记加一个「笔记设置」，让附件区的大小和位置能按实例调；把文件的「引用」统计从「只算笔记」扩到全类型（笔记 + 分享）。没有新增数据表，设置存在既有的 settings 表里，图床的上传、文件管理、标签、分享逻辑一行未动。本版只出源码，不构建镜像。',
      items: [
        { t: '笔记设置入口：顶栏更多菜单，退出登录的上一行', d: '「更多菜单」里现在是：我的账户 → 系统管理 → 笔记设置 →（分隔线）退出登录 → 配色模式切换。「笔记设置」紧挨在退出登录上方，因为两者都是「离开当前页面之前才会想起来的操作」，放在一起比散在两端好找。' },
        { t: '设置按实例区分，不同实例互不影响', d: '一份设置属于一个实例：在默认实例里把附件区调成「左对齐 + 40%」，切到另一个实例仍然是那一套的默认布局，切回来又是刚才调好的样子。与文件、标签、笔记的隔离口径完全一致。设置存在 settings 表，键名是 note-settings:<实例 id>（默认实例用 ~default），值是一段 JSON —— 以后加「待办设置 / 导航设置 / 文章设置 / 收集设置」只需在同一个 JSON 里多挂一个键，不用改表结构。' },
        { t: '附件加载区域大小：默认 / 指定比例', d: '选「默认」就完全保持现在的九宫格布局，一个像素都不动。选「指定比例」时下方出现「附件占页面最高比例」输入框（5% ~ 80%，默认 30%），这个比例指的是「附件显示三行时」的总高度；两行时按 80% 折算，一行时按 60% 折算。行数按附件数量决定：7 个及以上三行、4~6 个两行、1~3 个一行；4 个附件固定两行两列，其余每行最多 3 个。' },
        { t: '格子始终是正方形，宽度跟着高度算', d: '每个附件的宽高恒为 1:1：先由「页面高度 x 比例 x 行数系数」算出总高度，扣掉行间距后按行数平分得到行高，行高就是格宽，整块宽度再由列数反推出来。所以设定 30% 时，附件区实际占用的高度就是页面的 30%（三行时），不会因为图片本身的长宽比而走样。窄屏上算出来的宽度可能超过卡片宽度，此时按 100% 铺满、格子等比缩小 —— 需求要的是「最高比例」，小于它是允许的。' },
        { t: '页面高度按可视区算，实时换算写在设置页里', d: '「页面高度」取的是浏览器可视区高度（window.innerHeight），不是某个容器的高度 —— 这样笔记页、以后的公开页口径一致，换设备也不会算出两套结果。设置页在输入框下面直接给出当前窗口下的实际尺寸（三行 / 两行 / 一行各多少像素），改比例时数字跟着跳，不用保存后回列表去试。' },
        { t: '换算结果存 Cookie，同尺寸下不再重算', d: '这组示例数字（比例 + 视口高度 → 三个高度值）会写进浏览器的 Cookie：比例和窗口高度都没变时，下次打开设置页直接显示上次的结果，不重新计算。清空 Cookie 或者换了窗口尺寸才会重算并回写。设置本身也同步存了一份在 Cookie 里 —— 页面加载时先按它把附件区尺寸摆好，再向服务端要最新值，这样首屏不会先闪一下默认布局再跳成你设定的样子。服务端始终是唯一事实来源，Cookie 只负责首屏那一下。' },
        { t: '附件加载位置：默认居中 / 左对齐', d: '选「默认」保持现在居中的布局；选「左对齐」时附件区与正文左边缘对齐，不再居中。单张图（默认布局下是 62% 宽度、居中）也会跟着靠左；在「指定比例」模式下整块本来就窄，居中与左对齐的差别最明显。' },
        { t: '其余的待办 / 导航 / 文章 / 收集设置暂未开放', d: '设置页左侧列出五个分类，只有「瞬间设置」可点；其余四项置灰并标「即将开放」，点了不会有反应，也不做一屏空白面板糊弄过去。这些分类要等对应类型的编辑页做出来之后才有意义。' },
        { t: '文件引用：统计口径从「笔记」扩到全类型', d: '文件详情里的「文件引用」数量以前只算「被多少篇笔记当附件用」，现在把图床的分享链接也算进去：文件所在的目录被分享、或者文件挂着被分享的标签，都算一处引用。明细页里每条引用前面会标明来源（笔记 / 分享），并给出「N 条笔记 · M 个分享」的小计，两边都占时详情页也会显示这个拆分。' },
        { t: '但只有笔记引用会拦住删除', d: '分享引用是「筛选式」的：文件被某个目录分享覆盖，删掉它只是让那个分享里少一个文件，不会破坏任何内容；而笔记附件是硬引用，删了笔记里就会缺一张图。所以删除校验只认笔记 —— 否则一旦把根目录分享出去，全库文件都会变成「被引用」，连换张图都删不掉。这条是刻意的取舍：拦的是「删了会坏的东西」，不是「删了会少一个入口的东西」。' }
      ]
    },
    {
      title: '三十一、v1.1.2.2 更新要点',
      intro: 'v1.1.2.2 只调整「瞬间」长什么样：单个附件按原图比例显示，笔记设置里多了排版样式和附件行数，正文字数不再按行数截断而是按高度。没有数据库变更，没有新增表，图床主体功能一行未动。本版只出源码，不构建镜像。',
      items: [
        { t: '单个附件：改为按原图宽高比，不再裁成正方形', d: '以前只有一张图也会被塞进 1:1 的方格里，竖图、全景图都会被裁掉两头。现在单个附件按原图的宽高比显示：总高度 = 页面高度 x 设定比例 x 70%（三行是 100%、两行 80%、一行 60%，单个是 70%，都是同一个比例的折算），宽度 = 高度 x 宽高比。图还没加载完时先按 4:3 占位，拿到真实尺寸后立刻校正，不会跳两次。选「默认」布局时没有「设定比例」可依，就沿用原来「宽度约卡片 62%」的观感，高度由宽高比反推，并用 45% 视口高度封顶 —— 否则一张竖图会有 800px 高，直接顶满一屏。' },
        { t: '两个及以上：仍然是正方形，但宽度不够就按加载区宽度收', d: '格子的边长照旧由「总高度 ÷ 行数」得出，保持 1:1。区别在于多了一步宽度校验：如果算出来的一行总宽超过卡片可用宽度，就用可用宽度反推格子边长，收完仍然是 1:1，不会出现「宽度撑破卡片、格子被拉成长方形」的情况。可用宽度是实测出来的（跟着卡片走，窗口缩放会重新算），不是写死的数字。' },
        { t: '新增「内容排版样式」：默认样式 / 分割线样式', d: '选「默认样式」保持现在每条内容一张带边框的卡片。选「分割线样式」时把外边框整圈去掉，改为在每条内容下方画一条分割线，颜色与原来的边框线一致；卡片底色和阴影也一起去掉，否则相邻两条之间会露出两块色块，看着不像分隔。列表最后一条不画线，否则列表末尾会多出一道悬空的线。' },
        { t: '新增「附件数量加载」：三行 / 两行 / 一行', d: '只决定「显示几个」，不改变尺寸：加载三行最多 9 个（原有行为）、加载两行最多 6 个、加载一行最多 3 个。超出的部分照旧在最后一格叠「+N」，点开灯箱还能看全部。尺寸始终按上面的「附件加载区域大小」执行。' },
        { t: '附件间隔调小，附件与卡片的圆角统一成 5px', d: '九宫格的格间距从 4px 收到 3px，附件看起来更紧凑。附件格的圆角从 8px 收到 5px，每条瞬间内容的外边框圆角从 12px（移动端 10px）统一收到 5px —— 两端一致，也不再出现「卡片圆角很圆、里面的图很方」的落差。' },
        { t: '瞬间标题的颜色改成与时间一致', d: '以前标题用正文级的深色、时间用弱化的灰色，两者挨在一起会有主次错位的感觉。现在标题与时间同色，靠字号和粗细区分主次，视觉上更安静。' },
        { t: '纯文字正文改为按高度截断（页面高度的 30%）', d: '以前是按行数截断（无附件 10 行、有附件 5 行），同样行数在不同宽度的屏幕上占的高度差很多，一条长文在窄屏上能顶掉大半屏。现在改为固定口径：正文区最高不超过页面高度的 30%，超过才显示「全文」按钮，点开可展开。这个比例是固定的，不放进笔记设置 —— 只算正文本身，标题、心情天气、附件和按钮都不计入。' },
        { t: '设置的写入改成「按分类合并」', d: '以前保存设置时，只要提交的对象里缺某一项，那一项就会被当成「没填」打回默认值。现在每个分类内部也做合并：只提交你要改的那一项，其余字段保持原样。这样以后加新的设置项、或者某个页面只改一个开关，都不会顺手把同一分类里的其它配置清掉。' },
        { t: '数据库与其他模块', d: '本版没有新增表、没有新增列：排版样式和附件行数都是挂在既有 settings 表那段 JSON 里的新键，历史数据里没有这两个键时会落到「默认样式 + 三行」，与升级前完全一致，不需要数据迁移。图床的上传、文件管理、标签、分享逻辑一行未动。' }
      ]
    },
    {
      title: '三十二、v1.1.2.3 更新要点',
      intro: 'v1.1.2.3 把「瞬间」的默认观感一次调到位：设置里的出厂默认换成指定比例 35% / 左对齐 / 分割线样式 / 加载两行，附件高度按个数重新折算，留言从弹窗改成直接挂在卡片底部并且能像朋友圈那样点谁回复谁。没有数据库变更、没有新增表，图床主体功能一行未动。本版只出源码，不构建镜像。',
      items: [
        { t: '设置的默认值全部换了一套', d: '「附件加载区域大小」的默认项从「自动比例」改为「指定比例」，另一个选项（原来的「默认（保持现有布局）」）改名为「自动比例」；「附件占页面最高比例」默认 30% → 35%；「附件加载位置」的默认项从「居中显示」改为「左对齐」；「内容排版样式」的默认项从「边框样式」改为「分割线样式」；「附件数量加载」默认三行 → 两行（最多 6 个）。点「恢复默认」回到的也是这一组：指定比例 / 35% / 左对齐 / 分割线样式 / 加载两行。单选顺序按「当前默认项排第一」重排，打开设置就能看到生效中的那一项。' },
        { t: '旧设置不会被升级顶掉', d: '默认值只在「这一项没有存过」或者「存的值不合法」时才生效。已经明确保存过的值原样保留 —— 比如某人在 v1.1.2.2 里选过「边框样式 + 三行」，升级后仍然是边框样式 + 三行，不会被悄悄改成新的默认值。要换回新默认，点一下设置页的「恢复默认」即可。' },
        { t: '附件高度按个数重新折算', d: '「指定比例」模式下的折算系数改了：一行 1 个按 80%、一行 2 个按 70%、一行 3 个按 60%、两行（4~6 个）按 80%、三行（7 个以上）按 100%。口径是「实际显示个数」而不是附件总数：设置成「加载两行」时，9 个附件只显示 6 个，就按两行的 80% 算，被折叠的部分不占高度。默认 35% 时，视口 900px 下三行总高 315px、两行 252px、一行 189px。' },
        { t: '单个附件 70% → 80%', d: '只有一个附件时仍然按原图宽高比显示，不再裁成正方形；总高度从「视口高度 x 比例 x 70%」提高到 80%，所以同样 35% 的比例下，单图会比上一版高出约 14%。「自动比例」模式的计算完全没动，还是「宽度约卡片 62% + 45% 视口高度封顶」那套。' },
        { t: '附件圆角统一成 3px', d: '九宫格里每个附件的圆角从 5px 收到 3px，卡片外框的 5px 圆角保持不变 —— 于是「卡片圆一点、附件方一点」，界限更清楚。' },
        { t: '文字区限高：从卡片顶边算到「全文」按钮那一行', d: '口径从「正文本身不超过页面高度的 30%」改为「整块文字区不超过 30%」：从卡片的顶部边框 / 分割线开始算，到正文下方「全文 / 收起」按钮那一行为止，标题行、心情天气、正文、按钮都算在内；附件区、底部操作行、留言区都不计入。带附件的瞬间与纯文字瞬间同一个口径，于是「一条很长的图文」也不会把附件挤到屏幕外。' },
        { t: '留言不再开弹窗，直接挂在卡片底部', d: '以前「更多 → 留言」会打开一个独立的留言弹窗。现在留言直接显示在卡片里 ⋯ 按钮那一行的下面，像朋友圈一样：每条以「用户名称：内容」开头，名称有单独的颜色，正文跟在后面。没有留言的瞬间不显示这一块 —— 每条卡片底下都挂一行「还没有留言」太吵。' },
        { t: '留言区默认只占页面高度的 20%', d: '留言多的时候，留言区最高占视口高度的 20%，超出的部分先收着，下方出现「更多留言（N 条）」，点开后铺满全部留言，再点「收起」收回去。留言特别多（单条超过 100 条）时，点「更多留言」会先把剩下的从服务端补拉回来再展开，不会出现「明明 200 条却只看到 100 条」的情况。' },
        { t: '点哪条留言就回复哪条', d: '点任意一条留言，卡片下方展开输入框，占位文字变成「回复 @某某：」，发出去的内容以「回复 @某某：」开头。显示时这个前缀会被单独解析出来、把「回复 @某某」渲染成与名称同色的高亮，而不是混在正文里。这里没有给留言表加 parentId 列：朋友圈本身就是把「回复 @某某」写在留言正文里的，加一列就要写迁移、升级时用户得先跑一次数据库迁移，为一个展示效果付这个代价不划算。' },
        { t: '留言输入框在移动端不再被挤窄', d: '输入框固定 width: 100% + box-sizing: border-box，跟着卡片内容宽度走；手机上字号 14px、内边距收一档，长留言能正常换行，不会出现「输入框只占半宽、右边空一大块」的样子。桌面端 Enter 换行、Ctrl / ⌘ + Enter 直接发送。' },
        { t: '留言随列表一次取回，不再一卡一请求', d: '列表接口现在会带上每篇瞬间的留言（按时间正序，单篇最多 100 条）与留言总数，一条 SQL 取回整页数据再按笔记分组，一页 20 条也只多两次查询。以前如果让每张卡片自己去拉留言，一页就是 20 个请求，滚动时列表会明显发涩。发表与删除成功后就地更新卡片上的留言，不必整页重载；列表重新拉取时以服务端数据为准。' },
        { t: '数据库与其他模块', d: '本版没有新增表、没有新增列、没有迁移：留言仍然是 v1.1.2 建的 note_comments 表，回复关系写在留言正文的前缀里。图床的上传、文件管理、标签、分享逻辑一行未动，只读取了既有的 note_comments。' }
      ]
    },
    {
      title: '三十三、v1.1.3 更新要点',
      intro: 'v1.1.3 做了三件大事：把「本地文件」这一套叫法统一成「挂载文件 / 挂载管理」；把「选择文件」面板重做成「图床文件 / 挂载文件」双数据源并补齐筛选、搜索范围、预览；给实例加了一把「切换密码」的锁。首页的「记录」模式也接进了左右滑动的循环，笔记管理页若干处观感与行为按图床管理页对齐。数据侧只动了一处：瞬间标题从扩展字段搬到独立列。',
      items: [
        { t: '叫法统一：本地文件 → 挂载文件 / 挂载管理', d: '渠道设置里的「本地文件」渠道改名为「挂载文件」，内置渠道（id 999990）在初始部署时叫「挂载文件-默认」；本地文件管理页标题与后台所有页面左上角页面切换里的「本地文件」都改为「挂载管理」，「图床文件」改为「图床管理」。只改给人看的字符串，渠道类型值、接口路径、数据库字段一律没动，老配置与老链接不受影响。已经部署过的环境，内置渠道若仍叫历史默认名（「本地文件」「本地文件-系统」等）会在重启后自动改成新名字；用户自己改过的名字不会被覆盖。' },
        { t: '笔记管理页：顶栏与搜索', d: '顶栏顺序改为「发布 → 搜索 → 标签管理 / 刷新 / 回收站 → 更多菜单」，按钮高度统一，「配色模式」挪到「我的账户」上面。桌面端搜索框复刻图床管理页：搜索范围下拉嵌在输入框起始位置，右侧是清空与搜索两个图标按钮，点进搜索框会变宽一点。搜索支持 #标签 与 -#标签（排除），解析放在后端，前端、接口、以后的小程序共用同一份语义。新增搜索范围：全部 / 标题 / 正文 / 标签 / 其他；不传范围时按「全部」，老请求行为不变。' },
        { t: '笔记管理页：手机上的搜索行', d: '手机上点搜索图标，搜索框现在出现在顶栏下方的独立一行，并且和桌面端一样带搜索类目下拉（全部 / 标题 / 正文 / 标签 / 其他）、清空与搜索按钮。做法是把顶栏改成纵向排列：第一行（页面切换 + 按钮组）是一个独立的行容器，搜索行是它的下一个兄弟，展开与否都不参与第一行的排列计算——之前两者在同一个可换行的 flex 容器里，搜索行一出现就会让第一行重排、按钮整体位移。同时修掉一处一直没生效的高度同步：模板根节点前面有一段注释，组件被当成 Fragment，取到的根节点是注释节点，高度变量从来没写进去，第二行工具栏一直用 60px 默认值——搜索行展开后顶栏长到 95px，工具栏还钉在 60px，类型标签行就被盖住了；改用页面根 div 后两行高度始终对齐。', },
        { t: '笔记管理页：发布与类型', d: '分类停在「全部」时，按钮文案变成「发布笔记」，点击先弹类型选择页（瞬间 / 待办 / 导航 / 文章 / 收集）；后四种尚未实装，仍然列出来但显示为灰色并注明。类型下拉的「请选择」改为「全部类型」——根因是下拉组件把空字符串当成「未选」，换成显式哨兵值就好了。「纯文字」改名为「文字」。' },
        { t: '笔记管理页：三处观感修复', d: '① 左上角「切换实例」不再跌出下拉背景板：背景高度改由下拉组件自己按「页面项数 + 额外项数」算，页面不再各补各的，移动端实例序号角标也从右上改到图标左上；② 切换实例把页面滚回顶部时，两行顶栏之间偶发的发丝缝没有了 —— 高度测量从取整的 offsetHeight 改为保留小数的 getBoundingClientRect，并在切换后等布局稳定再测一次；③ 点「留言」不会再让整条瞬间消失：不再强制展开留言区，聚焦时禁止自动滚动，只把它挪到视野内。' },
        { t: '笔记管理页：加载与灯箱', d: '灯箱里的文件详情改为与图床管理页同一个构造函数 + 同一个弹窗组件，下载、删除、改名都能用，不再出现「这页少字段、那页齐全」。缩略图加了磁盘缓存（同一张图只处理一次，并发请求会合并），前端加了三级重试，灯箱翻页会预取相邻同类型图片 —— 偶发的「加载失败刷新又好」和翻页卡顿都在这一步处理掉了。' },
        { t: '瞬间编辑页', d: '输入框提示改「写点什么，或发个照片」并左对齐；附件支持长按拖动排序（触屏按住约 0.3 秒，轻微振动后可拖）；心情 / 天气的名称提示改到图标上方、选中底色加强，手机端改成左右两个下拉页（「设置心情」「设置天气」，选项带图标与名称，一行两个）；手机上三个上传按钮收边距并改为横滑，保持一行。' },
        { t: '选择文件面板：双数据源', d: '瞬间编辑页的「图床选择」按钮改名为「选择文件」。面板顶部新增「图床文件」「挂载文件」两个按钮：图床文件是原来的模式（默认）；挂载文件读取「挂载管理」里的目录，挑完点「上传到图床」会先弹「目标渠道 / 归属实例 / 上传目录」，确认后自动上传并把文件加进附件。两种来源的文件标识语义不同，所以切换来源会清空已选。' },
        { t: '选择文件面板：筛选与搜索范围', d: '图床文件模式下，搜索框起始位置内嵌搜索范围，范围为「全部 / 标题 / 标签 / 分类 / 用户 / 备注 / 其他」，与图床管理页完全一致；搜索框后面加筛选按钮，点开就是图床管理页那套筛选弹窗（文件类型、访问状态、黑白名单、审查结果、标签、日期、大小、尺寸、评级等），用了几个条件按钮上就显示数字。为了「一样的范围」不是两套实现，筛选的求值逻辑被抽成一份共享模块，图床管理页与选择文件面板调同一份代码。' },
        { t: '选择文件面板：小眼睛预览', d: '预览框顶部显示文件名；视频自动播放且带声音；音频也加了小眼睛并自动播放；预览框长宽比按文件自身尺寸来（取不到比例的才用默认方形）；浮层会自动挑选四周空间最大的方位弹出，并保证整体落在按钮之外，不遮挡小眼睛。' },
        { t: '归属实例自动定位', d: '从本地选文件、或从挂载文件里选文件上传时，「归属实例」自动定位到当前所在的实例；即使弹窗里没动这一项，提交时也会兜一层当前实例。' },
        { t: '首页：记录模式接入滑动循环', d: '左右滑动在「文件 → 链接 → 记录 → 文件」之间循环（原来只能在文件与链接之间来回切）。三种模式的操作区（虚线框）宽高与位置完全一致，切换时三个按钮一动不动、页面也不会多出滚动条；切到记录页不会再残留链接模式的粘贴输入框。「记录」的入口图标改小了并随操作区宽度自适应：桌面一行 4 个、移动一行 3 个，不满的最后一行居中。在记录模式发完的笔记会出现在下方的文件列表区，列表会自动展开。' },
        { t: '实例属性与切换密码', d: '实例列表在「邀请」后面新增「属性」按钮，原「改名」移入属性页。属性页可设实例名称、备注，以及「切换密码」——三选一：账户密码、两步验证动态码、自定义独立密码。启用后，从首页、图床管理页、笔记管理页切换到该实例需要先验证；只要任意一个页面验证过，其他页面刷新时不再追问。自定义密码留空表示「不修改」，改个名字时不必重输密码。' },
        { t: '视频灯箱：放大后滑动改为移动画面', d: '视频双指放大之后，滑动是移动画面本身，不再切上一个 / 下一个，也不触发上拉随机播放；缩回原始大小后恢复正常。' },
        { t: '下拉页滚动自动收起', d: '手机端六处下拉页在滚动页面时会自动收起：笔记管理页的类型选择、排序、右上更多菜单，后台左上角页面切换，图床管理页的排序与目录路径选择。' },
        { t: '数据库：瞬间标题独立成列', d: '瞬间标题原来塞在笔记表的扩展字段（JSON）里，按标题搜索只能对整段 JSON 做模糊匹配，既可能命中别的字段，也用不上索引。本版把它搬到 note_moments.title 独立列（默认空串），写入、读取、搜索范围「标题」全部改走这一列；「全部」范围仍保留对扩展字段的匹配，兜住老数据。升级不需要手工操作：容器启动时先跑一遍兼容脚本，它会补出该列并把老数据里的标题回填过来，随后照常同步表结构；回填是幂等的，重复启动不会重复写。清空标题也可靠——不再从旧 JSON 里兜底，否则清空后旧值会被重新读出来。' }
      ]
    },
    {
      title: '三十四、v1.1.4 更新要点',
      intro: 'v1.1.4 是一次「收口」版本：把共享文件的权限边界划清（别人的共享文件只能看，不能改），把笔记彻底变成私有（按用户 + 实例双重隔离，管理员也看不到别人的），修掉挂载视频上传后损坏这个真 bug，再把移动端灯箱、下拉页、瞬间卡片这些日常高频操作的手感逐项磨平。数据库没有新增表、没有新增列，升级不需要迁移；图床的上传 / 去重 / 存储通道逻辑除了那个损坏修复之外一行未动。',
      items: [
        { t: '共享文件：美化编辑只属于拥有者', d: '别人共享给你的文件，在详情页里只看得到预览、下载、直链这些「看」的操作。裁剪、压缩、转 WebP、异地互转、存入本地这一整块媒体编辑区，以及顶部那个「转存」按钮，对非拥有者一律不显示；连它的两个数据请求（转存渠道选项、媒体信息）也不再发出去，不会出现「按钮藏了但接口还在调」。判定只看接口返回的 shared / sharedSelf 两个标记，不需要前端再猜一次归属。' },
        { t: '首页：拍照按钮整块移除', d: '首页左下角快捷栏里的「拍摄」按钮连同它背后的摄像头弹窗、前后摄切换、变焦、系统相机兜底等全部代码一起删掉，全局样式里那一整段拍照弹窗样式也清了。用手机相册 / 文件选择的入口不受影响，只是不再从网页里直接调摄像头。' },
        { t: '笔记私有：按用户 + 实例双重隔离', d: '笔记列表、详情、编辑、删除、留言删除、标签候选、标签管理计数，全部改成无条件以「当前登录用户 + 当前实例」收窄。管理员的身份不再带来任何可见范围上的例外 —— 后台笔记管理页里也只看得到自己的笔记，看不到别人的。这一层收在服务端：即使直接调接口，也拿不到别人的数据。升级后原有笔记自动只对作者本人可见，不需要任何数据迁移。' },
        { t: '移动端笔记灯箱：边缘滑动改为「关灯箱」', d: '以前从屏幕左右边缘往里滑，灯箱不关、页面却后退一格，等于同时干了两件事。现在改成：边缘横滑（超过 26px 起手、64px 判定）先把灯箱关掉，同时吞掉这次手势、禁止页面后退，一次手势只做一件事。手势落点在输入框、下拉框、类型标签条这些元素上时直接放行，不影响原来的交互。' },
        { t: '瞬间卡片：视频不再有边框和背景框', d: '九宫格里的封面如果来自视频且已有海报图，就去掉那层底色与内边距，让海报图铺满整格，与图片格子的观感一致；没有海报图时才保留占位底色。' },
        { t: '瞬间卡片：「全文」按钮回到文字末尾', d: '正文超过限高时，「全文」不再另起一行顶在左下角，而是浮在最后一行文字的末尾（用一块等宽行内占位把末行缩短，按钮绝对定位在右下），读起来像句子自然收尾；展开后「收起」按钮仍单独一行。' },
        { t: '瞬间编辑页：默认上传目录自动带年月', d: '点「本地上传」选完文件，进到上传目标页时「上传目录」已经填好 /notes/瞬间/{年}/{月}；「挂载文件」上传到图床时同样自动填这一路径。年月取当前时间，和已有笔记目录的习惯保持一致，不用每次手打。' },
        { t: '挂载视频上传后损坏（本版重点修复）', d: '现象：从「挂载文件」里选一个视频上传，图床里能看到记录、大小也正常，但点开是 404 / 无法播放。根因是后置压缩（转码 / 压缩）产物的对象 key 与原文件相同 —— 默认命名模板取的是原文件 MD5，压缩改了内容却没改 MD5；而本地上传用的是硬链接，写同名文件等于直接改到源文件，随后「删除旧对象」又把刚写好的产物删掉，磁盘上只剩一个没人引用的原位文件。修复分三处：产物 key 与旧 key 相同时自动换一个唯一名；删除旧对象前先比对新旧 key，相同就不删；本地存储适配器在落盘前探测目标是否已存在，已存在就换唯一名，硬链接报 EEXIST 时重试一次再退回复制。' },
        { t: '小眼睛预览不再重复下载', d: '挂载文件模式下，小眼睛预览以前会拿原始文件地址重新下一遍，明明格子里缩略图已经加载完了还要再等一次。现在直接复用已经缓存的那张缩略图，点开即显。' },
        { t: '本地上传：放开文件类型', d: '发布瞬间时的「本地上传」不再限制只能选图片 / 视频 / 音频，任何类型都能选；确认后照常进入上传目标页。' },
        { t: '瞬间编辑页：只有上传方式那一行可以横滑', d: '页面上只有「图床选择 / 本地上传 / 链接提取」这一行允许左右滑动，其余区域（正文、附件、心情天气等）一律取消横向滑动，避免手指在正文里横划时整页跟着晃。' },
        { t: '首页：切到「文件」模式不再闪一下', d: '滑动切换模式时会有一段淡入反馈，原来用 opacity 0.35→1 做动画，而卡片本身基础透明度就是 0.7，动画把 opacity 顶到 1、结束又跳回 0.7，肉眼就是虚线框底色闪一下。改成 filter: opacity() 过渡（与原透明度相乘），起点更淡、终点回到原样，全程没有突跳。' },
        { t: '首页：白天模式操作区底色与「链接」对齐', d: '「链接」模式的操作区是 el-card，吃全局的玻璃底规则（白色 45%）再叠 0.7 透明度，实际约 31% 白；「文件」和「记录」是普通 div，底色走实色 #FAFAFB 叠 0.7，约 70% 灰，看着明显更「实」。白天模式下让这两页也走同一个玻璃底，三者现在完全一致（「记录」没有整体透明度，用 color-mix 自己乘一次 70%）。夜间模式不动。' },
        { t: '渠道设置：添加按钮改成右下角悬浮圆钮', d: '「+ 添加渠道」从页头挪到右下角固定圆形悬浮按钮，默认只显示「+」；桌面端鼠标移上去自动向右展开「添加渠道」文字，移动端保持纯图标（并让开底部安全区）。原来页头那个按钮已删除，功能与弹窗完全一致。' },
        { t: '视频灯箱：记住上次播放到哪儿', d: '关闭视频灯箱时把播放进度存进浏览器（localStorage，按文件名 + 地址做键），下次打开同一个视频，在下方「目录」与右侧「设置」中间会浮出一行提示「上次播放记忆在 12:34」，点「跳转」直接续播，点「忽略」收起提示、本次不再打扰。看完的（结尾 3 秒内）和刚开头的（3 秒内）不记录，避免每次都弹一个没意义的提示。翻页、暂停、关闭都会落地一次进度。' },
        { t: '移动端后台：更多菜单也跟着滚动收起', d: '上一版已经让六处下拉页在滚动时收起，但右上角「更多菜单」在分享页、账户设置等页面仍是常开。这一版把它补到所有后台页共用的顶栏组件上；同时把滚动收起的监听从「只听 scroll」升级为 scroll + 手指拖动 + 滚轮三路 —— iOS 在惯性滚动期间根本不派发 scroll，只靠它会出现「下拉页一直挂着、松手才消失」。手指落在下拉页自身的列表里滑动不触发收起，刚展开的 60ms 内也不响应，避免 Element Plus 打开时自己做定位导致「开了就关」。' },
        { t: '数据库与其他模块', d: '本版没有新增表、没有新增列、没有迁移：笔记私有化只是在查询条件里多带一个作者字段（本来就有），共享文件的权限判定用的是既有的 shared / sharedSelf 标记，播放进度存在浏览器本地。升级直接覆盖代码即可，旧数据、旧链接、旧分享都不受影响。' }
      ]
    },
    {
      title: '三十五、v1.1.4.1 更新要点',
      intro: 'v1.1.4.1 只有一件事：把「图床管理页」在手机上顶部那两行工具栏改成通栏贴边的整块样式。原来两行都带圆角、左右各留一点缝、上下还各有几像素的间隔，看起来像两块浮在页面上的卡片；改完之后它们从屏幕最左贴到最右、第一行直接顶到屏幕顶部、第二行紧接在第一行下面，两行连成一整块。桌面端、平板端以及其它后台页面的顶栏全部维持原样，这次改动没有碰任何数据与接口。',
      items: [
        { t: '第一行（顶栏）：去圆角、贴顶、通栏', d: '手机上第一行原来是圆角 14px、左右各留 4px 缝、距屏幕顶部 2px。现在圆角归零、左右直接贴死屏幕两侧（宽度 100%）、上边贴死页面顶部（间距 0）。背后那层玻璃背框（带 1px 描边和投影的那层）跟着一起去圆角，并收回原来的 1px 外扩，避免通栏之后在屏幕边缘多出 1px 的溢出。' },
        { t: '第二行（全选那一行）：去圆角、贴边、紧贴第一行', d: '第二行原来圆角 5px、左右各内缩 10px。现在同样是圆角归零、左右贴死屏幕两侧，并且与第一行之间的缝隙清零，两行上下一贴，视觉上就是同一块面板的上下两层。上下内边距同时各加 2px（4px 改为 6px），行内的按钮和图标不会显得被压扁。' },
        { t: '两行的内容位置：第一行不变，第二行更贴边', d: '背景通栏之后，原来由「顶栏左右各 4px 缝」和「内容区左右各 10px 内边距」让出来的那一段就消失了，若不同步补回，第一行最左侧的「页面切换」和第二行最左边的「全选」会直接压在屏幕边缘上。所以第一行的左右内边距由 0 补到 4px，内容位置与改动前逐像素一致；第二行的左右内边距按需求只保留 2px，让按钮更贴近屏幕两侧，可横向滑动的内容区也从 364px 变成 386px。' },
        { t: '贴死之后还剩的那条 1 像素细缝', d: '第一版交付后，坐标已经量到「顶栏 top 0、两行间隙 0」，但屏幕上仍能看见一条浅色细线。原因是顶栏元素本身带 1px 透明边框，而玻璃背框是它的伪元素、定位参照的是内边距盒，那 1px 边框环永远盖不住 —— 圆角浮起时这是刻意留白，通栏贴顶后就变成屏幕最上沿的一条缝；加上顶栏向下投的阴影会压在第二行顶部形成一条渐变暗带，两处叠起来就是肉眼看到的「缝」。现在把这 1px 边框环清零、背框铺满整个边框盒并关掉向下的投影，描边只保留第二行的底边，两行从背景到交界处完全连续。' },
        { t: '滚动吸附时的位置同步', d: '手机上第二行在页面滚动后会吸附到第一行下方。既然常态下两行已经贴死，吸附态的定位也一并从「顶栏底部加 2px」改成「顶栏底部」，宽度与左偏移同步改成贴边值，并清掉吸附期间的左右外边距 —— 否则一滚动整行就会往下跳 2px、或者被负外边距推出屏幕。' },
        { t: '影响范围', d: '只在「图床管理页 + 手机屏宽（不超过 768px）」生效：样式规则全部挂在图床管理页专属的页面标记之下，顶栏虽然是与其它后台页共用的组件，但其它页面不会命中这些规则；桌面端（大于 768px）与平板（769 至 1023px）的顶栏、第二行保持原样。没有新增表、没有新增字段、没有接口改动。' }
      ]
    },
    {
      id: 'whatsnew-115',
      title: '三十六、v1.1.5 更新要点',
      intro: 'v1.1.5 做两件事：一是「移动」弹窗里多了「移动 / 复制」二选一，可以把文件复制给别的实例（目标实例多一份数据、有新链接，但底层还是同一个文件，不多占存储）；二是把「引用」与「共用」两个统计彻底拆开 —— 前者管「这份数据能不能删」，后者管「存储里的文件能不能删」，并让所有删除入口（删除、回收站恢复/彻底删除、批量删除、目录删除）都按这套规则把关。',
      items: [
        { t: '批量操作：移动还是复制，必须先选一个', d: '选中文件或文件夹点「移动」，弹窗第一步仍是选接收实例，下方新增「操作方式」两个选项：移动（源数据不再保留）、复制（源数据保留、目标实例多一份）。默认一个都不选，必须选一个才能点「下一步」，每次打开都重新回到未选状态，不记忆上次选择；选了之后弹窗标题、第二步顶部的徽标都会跟着变成「复制」或「移动」，避免做到一半忘了自己在做什么。' },
        { t: '复制出来的那份：新链接，同一个文件', d: '复制会在目标实例里新建一条文件数据，因此有独立的访问链接、独立的文件名与标签，但它指向的仍然是存储里的同一个对象 —— 不额外占用空间。同时这条复制关系会记进「删除统计」：两条数据从此互为共用，任何一方彻底删除都只删掉自己那份数据，存储里的文件要等最后一份被删掉才会真正清走。' },
        { t: '引用统计：管的是「数据能不能删」', d: '只要一个文件被引用过——被笔记当附件/封面引用，或者它所在的目录被共享给了别人——这份数据就不能删除，连放进回收站也不行。原因是删除后别人的笔记会变成「加载失败」、被共享的人也会突然打不开。拦截时会直接告诉你占用的来源：有笔记引用就列出笔记标题，只有目录共享就提示去「文件夹属性」里先取消共享。' },
        { t: '删除统计（共用）：管的是「文件能不能删」', d: '同一个文件被几份数据共用着，就记几次共用。共用大于 0 时删除只删自己那份数据，存储里的文件留着给别人用；共用为 0（也就是最后一份）且没有引用时，在回收站里彻底删除才会把文件一并清掉。登记文件（只登记了地址、文件本身在别处）例外——无论何时都不会去删源站的文件。' },
        { t: '四种删除情形的最终行为', d: '有引用 + 有共用：数据不能删；有引用 + 无共用：数据不能删；无引用 + 有共用：数据能删、能从回收站彻底删除，但文件保留；无引用 + 无共用：数据能删，彻底删除时文件一并清掉。这四个分支在删除文件、删除目录、回收站彻底删除、批量操作里走的是同一套判定，不会出现「这个入口拦住了、那个入口放过去了」。' },
        { t: '上传去重：同实例给原链接，跨实例才新建', d: '上传时发现内容和已有文件完全相同：如果在同一个实例里，直接把原来那份的链接给你，不再新建数据（也就不产生共用关系）；如果命中的是别的实例，则在当前实例里新建一份数据（新链接），并计入共用以共用同一个文件。判断「是不是同一个文件」看的是渠道内的对象标识，所以复制、跨实例上传、去重命中产生的都是同一份实体。' },
        { t: '详情页：引用(xx) | 共用(xx)', d: '文件详情里「文件引用」一行现在输出两个数字，例如「引用(2) | 共用(1)」，鼠标停在数字上会解释各自的口径；数字为 0 时置灰，任意一个不为 0 就显示「查看」按钮，点开是新标签页的引用明细页。原来的来源小计（几条笔记 / 几个分享）保留，但只在两种来源同时存在时才显示。' },
        { t: '文件引用页：分成「引用明细」和「共用明细」', d: '页面顶部给出「引用(xx) | 共用(xx)」，下面分成两块：引用明细列出这个文件被哪篇笔记、哪个目录共享、哪个标签分享用着（带类型、时间、作者）；共用明细列出这个文件还被哪几份数据共用 —— 在哪个实例、谁上传的、是否在回收站、以及这一份是不是从你这里复制出去的。只有存在共用时才会出现这一块。' },
        { t: '顺手修掉的三个问题', d: '① 文件引用页以前一直显示「还没有被任何引用」，实际是请求地址写错一直打不开数据，现已能正常列出；② 详情页「文件引用」的数字以前恒为 0（列表数据里没有这两个字段，弹窗打开时也没回填），现在与真实情况一致；③ 开发环境下打开文件引用页会白屏（请求被错误转发到后端），已修正转发规则。' },
        { t: '数据库与其他', d: '本版给文件表新增三列：引用统计、删除统计、来源记录（记录这条数据是从哪条复制/克隆出来的）。三列都有默认值，旧数据不需要手工回填，第一次被访问或删除时会自动算出准确值。旧的图片、外链、分享、笔记附件关系全部不受影响。' }
      ]
    },
    {
      id: 'whatsnew-116',
      title: '三十七、v1.1.6 更新要点',
      intro: 'v1.1.6 是一次「修问题 + 补细节」的版本：把笔记灯箱「点第 3 个却打开第 1 个」和「边缘滑动变成页面后退」这一对根因相同的 bug 钉死，把笔记标签真正做成按账户 + 实例隔离，把瞬间编辑页与瞬间卡片的一批交互细节按需求逐条对齐；同时新增了「文件浏览记录」——关掉灯箱就记下这一笔，历史记录页可以按「今天 / 昨天 / 前天 / 近 7 天」回看。另外还改了排序按钮、昼夜切换默认时间、网站标题占位符、挂载渠道停用后的入口隐藏等零散项。',
      items: [
        { t: '灯箱为什么「有时行有时不行」', d: '父组件通常在同一个渲染批次里既设置待预览列表、又把灯箱设为打开，于是灯箱组件是「带着打开状态被创建」的。这种创建方式不会触发「打开」的监听逻辑，导致内部停在第一项，键盘、屏幕边缘返回手势、历史哨兵也都没绑上 —— 点第 3 个附件显示第 1 个，滑边缘不会关灯箱而是页面后退，都是这一处引起的。现在组件挂载时会补跑一次完整的打开流程，两个问题一起消失。' },
        { t: '笔记标签按账户 + 实例隔离', d: '标签的唯一标识原来只有「名称 + 实例 + 类型」，两个账户取同一个标签名会落到同一条记录上，于是互相看得见。现在标签多了一个「归属」维度：文件标签统一留空，笔记标签写入作者账户名，唯一性按四元组判定。启动时会自动把历史上「多个账户共用一条笔记标签」的数据按作者拆开，老数据无需手工处理。笔记标签只有作者本人（以及同账户下的自己）能改名 / 合并，管理员也看不到别人的。' },
        { t: '发布笔记选文件只看自己当前实例', d: '「选择文件」里原本管理员能翻到全站文件，现在一律只列出「当前账户 + 当前实例」下的图床文件，与图床管理页看到的一致。' },
        { t: '瞬间编辑页 6 项细节', d: '① 正文输入框最小高度提到视口高度的 30%；② 「取消」左侧那句常驻的「写点什么，或发个照片」去掉了（输入框里的提示文字保留）；③ 正在上传文件时，这个位置显示「文件上传中」；④ 「链接提取」的输入框加高两行；⑤ 「选择文件 → 图床文件」里的视频现在能显示缩略图了；⑥ 心情 / 天气在桌面端把鼠标放上去会显示名称，手机上也不再是下拉框，改回和桌面一样直接点图标。' },
        { t: '瞬间内容排版', d: '文字超长时「全文 / 收起」会落在最后一行文字的末尾并带底色，不再单独占一行；选「分割线样式」时附件不留圆角、彼此间距收到 2px，并且标题、正文、附件区的实际宽度与「边框样式」完全一致（以前会宽出 32px，来回切换排版内容会左右跳）。' },
        { t: '发布后可以改发布时间', d: '卡片标题旁边的时间现在可以点，点开就能把这条瞬间的发布时间改成真实时间（比如补记昨天的事）。列表按发布时间排序、分组，改完立即生效；误填的时间也能随时再改回来。' },
        { t: '新增：文件浏览记录', d: '在「图床管理」或「笔记管理」里用灯箱看过某个文件，关闭灯箱时会把这一刻记到该文件上（灯箱里左右翻过的文件都会记）。只有用灯箱看过才算，从文件详情页打开、直接点链接都不算。历史记录页「文件类型」后面新增「最近浏览」下拉，可选全部 / 今天 / 昨天 / 前天 / 近 7 天，默认不过滤。' },
        { t: '图床管理', d: '「排序」按钮由纯图标改成「↓ 降序 / ↑ 升序」的文字按钮，桌面端鼠标移上去自动展开菜单、移走自动收起；筛选里新增「文件引用」（已引用 / 未引用）与「文件共用」（已共用 / 未共用）两组条件；移动文件时如果目标就是当前实例，只能移动不能复制（复制到同一实例没有意义）。' },
        { t: '系统设置与首页', d: '白天 / 夜间切换时间的默认值改为 07:00 — 19:00（已手动设置过的不受影响）；网站标题支持 {host}（当前域名）、{user}（登录用户名）、{pagename}（当前页面名）三个占位符，未登录时后两个不显示、也不会留下多余的分隔符；渠道设置里停用的「挂载文件」渠道不再出现在挂载管理页；「创建用户」弹窗里的「账户权限」整组移除，新建账户走默认权限，建好后再到编辑账户里调整；首页去掉了「选一个类型，直接开始写」、放开了图标行距，并在右下角「文件」上方新增「笔记」入口。' },
        { t: '权限与日志', d: '超级管理员现在可以删除 / 彻底删除别人名下的文件（普通用户仍然只能删自己的，行为不变）；上传失败会写入系统日志，带上文件原名与渠道，方便排查。' }
      ]
    },
    {
      id: 'whatsnew-117',
      title: '三十八、v1.1.7 更新要点',
      intro: 'v1.1.7 主要是「把要求逐条对齐」的版本：笔记设置新增「通用设置」（页面加载方式 + 正文字号），瞬间编辑页一次改掉十几处交互细节，文件详情页的「裁剪」改名为「剪辑」并真的能涂鸦写字了；另外把浏览记录按账户 + 实例收窄、边缘横滑不再退回上一页、网站标题留空时默认「GoHub 页面名」，以及「收集」改名为「登记」、用户管理四个模块换了名字。',
      items: [
        { t: '笔记设置：新增「通用设置」', d: '设置页左侧在「瞬间设置」前面多了一项「通用设置」，里面两件事。① 页面加载设置：自动加载（默认）= 滚到底自动续上一页；手动加载 = 滚到底只出现「加载更多」按钮，点了才加载。② 字体大小设置：只作用于正文，标题、日期、留言等其他文字不受影响；默认值与出厂值一致（桌面上 14.5px），所以没动过这项的人看到的样子完全不变。设置按实例保存，切换实例各是各的。' },
        { t: '瞬间卡片排版', d: '选「分割线样式」时，那条分割线现在和内容加载区一样宽 —— 以前它是盒子的下边框，比内容区宽出左右两段内边距，看着就是个「多出来的边」。附件之间的上下左右间距统一收到 1px（边框、分割线两种样式一致），边框样式下附件的圆角从 3px 收到 2px。' },
        { t: '留言：长按删除、更多 / 收起、发布后不跳位', d: '留言后面那个常驻的 × 去掉了，改为长按留言 → 弹出只有「删除」的菜单（手机长按 0.5 秒，桌面也能右键）。留言超过高度限制时下方出现「更多」，展开后变「收起」，刷新后回到收起状态。发布留言后页面会留在原来那条瞬间上，不再被滚动带到别处。关于「带附件的瞬间点别人的留言会整条消失」：这次把发布 / 回复时的滚动补偿和长按菜单一起重做了，滚动不再无限制往下跑；由于本地环境里所有留言都属于登录账户本人，构造不出「别人的留言」这个场景，未能复现原始现象。' },
        { t: '瞬间编辑页的十余处细节', d: '心情「难过」改为「伤心」并换成哭泣图标；位置输入框不再用浏览器记忆，改成「聚焦时列出当前实例最近的记录、输入时按关键字在数据表里筛选」（和标签框一个手感，只查自己当前实例）；标签框按空格也等同回车成为标签；标签下拉一律向上展开；上传文件时「文件上传中」前面加了旋转图标；「x 个附件」挪到「取消」左侧（上传时显示上传中，平时显示附件数）；「上传到图床」弹窗只能点按钮或按 Esc 关，点外面不再关掉；编辑页与「选择文件」页在移动端宽高都改到 98%；正文输入框最小高度提到视口 45% 且右下角可以自由拉伸；「链接提取」输入框加高 2 行；标题不再自动填充，提示语改成「标题（选填）」。' },
        { t: '「选择文件」会记住上次的样子', d: '加载过的列表按「实例 + 类型 / 渠道 + 目录」缓存在浏览器里（24 小时过期、有条数与体积上限），下次进来先用缓存把界面铺满，再在后台拉最新数据，不再白屏等一圈。同时记住上次选的加载源、类型，以及「挂载文件」里选的渠道和打开的目录，下次直接回到那个位置。' },
        { t: '发布时间：居中、星期、初始时间', d: '手机上点瞬间标题后面的时间，时间选择器改为屏幕居中，不会再被底部遮住。时间后面自动跟星期，例如「11月11日 09:13 周三」。数据库新增一列「初始发布时间」，只在创建瞬间时写一次，之后无论怎么改发布时间都不动它 —— 按需求目前只落库、不下发、不显示，留给以后做「原始发布时刻」相关的统计。' },
        { t: '图床管理：移动按钮直接选接收实例', d: '卡片视图里文件夹上的移动按钮、列表视图里文件夹和文件行尾的移动按钮，点下去现在直接调出批量操作里那个「选择接收实例」弹窗，不用再先进批量模式。' },
        { t: '「裁剪」改名为「剪辑」，并且能涂鸦写字了', d: '文件详情页里的「裁剪」正式改名「剪辑」，打开的还是同一个处理页，但多了两个工具：画笔（自由涂鸦，7 种颜色 × 3 种粗细，可撤销 / 清空）和文字（点图上任意位置输入，颜色与字号可调）。涂鸦和文字都记在图片坐标系里，旋转图片时跟着一起转，转四次回到原位不会错位；保存时按「先裁切、再叠加」的顺序合成为一张图，落在外面的笔迹自然被裁掉。处理页的宽高统一改为 98%（以前手机上满屏、桌面上靠内容撑高还容易溢出）。' },
        { t: '浏览记录只对自己、只对当前实例', d: '以前浏览时间写在文件行上，管理员看了别人的文件，文件作者在「历史记录 → 最近浏览」里会看到这条记录。现在写入时只记自己名下的文件（看别人的静默跳过），查询「最近浏览」时一律按当前登录账户收窄 —— 连共享进来的目录也不放开。文件详情的「文件引用 → 查看」页同样只列自己当前实例下的数据。' },
        { t: '全站：横滑不后退、灯箱去圆角、切换按钮间距', d: '边缘 28px 内的横滑一律吃掉（除非本来就是能横滚的容器，或者横滑就是它功能的滑块 / 走马灯 / 标签条）；以前从边缘起手又刚好落在输入框、开关上时会放行，那几下仍会退回上一页，现已收紧。所有图片灯箱里浏览的图片去掉了圆角。移动端图床管理页、笔记管理页左上角「页面切换」按钮的左右外边距改为 5px。' },
        { t: '网站标题默认值与页面名', d: '「网页设置 → 网站标题」留空时的默认值改为「GoHub {pagename}」，等于默认就带页面名。{pagename} 的映射补齐：/ = 首页、/dashboard = 图床管理、/localFiles = 挂载管理、/notes = 笔记管理、/customerConfig 及其子路径 = 用户管理、/systemConfig = 系统管理、/manage/history = 历史记录；仍然只在登录后显示，未登录时自动回落到「GoHub」。' },
        { t: '改名：登记、以及用户管理的四个模块', d: '首页「记录」下的「收集」和笔记管理里的「收集」统一改名为「登记」（发布按钮相应变成「添加登记」，设置分类叫「登记设置」）。用户管理页的四个模块改名：实例管理 → 我的实例空间、存储渠道 → 默认存储渠道、对外分享 → 对外分享记录、管理员操作 → 管理员操作区。' }
      ]
    },
    {
      id: 'whatsnew-118',
      title: '三十九、v1.1.8 更新要点',
      intro: 'v1.1.8 是「收口细节」的一版：瞬间卡片彻底不再有标题，时间回归它本来的身份（可改、不加粗）；笔记设置新增「笔记页背景图」；全站层叠页面统一由 closePageOrder 按层级逐层关闭，边缘横滑与 Esc 都一次只关一层；剪辑页的文字可以拖着走了；图床卡片视图的圆角、按钮、播放角标一并做了微调。',
      items: [
        { t: '瞬间不再有标题，时间可以一直改', d: '① 编辑页的标题输入框整块移除，内容加载区也不再显示标题；② 发布时间不再顶替标题的位置、不再加粗，任何时候点它都能改；③ 笔记管理的默认排序「最新发布」改为按发布时间降序，发布时间为空的老数据排在最后，其次按创建时间兜底。' },
        { t: '留言：更多 / 收起，以及点留言不再整条消失', d: '留言超过显示区高度时，下方出现「更多」，点开变「收起」，刷新后回到收起态 —— 原来按钮和被裁切的列表在同一个 overflow:hidden 容器里，按钮自己被裁掉了，现在拆成「外层不裁 + 内层裁列表 + 按钮在外」。点留言导致整条笔记消失，根因有两个：一是瞬间卡片是多根组件，$el 拿到的是注释节点，获取位置时抛错让后面的滚动补偿整段失效；二是手机软键盘弹起时视口高度骤减，所有按视口百分比的尺寸一起缩，整条卡片被挤出屏幕。前者改用 ref 取真实节点，后者在「输入框聚焦 + 高度骤减」时不再同步视口高度。' },
        { t: '笔记设置：新增「笔记页背景图」', d: '笔记设置 → 通用设置里新增一项多行文本框，写法 [“图片地址1”,“图片地址2”]。填多张时每次刷新随机取一张，只填一张就固定用它；只在日间模式生效，切到夜间模式背景图直接不渲染。校验口径与「用户管理 → 账户自定义背景图」一致：只接受 http(s) 链接与站内 / 开头的路径，最多 20 张，写错的地址会被丢掉而不是让整份设置存不进去。填空即取消背景。' },
        { t: '边框线样式：改名、间距 2px、圆角 3px', d: '「边框样式」正式改名「边框线样式」（中英文都是），选择它时附件之间的上下左右间距为 2px、附件圆角 3px；「分割线样式」保持原来的 1px 与直角。高度预算里用的间距常量也同步跟着排版样式取，避免算出来的行高与真实渲染差 1px 导致最后一行溢出。' },
        { t: '「选择文件」页：全部类型、两个来源按钮改名', d: '文件分类在「图片」前面加了「全部」，选中它就不按类型过滤，一次看到图床里的所有文件（挂载模式同样不过滤）；「图床文件」「挂载文件」两个来源按钮改名为「从图床文件」「从挂载文件」；上次选的类型仍会被记住。' },
        { t: '剪辑：文字可以拖着走，移动端图片区更高', d: '文字工具下，按在已有文字上就拖动它（按下的点相对文字的偏移保持不变，拖起来不会跳），按在空白处才是新建一段；命中判定用与绘制相同的字体量出文本框，并留 6px 手指余量，从后往前找（后画的在上）。移动端剪辑页的图片加载区最小不低于视口高度的 60%。所有剪辑入口统一调用同一个处理组件，上传页的裁剪也去掉了 allow-annotate=false，功能与文件详情页完全一致。' },
        { t: '层叠页面：一次只关一层（closePageOrder）', d: '新增 closePageOrder()，全站浮层（灯箱 / 文件详情 / 各类弹窗）打开时登记层级，关闭时注销。边缘横滑或按 Esc 时，按「z-index 从大到小、同层按打开顺序」选出最上面一层并只关它：灯箱上压着文件详情就先关详情，再滑一次才关灯箱，都关完页面才会响应返回。修复过程中还顺手修掉一个真 bug：边缘滑动的位移只在判定那一帧记录（约 6~14px），之后每帧都提前返回，抬手时永远够不到 64px 阈值 —— 也就是真实用户滑得再远也关不掉浮层。' },
        { t: '灯箱：下拉之后仍能打开文件详情', d: '灯箱打开时锁住页面滚动（还原时补回滚动条宽度），手指下拉不再滚动身后的列表页，也就不用担心翻页、排序或滚动位置漂移导致「详情」查不到当前这条文件；万一确实对不上，也会按列表项的原始数据兜底打开。另外控件自动隐藏时，点空白处只把控件唤回来，不再误关灯箱。' },
        { t: '卡片视图的四处观感微调', d: '① 卡片圆角 12px → 5px；② 右上角选中圆圈上移 2px；③ 悬停时出现的「复制」「打开」按钮 32px → 28px、图标 13px → 12px；④ 视频缩略图右下角加了一枚小小的播放角标（缩略图加载失败时不再叠它，避免盖在「加载失败」上）。' },
        { t: '图标补齐', d: '「转为重定向」与「转存方向」原先引用了未注册的 exchange-alt、right-left，控制台报图标缺失、显示空白；现已注册（Font Awesome 6 里两者的规范名都是 right-left，浏览器里看到的是同一个图标）。笔记里用的 location-dot 也一并注册。' },
        { t: '页脚、首页页签与详情按钮', d: '首页与登录页页脚的「©2024-2026 Powered by」后面补上 HQH；首页「记录」页签改名为「发布」；从笔记管理浏览附件、在灯箱里打开的文件详情页，顶部补齐「标签 / 黑名单 / 白名单」三个按钮，与图床管理页里打开时完全一致。' }
      ]
    },
    {
      id: 'whatsnew-119',
      title: '四十、v1.1.9 更新要点',
      intro: 'v1.1.9 把上一版「以为修好了」的一处彻底查清：图库预览里点「查看详情」时有时无反应，根因不是滚动，而是弹窗与预览之间的层级竞争。同时把文件详情里的十五个弹出页全部接进了层叠关闭体系，手机剪辑页的图片区放大到视口高度的 70%。',
      items: [
        { t: '修掉「预览里点详情没反应」', d: 'Element Plus 弹层的 z-index 是全局计数器从 2000 起逐个递增分配的，而文件预览大图的层级是写死的 3200。会话里开过的弹窗少时，详情拿到的是 2001 左右 —— 其实已经打开了，只是被压在预览底下，看起来就是「点了没反应」。现在把弹层的层级基准整体提到 4000，预览保持 3200（仍高于页面顶栏），详情永远在预览之上，关掉详情预览还在。' },
        { t: '十五个弹出页纳入层叠监测', d: '文件详情里的标签、黑名单、白名单、重命名、删除、限时、加密、重定向、分享、源信息、转到异地 / 存入本地、压缩、转 WebP、剪辑，之前都没有登记到层叠栈里：它们开着时按 Esc 或边缘横滑会直接把文件详情关掉，小弹窗反而留在屏幕上。现在逐层登记，一次只关最上面那一层 —— 小弹窗全关完才会关详情，详情关完才会关预览。' },
        { t: '确认框也算一层', d: '删除、黑名单、白名单用的是弹出确认框（还需要手动输入「确认删除」），不是普通弹窗，之前完全不在层叠体系里。现在同样登记，确认框开着时按 Esc 只关确认框，不会误关详情页。' },
        { t: '手机剪辑页：图片区 70% 屏高', d: '由 60% 提高到 70%，底部工具栏因此被挤到可视区之外 —— 这时弹窗内容可以上下滑动，工具都能滑到、点到，不会被裁掉。' },
        { t: '列表视图缩略图圆角 5px', d: '与卡片视图的卡片圆角对齐；桌面端原来是 8px、手机端 6px。' },
        { t: '瞬间输入框提示文案', d: '改为「记录当下瞬间，汇聚未来回忆」。' }
      ]
    },
    {
      id: 'whatsnew-1191',
      title: '四十一、v1.1.9.1 更新要点',
      intro: 'v1.1.9.1 把两处「层级打架」的根因挖了出来：一是预览里下拉打不开文件详情，二是确认框被宿主弹窗整层盖住。顺带把十四张弹出页全部接进层叠关闭体系，并把瞬间编辑页的头尾各收窄 10px、心情天气的名称提示改成不会被裁掉的浮层。',
      items: [
        { t: '图床管理：预览里下拉能打开详情了', d: '上一版只修了「点详情按钮」，下拉走的是另一条分支：文件已落库时会发出「打开文件详情」事件，但图床管理页从来没有接这个事件，于是下拉毫无反应。现在补上监听，与点按钮走同一套逻辑，找不到当前行时还会用预览里保存的原始行兜底。' },
        { t: '确认框不再被弹窗盖住', d: '文件详情里的黑名单 / 白名单 / 删除、瞬间编辑页的「链接提取」，弹出的都是 Element Plus 的命令式确认框。它的层级基准是 2000，而普通弹窗是 4000，于是确认框永远垫在下面 —— 链接提取看起来就是「点了不弹」。现在确认框统一抬到 6200，永远在弹窗之上。' },
        { t: '十四张弹出页纳入层叠关闭', d: '笔记设置、发布类型选择、删除瞬间、筛选、新建目录、链接格式（图床管理 / 首页）、登记文件与它的目录选择、上传设置与它的目录选择、三处切换实例，全部登记为层叠页。目录选择弹窗天然压在宿主弹窗之上，一次返回 / Esc 只关最上面那一层。' },
        { t: '瞬间编辑页：名称提示不再被裁', d: '心情 / 天气的名称提示原先渲染在图标内部，而正文区是滚动容器，向上浮出的那一小块整块落在裁切区之外，实测完全看不见。现在改成挂在页面最外层、按图标位置浮动的提示，既不参与裁剪，也不会被标题区盖住。' },
        { t: '瞬间编辑页与剪辑页：头尾各减 10px', d: '顶部标题行、底部按钮行的内边距各压掉 10px，正文 / 图片区因此多出 20px；这两处的固定块高度都实测少了整整 10px。' },
        { t: '上传到图床：可直接选目录 + 记住历史', d: '「上传目录」输入框左侧新增目录选择器，列出当前所选实例下的目录，选中即回填；输入框同时记住最近用过的目录，光标进入即可直接挑，与首页上传设置共用同一份历史。' },
        { t: '两处文案', d: '留言按钮由「发布留言」改为「发表留言」；瞬间输入框提示改为「记录瞬间，汇聚点滴」。' }
      ]
    },
    {
      id: 'whatsnew-1192',
      title: '四十二、v1.1.9.2 更新要点',
      intro: 'v1.1.9.2 新增了一个「相册视图」——参照群晖相册与 Immich 的图墙：没有圆角、没有边框、没有下方信息区，图片直接铺满，间隔 2px 并左右贴边。同时把二十九张弹出页全部接进层叠关闭体系，并让「批量选中」也能用 Esc / 边缘横滑取消。',
      items: [
        { t: '新增相册视图', d: '视图切换按钮从两个变三个，相册在前两个之后，图标是叠放的照片。进入后整页只有格子：图片直接加载缩略图铺满，文件夹显示图标 + 名称（名称在图标下方），点图片开灯箱、点文件夹进目录。' },
        { t: '相册的尺寸口径', d: '所有格子都没有圆角、没有外边框、没有下方信息区，间隔 2px，最左最右直接贴屏幕边缘。手机竖屏每行 4 个、横屏 8 个（单格 1:1）；平板竖屏 6 个、横屏 12 个；桌面端固定每行 8 个、单格 1:1，窗口变宽时格子等比变大，两边始终对齐。' },
        { t: '相册按屏宽决定一次加载多少', d: '手机（含横屏）首次加载 48 个，平板与桌面首次加载 72 个；滑到底部自动追加，不用点「加载更多」。' },
        { t: '回收站也能切换展示方式', d: '回收站原先固定按文件夹分组显示。现在与普通列表一样有「展示文件夹 / 直接展示文件」两种方式，切到直接展示时，回收站里所有文件平铺成一条列表，不再出现文件夹卡片。' },
        { t: '两处界面细节', d: '「直接展开文件」文案改为「直接展示文件」；卡片视图的文件夹卡片圆角由 12px 收到 5px，与文件卡片一致。' },
        { t: '创建目录会记录创建人', d: '以前从「创建目录」建出来的文件夹，属性里看不到创建用户 —— 因为目录本身只是一条路径，没有数据行可挂。现在建目录时会把操作人写进账户 / 实例维度的目录登记表，属性里能正常显示创建人与创建时间（空目录也有）。' },
        { t: '批量选中：Esc / 边缘横滑 = 取消选中', d: '选中一批文件或文件夹后，桌面按 Esc、手机在屏幕边缘横滑，会先取消选中，而不是退出页面或回到上级目录。没有弹窗可关时才会走到这一步。' },
        { t: '二十九张弹出页纳入层叠关闭', d: '回收站删除、文件夹属性、删除文件 / 文件夹、批量备份、批量编辑原名、批量标签、批量设置（限时 / 加密 / 重定向）、黑名单 / 白名单、移动文件、标签属性 / 合并 / 拆分 / 删除、发布瞬间里的选择文件与筛选、上传到图床时的选择目录、用户管理的实例加入 / 创建 / 邀请 / 属性 / 删除、系统状态的趋势选日期、渠道设置的添加 / 详情 / 编辑 / 授权、API Token 的创建 / 接入信息 / 编辑 / 删除 —— 打开后一次 Esc 或一次横滑只关最上面那一层。' },
        { t: '顺带修掉两个底层缺陷', d: '一是「从没开过弹窗的页面根本不监听 Esc」——关闭逻辑只在登记弹窗时安装，于是批量选中按 Esc 毫无反应；二是「弹窗用 v-show 关掉后，它的层还留在栈里」——这类死层会把第一次 Esc 白白吃掉。现在分别补上安装时机与死层清理。' }
      ]
    },
    {
      id: 'whatsnew-1193',
      title: '四十三、v1.1.9.3 更新要点',
      intro: 'v1.1.9.3 是一次全面对齐：三种视图（卡片 / 列表 / 相册）的文件加载区上边距统一为同一个值；相册里的视频补上首帧缩略图与播放角标，视图切换滑块补上第三档；电脑端顶部两行改为通栏、贴紧、随页面吸附；灯箱打开时默认只显示内容，控件点一下才出来；瞬间编辑页右下的状态位改为三态常显；手机剪辑页真正满屏，次要操作挪到底部左侧。',
      items: [
        { t: '三种视图的留白统一', d: '改前卡片视图的文件区离上方第二行是 10px，列表与相册是 15px。现在统一以列表视图为基准：电脑端 18px、手机端 11px，切视图不再跳。手机端三个视图的上外边距统一归零，由父级 gap 一次性给足，避免「吸顶条 + 双倍留白」。' },
        { t: '视图切换滑块补上第三档', d: '滑块是 ::before 绝对定位，位移按「档位 ×（按钮宽 + 间隔）」算：桌面按钮 28px、间隔 2px，相册档 60px；手机按钮 24px、间隔 2px，相册档 52px。以前切到相册滑块还贴在列表那一格。' },
        { t: '相册里的视频显示首帧', d: '视频格子以前是纯黑。现在用 preload="metadata" 加 #t=0.1 的媒体片段参数，让内核解出第 0.1 秒那一帧（只读元数据很多内核不解帧），muted + playsinline 保证移动端不自动起播、不全屏，画面按 cover 铺满正方形格子。' },
        { t: '相册视频的播放角标', d: '格子右下角 6px 处一个 20px 的圆形角标（半透明黑底 + 白色播放三角），够认不抢图；pointer-events: none 让点击穿透到格子本身，不会出现「点角标没反应」。三角视觉重心偏左，单独右移 1px 才居中。' },
        { t: '电脑端顶部两行：通栏', d: '两行左右不再有留白，直接贴住页面边缘。做法是用负 margin 抵掉主容器内边距（桌面 60px、平板 24px）并同步加宽，同时去掉圆角与外边框。注意 .breadcrumb-container 默认 content-box，只写 width: calc(100% + 120px) 会把左右 padding 再加一遍，右边界比屏幕多出 24px —— 必须显式 box-sizing: border-box。' },
        { t: '电脑端顶部两行：贴紧', d: '两行之间的上下间隔改为 0。这里有个隐性余量：顶栏占位变量 --admin-header-space 写的是「实际高度 + 12px」（给阴影留的呼吸空间），所以第二行要按档位反向抵消：桌面 -20px、平板 -16px、紧凑顶栏（≤1023）-28px。只抵 16px 时平板竖屏会露 8px 缝。回收站横幅夹在两行之间时单独归零，避免横幅被一起吸上去。' },
        { t: '电脑端顶部两行：吸顶', d: '本站 body 滚动由 OverlayScrollbars 接管，原生 position: sticky 无效，所以沿用「越阈值 → 切 fixed + 外层占位」的做法，并新增桌面端启用。阈值要减掉第一行高度，否则「刚贴到顶栏下沿」那一瞬还没触发切换、第二行会被第一行压住一段。行为分三段：向下滚顶栏隐藏、第二行贴顶；向上滚顶栏出现、第二行贴顶栏下沿；滚回顶部复位。吸顶态用不透明底色 + 1px 下边框，避免文件列表透过来。' },
        { t: '灯箱打开时默认不显示控件', d: '打开时不再自动弹出控件与启动自动隐藏定时器，点一下屏幕才显示、再点收回。定时器必须一并清掉：留着会在两三秒后把控件又置回隐藏并触发一次无意义重排，若用户恰好在这时点击就会跟「点击切换」打架。视频的原生播放条也跟着一起藏（:controls 绑定同一个状态），否则等于没藏。' },
        { t: '灯箱背景与翻页按钮', d: '遮罩从深压暗降到 10%（保留轻微模糊），翻页按钮从不透明黑底改成与右上「关闭」一致的玻璃质感（1px 白描边 + 8% 白底，悬停 16%）。因为遮罩几乎透明，落在其上的元素必须自带描边，否则浅色页面里看不见。' },
        { t: '灯箱小圆点（朋友圈样式）', d: '多图时，控件隐藏状态下距底部 10px 显示一行圆点，切图跟随，控件一显示即隐藏。跟随用的是「当前图在缩略图集合里的序号」而不是全局 index —— 灯箱可能从「当前目录图片」或「全部图片」两种集合打开，index 基准不一致。圆点用 .is-idle 控 opacity 而不是 v-if：v-if 每次切控件都会销毁重建 N 个节点，图多时会卡。5px 圆点外加 1px 深色描边，是为了在 10% 遮罩下也能分辨。' },
        { t: '手机图片灯箱：垂直居中', d: '以前为上方标题区、下方缩略图区预留了内边距，图片被压成一小块。现在图片垂直居中、不为控件避让，标题区与缩略图区改为绝对定位浮层并补上渐变 / 纯色底，否则白色文字落在浅色图片上会糊。这些规则只对图片生效（根节点加 is-image 类区分），视频与 PDF 的排版不动。' },
        { t: '手机图片灯箱：隐藏三个缩放按钮', d: '「缩小」「尺寸切换」「放大」在手机上直接不显示 —— 手机靠双指缩放，这三个按钮没有使用场景。电脑端保留。' },
        { t: '缩略图尺寸调小', d: '电脑端由 72×54 收到 64×48，手机端由 58×44 收到 52×40，仍保持 4:3 —— 缩略图是 4:3 容器加 cover，改比例会让图片变形。' },
        { t: '瞬间编辑页：三态状态位', d: '「取消」左侧那一位以前只在有附件时显示「x 个附件」，空草稿时是空的，用户不知道这里能不能写。现在上传中显示上传提示（带转圈）、有正文或附件显示「x 个附件」、都没有显示「写点什么，或发个照片」（65% 透明度 + 斜体，与信息态区分）。判定正文前先 trim，只敲空格不算有正文。' },
        { t: '分割线样式附件间隔 2px', d: '由 1px 改为 2px，与默认样式一致。这条牵动两处：样式表里的 gap 与计算用的 attachGapOf() 常量必须同时改 —— 该常量参与「网格总高 ÷ 行数」的高度估算，用于分页占位；两处不一致的症状是第一屏正常、往下滑图片一点点往上跑、最后一屏最后一行被裁掉。' },
        { t: '剪辑页：次要操作挪到底部左侧', d: 'footer 分左右两区，左侧按模式切换内容：裁剪模式只显示「重置选区」，画笔 / 文字模式显示「撤销」「清空」；右侧永远是「取消 / 保存」。都改成 text 类型按钮，并以「有没有框选」「有没有标注」为可点门槛，避免误点。' },
        { t: '剪辑页：真正满屏', d: '以前手机上是 374px 宽（390 × 94% 再减边距）—— 因为全局 responsive.css 里有一条带 !important 的弹窗宽度收敛。要满屏只能同样用 !important 压回去（width / max-width 100vw，height / max-height 100vh，margin 0，圆角 0），并去掉 Element Plus 默认的居中偏移。' },
        { t: '剪辑页：移动端舞台最小 65vh', d: '用 min-height 而不是 height：图片本身很矮时舞台也占 65vh（不塌），图片很高时舞台可以长出去、由 body 滚动条承接（不裁）。若写成固定 height，这两头都做不到。底部工具行展开超出屏幕时，页面出现滚动条，所有按钮都能滚到。' },
        { t: '文案：「框选裁剪」改为「裁剪」', d: '中文侧工具名改短，英文侧本来就是 Crop 不用动。工具行是「图标 + 文字」，名字短一点在手机上不容易折行。' }
      ]
    }
  ]
};

const EN = {
  title: 'Documentation',
  subtitle: 'Everything about uploading, links, storage channels, dedup and backups',
  toc: 'Contents',
  backHome: 'Back to upload page',
  footer: 'This documentation ships with the system and matches the current version behaviour.',
  sections: [
    {
      id: 'quickstart',
      title: '1. Quick Start',
      intro: 'Three upload modes are available. The second button at the top-right switches between "file upload" and "clipboard upload".',
      items: [
        { t: 'File upload', d: 'Click or drag files into the drop area (multi-select). You can also pick a whole folder; the relative directory structure is preserved. Fill the folder input on top to target a directory, leave empty for root.' },
        { t: 'Clipboard upload', d: 'Switch to clipboard mode, then paste an image/file or one or more URLs.' },
        { t: 'Transfer (URL upload)', d: '"Transfer" makes the server fetch the URL and re-upload it through the current channel, returning a local link. "External" only registers the link without storing the file.' },
        { t: 'Naming (v2.8.8)', d: 'No longer offered in the upload settings — every upload follows Settings → Others → Upload-related config → Default naming, so the same account gets consistent file names everywhere.' },
        { t: 'Register File (v2.8.8)', d: 'A button right above "Upload settings" in the bottom-right quick toolbar, and another one next to "New folder" in the admin file manager. Use it to register a file that already lives on object storage or another image host: fill in the source URL, an optional name, channel, folder and note; type / size / MD5 are probed from the URL, upload time is the moment you submit, upload source is recorded as Record, and tags (year / extension / channel / type / Record) are added automatically. Nothing is uploaded again. Deleting a registered record removes the record only — the source file stays untouched.' },
        { t: 'Per-account transcode policy (v2.8.8)', d: 'In User management → edit → Admin actions you can set, per account: follow global / disabled / enabled / let the user decide. With "let the user decide", that account sees the same dropdown in Upload settings → File preprocessing (follow global / disabled / enabled) and it resets to "follow global" on every refresh. The policy applies to all upload entry points of the account (home page, link transfer, WebDAV, API-S3, API-Web).' },
        { t: 'Per-account file size limit (v2.8.8)', d: 'Set it in User management → edit → Admin actions; empty or 0 means the global limit. It applies to every upload entry point of that account, and the error message says whether the account or the global limit was hit. The old "type and size limits" switch has been removed.' },
        { t: 'Excluded compression formats', d: 'Sits right after File compression → Compression target (%): formats in this list skip compression and upload as-is (e.g. add mp4 to stop compressing video). Leave empty to exclude nothing — every compressible type follows the compression rules. Built-in compressible list: jpg/jpeg/jfif/png/webp/avif, mp4/webm/mov/m4v/mkv, mp3/m4a/aac/wav/flac/ogg/opus.' },
        { t: 'Size guarantee', d: 'If compression/re-encoding does not make the file smaller (equal or larger than the original), the result is discarded and the original is uploaded — never "compressed" into a bigger file. The only exception is video compatibility transcode: H.265/HEVC → H.264 is kept even when larger so browsers can play it, and the size change is written to the system log.' },
        { t: 'Video compatibility transcode', d: 'Settings → Others → Upload-related config → Video compatibility transcode: H.265/HEVC, ProRes and other browser-unfriendly codecs are transcoded to H.264 on the server (ffmpeg required). H.264/AV1/VP9 files pass through; independent of the compression switch.' },
        { t: 'Post-processing (major change in v2.8.8)', d: 'Compression and compatibility transcode for video / audio no longer run inside the upload request. Once the file is stored and the channel write succeeds the link is returned immediately, and compression / transcode run in a single background queue (at most one ffmpeg process at a time). Order is always compress first, then transcode — compression uses libx264 so its output is already H.264 and a successful compression skips transcoding entirely.' },
        { t: 'When post-processing gives up', d: 'Upload success always wins: (1) estimated time above 5 minutes (MEDIA_POST_MAX_SECONDS) → give up; (2) fewer than 2 CPU cores, 1-minute load above cores x1.5, or under 256MB free memory → skip; (3) compression is predicted to fail → give up on both; (4) compression succeeded but transcode is predicted to fail → keep the compressed file, drop the transcode; (5) execution timeout → give up. On any give-up the original object and record stay as uploaded, links keep working, and the reason is written to the system log.' },
        { t: 'WebP Conversion / File Compression are master switches (v2.8.8)', d: 'Both items in Settings → Others → Upload-related config were upgraded from "defaults" to master switches. Turning WebP Conversion off hides the Convert to WebP button in the upload list toolbar. Turning File Compression off hides the File Compression toolbar button and every compression option in the upload settings dialog, and also hides "Min compress threshold" / "Default compress target" in the admin — values are kept and come back when re-enabled.' },
        { t: 'Auto retry moved (v2.8.8)', d: 'The Auto retry switch from the upload settings now lives in Settings → Others → Upload-related config → Auto retry (the row right above Video compatibility transcode). It is stored in the database, applies to every account, and is no longer shown on the upload page.' },
        { t: 'Auto retry vs auto channel switch (split in v2.8.9)', d: 'v2.8.8 merged two different things into one switch; v2.8.9 separates them again. Auto retry on failure is the master switch (web upload, link transfer, WebDAV, API). Turning it on reveals Retry attempts underneath (empty = 3, 0 = unlimited; when the count is reached retries stop and failed files stay in the list). Auto channel switch is a separate item and only controls whether a failure moves to the next available channel. A new Other → Auto retry switch appears in Upload settings → File preprocessing (only when the master switch is on, and it only affects web upload and link transfer).' },
        { t: 'WebP give-up policy (v2.8.9)', d: 'The Convert to WebP button now sits right after File Compression and behaves the same way (click the icon to reveal the label and switch). If conversion fails or takes longer than 300 seconds it is abandoned, the original file is uploaded, and the reason shows up in the detail page Processing line.' },
        { t: 'Processing record (v2.8.9)', d: 'The file detail page gains a Processing line right below Redirect: retry count, failure reason, the channel it switched to, compression / transcode status and duration, why a step was skipped, and why WebP was not converted. The line is hidden when nothing extra happened.' },
        { t: 'File dimensions & dimension filter (v2.8.9)', d: 'Image dimensions in the detail page becomes File dimensions and is recorded for any file with known width/height (images, SVG, video — video is probed with ffmpeg). The filter dialog gains a Dimensions tab: landscape / portrait / 1:1 / 4:3 / 16:9 / 360p / 480p / 720p / 1080p / 2K / 4K / 8K presets (landscape and portrait are judged by the shorter side, so swapping width and height still matches) plus custom width and height ranges.' },
        { t: 'New filter fields (v2.8.9)', d: 'In General: Validity (limited / expired / permanent) below Redirect, and Name Status (renamed / original name) below Backup status. In Size: a Current size / Original size basis switch (default Current), and clicking a preset now fills the custom inputs with the value converted to a suitable unit. The tab strip scrolls horizontally on phones.' },
        { t: 'Upload directory option (v2.8.9)', d: 'When Upload-related config → Upload directory option is off, the folder input in the top right of the upload page and the directory picker in the bottom right toolbar are both hidden (previously only the suggestions were disabled).' },
        { t: 'Mobile header (v2.8.9)', d: 'In the admin file manager on phones: the sound toggle moves into the More menu (above the language item, labelled Enable sound / Mute sound), a Search button appears left of Refresh and expands the search box (collapsed again after a reload), and Filter follows it. On desktop the Refresh / Trash / Sound buttons get 4px more spacing on each side.' },
        { t: 'Register file improvements (v2.8.9)', d: 'The register dialog gains an optional Extension: use it when the source URL has no extension (e.g. Immich /api/assets/xxx); when the URL already has one the URL wins. Channel domains are no longer hard-coded — every access address in the channel config (public / internal / endpoint) is read, and when the host matches and there is no query string only the object path is stored, so the link is signed from the channel configuration exactly like a normal upload. External addresses keep their absolute URL.' },
        { t: 'Mobile swipe gestures (v3.0.0)', d: 'On phones the upload page list items support left/right swipes to quickly flip between entries and jump between the file-upload and link-transfer inputs, without tapping the top toggle.' },
        { t: 'Auto config refresh before upload (v3.0.0)', d: 'When the upload page opens and again right before each submit, the frontend re-fetches the latest settings (channels, compression / WebP / naming). Admin changes apply without the user manually reloading.' },
        { t: 'WebP conversion mode (v3.0.0)', d: 'When the WebP Conversion master switch is on, a WebP Conversion Mode item appears underneath (Lossless / Lossy, default Lossless); the upload settings can override it with Follow global / Lossless / Lossy. Lossless keeps the exact quality (slightly larger); lossy is smaller with minor quality loss. WebP and compression share the keep-the-original-if-bigger policy: if the result is not smaller, the original file is uploaded.' },
        { t: 'Instance switch (v3.0.0)', d: 'The avatar at the top-left of the upload page opens the Switch Instance dialog (default instance plus instances you own or joined); the small badge on the avatar is the number of the current instance. The choice is stored locally (localStorage gohub_instance_id) and subsequent uploads belong to that instance. The dialog footer also links to User Management and instance management. Each instance name in the dialog is prefixed with its number (the default instance shows none).' },
        { t: 'Register file (v3.0.0)', d: 'Domain matching now behaves the same for every channel: the source URL is tried against internal domain → public domain → Endpoint / service address, automatically falling through when one is empty. The file name prefers the real source file name and only falls back to "record-<timestamp>" when none can be read.' },
        { t: 'Camera capture with a live preview (v3.0.0 R8 / R8.1)', d: 'The camera button above Register file opens a real live camera preview (not a file picker): press Capture and the photo goes into the normal upload pipeline - uploaded immediately in auto mode, queued in manual mode; front and rear lenses can be switched. When the browser cannot use a camera or the page is not HTTPS, the dialog explains why and offers Use system camera (phones open the camera app directly).' },
        { t: 'Owner instance in upload settings (v3.0.0 R8)', d: 'Upload settings gains an Owner Instance dropdown under the backup channel: follow the current instance, force the default instance, or pin a specific one. The choice is saved with the upload settings and applies to every upload from that page (single file, chunked upload, link transfer).' },
      ]
    },
    {
      id: 'url',
      title: '2. Link Formats',
      intro: 'Four formats are generated for every file; the default one is used when copying.',
      items: [
        { t: 'Raw URL', d: 'e.g. https://your-domain/file/<File_ID>.jpg — the trailing extension is only a visual hint; the link also works without it.' },
        { t: 'Markdown', d: '![filename](url)' },
        { t: 'HTML', d: '<img src="url" alt="filename">' },
        { t: 'BBCode', d: '[img]url[/img]' },
        { t: 'Custom URL prefix', d: 'For CDN acceleration. Make sure the custom prefix is reachable.' },
        { t: 'About the extension', d: 'The backend strips the last extension when looking up the record, so both forms work and neither affects proxy forwarding, 302 redirects or access-source switching.' }
      ]
    },
    {
      id: 'channels',
      title: '3. Storage Channels',
      intro: 'Manage channels in Settings → Upload Settings. Nine types are supported.',
      items: [
        {
          t: 'Channel types',
          sub: [
            'Dedicated (own adapter): Tencent COS, MinIO, Cloudflare R2, S3-compatible, WebDAV, Immich',
            'Generic (shares the generic HTTP adapter with the Custom Web channel): EasyImages, Lsky Pro, Custom Web'
          ]
        },
        { t: 'Custom Web channel', d: 'Only three things are required: upload endpoint, file form field name and response URL path. Use the custom headers / extra form fields JSON for auth or extra params. Legacy token/headers/extraFields fields are still accepted.' },
        { t: 'Main & backup channel', d: 'The main channel uploads synchronously (drives latency); the backup channel is written asynchronously and never blocks the response. Each channel can be enabled independently.' },
        { t: 'Disabled channels (v2.8.6)', d: 'Turning a channel off removes it from every channel dropdown / picker (upload settings, tokens, user management, status page) and it no longer accepts uploads from any source: web, WebDAV or API requests that name it explicitly get a clear "channel disabled" error instead of silently landing on another channel.' },
        { t: 'Public / internal domain (v2.8.7)', d: 'Channel domain fields are now uniformly labeled "public access domain". EasyImages, Lsky, Immich, MinIO, S3, WebDAV and custom Web channels also support an optional "internal communication domain": set it to a container IP or container name and every internal file load (file manager, detail, history, public gallery, proxy fetching for issued links) prefers the internal address - faster and saves public traffic; falls back to the public domain, then the endpoint. The detail page "storage / backup channel" source links always use the public domain, and 302 redirect mode also uses the public domain. Since v3.0.0 a MinIO channel expects a bare domain in both fields — do not append /bucket. The bucket is inserted by the backend when building the link, so the final address is always domain/bucket/object-prefix/file (e.g. https://minio.example.com/gohub/2026/10/xxx.png). Stored object keys never contain the bucket (the S3 API takes Bucket separately; repeating it in the key would create bucket/bucket/...), so the bucket is added only at link-building time — consistently for streaming, 302 redirects and the detail-page source link. Legacy values that still contain /bucket are stripped on read, and legacy registered files whose key lacks the bucket get it added, so neither form produces a duplicated bucket.' },
        { t: 'Quota', d: 'Enable the quota switch to reveal the limit and alert threshold. Channels above the threshold stop receiving new uploads.' },
        { t: 'Local storage channel (v3.0.0)', d: 'Besides the built-in local channel you can now add a Local storage (custom path) channel: the storage address is a path inside the container (rootPath, pick a suggestion like /data, /app/uploads, /mnt or type your own), with an optional host-mapped directory (hostPath). Object prefix and custom naming work like any other channel, and a size limit can be enabled.' },
        { t: 'Built-in local channel path rule (v3.0.0)', d: 'The built-in channel (ID 999999) has a fixed storage address uploads (not editable). Files land as uploads / username / instance / object prefix: grouped by uploader first, then by instance when multi-instance is used, then the object prefix.' },
        { t: 'Multiple browse roots for local storage (v3.0.0 R8)', d: 'A Local files channel can now define several browse roots (one per line). The Local Files page lists all of them in the folder tree and switching a root only swaps the tree - the page is not rebuilt. Old single-root configs are read as a one-element list, so no migration is needed; the in-library check compares full paths, so roots never shadow each other.' },
        {
          t: 'Placeholder variables (v3.0.0 / expanded in round 9)',
          sub: [
            'Custom storage prefix supports: {y} year (4 digits), {m} month (2 digits), {d} day (2 digits), {ID} channel ID, {user} uploader name + 3 random digits (abc123 becomes abc123524), {domain} channel public domain (empty when not configured). Quick buttons next to the field (Channel ID / Username / Domain / Year / Month / Day) append the placeholder, including its leading slash.',
            'Custom naming supports: {hash} first 16 chars of the content hash, {filename} original name (no extension, sanitised), {uuid} random UUID (unique ID), {md5} file MD5, {timestamp} 13-digit millisecond timestamp, {ext} extension. Quick buttons: Hash / Filename / Unique ID / MD5 / Timestamp / Extension (inserts .{ext}).',
            '{filename} keeps only letters, digits, CJK characters, - _ and .; leading and trailing spaces are trimmed and inner spaces become -. When the template omits {ext} the original extension is appended automatically; an empty template now falls back to {hash} (first 16 chars of the content hash).'
          ]
        },
        { t: 'Test connection', d: 'Use "Test connection" when adding or editing a channel; a successful test returns a clickable direct link.' },
        { t: 'Unified field name "Endpoint / service address" (v3.0.0)', d: 'The field that used to be called Upload API address, service address or WebDAV address depending on the channel type is now uniformly labelled Endpoint / service address in every channel. Meaning and validation are unchanged (the upstream address of object storage, WebDAV and custom web channels) and existing values are kept as-is — nothing to migrate.' },
        {
          t: 'LAN / internal addresses (faster uploads)',
          sub: [
            'Channel addresses (Endpoint / service URL / upload endpoint) accept a LAN IP or a Docker container name, e.g. minio:9000, immich:2283, lsky:8080, 192.168.1.10:9000, nas.local.',
            'Typical setup: GoHub and MinIO / Immich / Lsky / WebDAV run on the same NAS and the same Docker network — internal traffic skips the public internet and any CDN, so uploads are noticeably faster.',
            'When the protocol is omitted it is inferred: internal hosts and container names get http, public domains get https (self-hosted services usually have no TLS, so blindly forcing https would fail).',
            'All channel traffic is initiated by the server (the backend PUTs/POSTs the file); the browser only submits the config. So the gohub being served over https does not prevent talking to http://minio:9000 internally, and mixed-content blocking does not apply.',
            'Reads can go internal too: the public/access domain is the domain prefix of the outbound link, and what it should be depends on the delivery mode. In proxy mode (default) the server fetches the bytes, so you may put an internal address there for the fastest read+write path while visitors still see the gohub domain. In 302 redirect mode the visitor browser opens that address directly, so it must be publicly reachable.'
          ]
        }
      ]
    },
    {
      id: 'deliver',
      title: '4. Link Delivery (proxy / 302)',
      items: [
        { t: 'Proxy mode (default)', d: 'The server fetches upstream bytes and forwards them. Links stay stable, Range requests work, and failures degrade to the other channel automatically.' },
        { t: '302 redirect', d: 'The browser hits the upstream storage directly — minimal server traffic.' },
        { t: 'Current access source', d: 'Switch between main and backup channel with one click; it applies to all existing links immediately.' },
        { t: 'Proxy parameters', d: 'Tune the upstream timeout and client cache duration (0 disables caching).' }
      ]
    },
    {
      id: 'dedup',
      title: '5. Deduplication (instant upload)',
      items: [
        { t: 'Rule', d: 'MD5 and size are computed from the ORIGINAL file before compression, then looked up right away: same MD5 and same size means duplicate — the existing link is returned without review, compression, transcoding or upload.' },
        { t: 'Why the original size', d: 'The compressed byte count of the same source file is not stable across quality settings (JPEG re-encoding, ffmpeg transcoding both vary). Comparing post-compression sizes makes the same file look like a new one, so the original size + original MD5 are used.' },
        { t: 'MD5 semantics', d: 'The MD5 stored on a record is the MD5 of the original file content, so older as-is uploads still match. Legacy rows without an original size fall back to the current size.' },
        { t: 'Scope: across all channels', d: 'Same MD5 + same size means duplicate (default, saves the most space).' },
        { t: 'Scope: same channel type (v2.8.7b)', d: 'Compares channel type first, then size + MD5 — dedupes among channels of the same type (e.g. multiple S3 channels), while different types each keep a copy.' },
        { t: 'Scope: same channel name (v2.8.7b)', d: 'Compares channel name first, then size + MD5: the same file can live in different channels (channels sharing a name still dedupe).' },
        { t: 'Toggle', d: 'The dedup switch and scope live in the storage/distribution settings; turn it off to always upload for real.' }
      ]
    },
    {
      id: 'backup',
      title: '6. Backups & Config Backup',
      items: [
        { t: 'Config backup / restore', d: 'On the System Status page, "Config Backup" exports the settings sections (page / security / others / AI, including whitelist, mail and page settings) as JSON; "Restore Config" writes it back, overwriting items with the same key. File records, storage channels and API tokens are not included.' },
        { t: 'Automatic mirroring', d: 'With a backup channel configured, every new upload is mirrored asynchronously.' },
        { t: 'Backup selected', d: 'Open File Management and use the batch action "Backup selected". The system detects which files lack a backup and only backs those up, reporting success / failed / skipped.' },
        { t: 'Backup badges', d: 'Card view shows backup channels next to the channel badge; list view has a dedicated "Backup Channel" column. In file details you can click a channel to open that file on that channel.' }
      ]
    },
    {
      id: 'manager',
      title: '7. File Management',
      items: [
        {
          t: 'Search syntax',
          sub: [
            'Plain keyword: fuzzy match on file name / File_ID',
            '#tag: include tag',
            '-#tag: exclude tag',
            'Combine freely: landscape #mountain -#water'
          ]
        },
        { t: 'Filter dialog (v2.8.7)', d: 'The filter button now opens a dialog with four tabs: "General" (all original conditions: access status, black/white list, review result, file type, backup status, redirect, channel type / name, upload method), "Tags" (tag presence plus multi-select specific tags with any/all match), "Date" (quick picks: today / yesterday / day before yesterday / this week / last week / this month / this year, plus a calendar range), and "Size" (<100K / <1M / <10M / <100M / >100M quick picks plus custom min/max). The dialog is fixed at 96% of the viewport height, centered both ways, with no jump when switching tabs; any tab with values shows a badge on the button and a dot on the tab label. All conditions combine with the search box, search scope, user filter and trash state into one backend query (also effective inside the trash). The former standalone tag button in the toolbar has been removed — tag filtering now lives in the Tags tab of the dialog (v2.8.7c).' },
        { t: 'Video mute toggle (v2.8.7)', d: 'A sound button next to the trash button: muted by default (hover preview and file detail videos stay silent); click to enable sound. Videos always start muted for instant playback and then follow the toggle (browsers block unmuted autoplay, which previously stalled the picture); closing the detail dialog or dismissing the hover preview stops any playing video/audio for good — the media elements are destroyed on close and cannot be revived by background buffering or page updates; reopening the dialog reloads and replays (v2.8.7c). The choice is remembered across pages.' },
        { t: 'Duplicate-upload guard (v2.8.7)', d: 'Retrying after a network hiccup during "merging" no longer creates duplicate files: the merge endpoint is idempotent (a completed session returns the previous result) and re-submitting an already-uploaded file is blocked with a clear notice. The "merging" toast no longer stacks.' },
        { t: 'Mobile file manager (v2.8.7)', d: 'List view shows the file size next to the channel badge; the checkbox / view / sort row becomes a single horizontally scrollable line; the folder card hover layer no longer shows a delete button (use the batch action bar).' },
        { t: 'Sorting', d: 'By upload time, file size, raw name, display name, and by view count.' },
        { t: 'View count', d: 'Incremented on every real external access; admin previews are excluded so refreshing the console does not inflate it. Hover a card to see it, or check the list column.' },
        { t: 'Preview eye (v2.8.6)', d: 'The eye icon on the left of a card\'s third row: hover on PC to preview the full image/video; long-press on mobile to preview (centered, release to close). In list view, long-press the thumbnail on mobile for the same preview.' },
        { t: 'Trash (v2.8.6)', d: 'The trash banner clearly states files can be restored or permanently deleted (irreversible), highlighted with a stronger background.' },
        { t: 'Trash pagination & delete spinner (v3.0.0 R12)', d: '① The trash is now server-paginated at 48 items per page (the normal file list stays at 24) with pager and "load more" appending; ② while deleting / restoring / purging in the file manager or trash, the affected card or row is covered by a spinner mask ("Deleting… / Processing…") to prevent double clicks; ③ registered empty folders can now really be deleted (previously only their files were trashed and the folder stayed), together with their folder properties.' },
        { t: 'Folder rename & folder operations fixed (v3.0.0 R12)', d: '① The custom folder name from Folder properties now applies everywhere — folder cards, directory navigation (current chain / global tree) — and takes effect immediately after saving (the real path never changes); ② batch-moving folders accepts plain folder names like "Manga" without a leading slash (auto-prefixed); ③ registered empty folders move together with the batch move; ④ the success count includes folders and the directory navigation refreshes afterwards.' },
        { t: 'Lightbox enhancements (v3.0.0 R12)', d: '① Image / video lightbox spans 100% width edge-to-edge and the zoom buttons lose their shared frame; ② arrow keys stay silent while controls are hidden and 3× long-press no longer lights them up; ③ on mobile, swipe up plays a random video and swipe down opens the file detail without scrolling the page; ④ the TXT lightbox is full-height with larger left-aligned text and a "copy all" button; ⑤ video "TOC / settings" buttons align with the prev/next arrows; ⑥ a heart button below "next" opens a rating / level / tags panel without leaving the lightbox; ⑦ the PDF preload strip no longer covers the viewing area; ⑧ the video snapshot upload failure is fixed.' },
        { t: 'Media compress/transcode guard (v3.0.0 R13)', d: 'Under Other settings → Upload config, a new "Media Compress/Transcode Guard" switch (on by default) sits below Frontend Concurrency. When on it reveals two inputs — "load1 Load Factor" (default 1.5) and "RAM Floor (MB)" (default 256): before compressing or transcoding a video/audio file the server checks load and free memory; if load1 exceeds factor × CPU cores OR free memory is below the floor, the job is skipped, the file uploads normally with the original kept, and the reason is logged. Set either input to 0 to disable that check; turn the master switch off to skip all resource checks. Image compression is unaffected; in Docker the readings reflect the host machine (WSL2).' },
        { t: 'Cross-device polish (v3.0.0 R14)', d: '① Home: the upload directory row is right-aligned on desktop, the mobile directory tree loads reliably (timeout + retry, root expanded), capture uses a 3:4 portrait frame with burst shooting and reset zoom, and every upload re-reads the directory box; ② Local files: files already in the library are skipped (new "In library" filter), the tree can collapse / expand all, the desktop top bar stays pinned, and list rows get a permanent select circle; ③ File manager: deleted folders appear in the trash and can be recreated (restoring merges contents), selecting one folder reveals every folder checkbox, filters add TXT/PDF ("Other" excludes them), folder sharing defaults to read-only, edit-share users can rate, and the mobile back button walks up one directory at a time (root no longer leaves the page); ④ Lightbox: the favourite heart is gone, copy sits left of details, opening details pauses audio/video, mobile swipe-up picks a random image/audio, snapshots upload in the background without closing, TXT is full-height and centred; ⑤ Misc: whole-star rating only, "No rating / No level" wording, outline hearts by default, "Original Name" label, automatic "Local upload / Video snapshot" tags plus `#hashtag` extraction, and a 2FA prompt before purging trash.' },
        { t: 'File names (v2.8.6)', d: 'Cards / list / history / public pages all use the same middle-ellipsis: head and tail (with extension) are always kept.' },
        { t: 'Views & batch actions', d: 'Card / list views; batch copy links, download as zip, move, tag, block/whitelist, delete, and backup selected.' },
        { t: 'Click actions (v2.9.0)', d: 'Card cover / list thumbnail opens the media viewer (image lightbox, video player, audio player, or a generic dialog for other types); the file name still opens the file detail page. The hover-preview eye is unchanged.' },
        { t: 'Image lightbox (v2.9.0)', d: 'Full screen over a dim, slightly blurred grey backdrop. Top-left shows the file name and size; the top bar has slideshow (1 / 2 / 3 / 5 / 8 seconds per slide), actual size / fit-to-window and close; the bottom strip is a thumbnail reel you can click through. Side arrows or ← → switch, Space toggles the slideshow, Esc closes. Clicking the image also toggles actual size / fit.' },
        { t: 'Video player (v2.9.0)', d: 'Full-screen playback with the name at top-left, close at top-right, and "More settings" at bottom-right: playback speed 0.5×–2× and play mode (loop single / shuffle / sequential, rotating through the videos on the current page).' },
        { t: 'Audio player (v2.9.0)', d: 'Collects every audio file on the current page into one playlist; click any row to play, it advances automatically and stops after the last one. Rows show the index, name and size.' },
        { t: 'Generic dialog (v2.9.0)', d: 'For files that are not image / video / audio, the dialog shows a type icon, name, size and uploader with Copy link / Open link / View details actions.' },
        { t: 'Auto-hiding controls (v2.9.0)', d: 'After two idle seconds the top bar, arrows and thumbnail reel fade out and come back on mouse move or touch. The video settings panel stays visible while open so it can still be clicked.' },
        { t: 'Filter: deleted (v2.9.0)', d: 'The General tab now offers "Deleted" in access status so soft-deleted files can be filtered in the normal list. Entering the trash automatically drops this condition to avoid a conflict.' },
        { t: 'Filter: users tab & load more (v2.9.0)', d: 'A new "Users" tab replaces the old user dropdown, loading the 30 most recently created users with a "Load more" row; the Tags tab behaves the same way. Both lists are sorted newest first.' },
        { t: 'All / Any and Or / And (v2.9.0)', d: 'With two or more conditions selected, an All / Any switch appears next to "Clear filters" in the footer and decides whether different groups must all match or any match. Inside the Tags tab, two or more selected tags get their own Or / And switch that only affects tag names and never touches the global switch.' },
        { t: 'Registered files (v2.9.0)', d: '① An empty folder field now defaults to "Record/current year/current month"; ② opening the dialog from the admin file manager prefills the current directory; ③ after registering on the upload page the record appears in the file list immediately with its signed link, no refresh needed; ④ links are resolved by matching the source URL against internal domain → public domain → API endpoint, dropping the matched part and keeping the rest as the storage path; if none matches, registration fails with a clear reason.' },
        { t: 'Rename (v2.9.0 fix)', d: 'The rename input is read-only: the button generates a 48-character random File_ID (upper/lower case + digits) that is checked against existing names, and typing is no longer possible. Renaming only changes the display name — it no longer clears the folder or moves the file to the root.' },
        { t: 'Toolbar buttons (v2.9.0)', d: 'Refresh / Trash / Sound now share the Filter button style (transparent, 32×32, themed icon); New folder / Register file / History share the Sort button palette; on phones their padding and margins are tightened and the group is right-aligned.' },
        { t: 'Search scope entry (v2.9.0)', d: 'The "show folders / expand all" items that used to hide in the search icon dropdown moved next to the card/list switch as two icon buttons (folder tree / list), with the active one highlighted.' },
        { t: 'Show folders / expand all & load more (v3.0.0)', d: 'In "show folders" mode directories render as cards and you enter one to see its files; "expand all" flattens every file regardless of folders. Long lists render the most recent slice first, keep loading as you scroll down and also back-fill an earlier slice when you return to the top (two-way lazy loading), staying smooth even with huge libraries.' },
        { t: 'Batch edit: original name / expiry / redirect / encryption (v3.0.0)', d: 'With multiple files selected you can do all of this in one pass: restore / set the original name (the extension is preserved automatically, only the base name changes), set an expiry (links die at the deadline), toggle redirect, and encrypt / decrypt — all three in one dialog, confirmed from the bottom batch bar.' },
        { t: 'Tag management modes (v3.0.0)', d: 'Tag management now uses a three-column card layout (all tags / editor / preview) with a search box on top; a tag can be split into several, given a note, and opened for public sharing, on top of drag-to-reorder, locking, merging and batch apply / remove.' },
        { t: 'Folder properties (v3.0.0)', d: 'A folder\'s context / more menu opens Folder properties: rename, sharing (generates a share entry), public sharing (generates the guest gallery link), notes, and encrypting the whole folder.' },
        { t: 'Directory scope: current / global (v3.0.0)', d: 'The folder dropdown can switch between "folders of the current instance" and "all folders on the site", so you can compare paths and move files across instances.' },
        { t: 'Instance switch moved into the page dropdown (v3.0.0)', d: 'The instance switch no longer has its own button in the file manager; it lives in the top page-switch dropdown. Lists, filters and batch actions only touch files inside the selected instance.' },
        { t: 'Mobile back key goes up one level (v3.0.0)', d: 'On a phone, pressing the system back key inside a folder returns to the parent folder instead of leaving the file manager.' },
        {
          t: 'Public sharing: folders & tags (v3.0.0)',
          sub: [
            'Folders and tags can each be opened for public sharing: a switch, an access password (leave empty for none) and a deadline after which the link stops working.',
            'Folder share URL: /browse/username/instance-number/cate/folder-path',
            'Tag share URL: /browse/username/instance-number/tag/tag-name',
            'Instance number: 0 = the default instance, 1..n ordered by instance creation time (identical to the badge on the upload page avatar). The same folder / tag gets a different URL after switching instances.'
          ]
        },
        { t: 'Share records page (v3.0.0)', d: 'File manager → Share records: enable / disable, set or change the password, encrypt and delete one by one, or in bulk (enable / disable / encrypt / delete), filtered by user and instance so stale shares are easy to clean up.' },
        { t: 'Guest gallery is read-only (v3.0.0)', d: 'Visitors who open a share link can only browse: the folder input is gone, so they cannot jump to another path, and no management action is exposed.' },
        { t: 'File link passwords only use the file\'s own encryption (v3.0.0)', d: 'Since v3.0.0 a /file link only honours the file\'s own encryption. Folder and tag passwords now only gate visibility inside the guest gallery / share page and no longer apply to the link itself — a password-protected folder still hands out password-free links.' },
        { t: 'Filter "AND / OR" (v3.0.0)', d: 'The global switch on multi-condition filters (previously "All / Any") decides whether different condition groups must all match or any match. The Tags tab keeps its own AND / OR switch that only affects tag names, independent of the global one.' },
        { t: 'Shared-by / shared-with and encrypted filters (v3.0.0)', d: 'The user dimension of the filter dialog gains "shared by me / shared with me"; the General tab gains an "encrypted" condition (encrypted / not encrypted) so files awaiting or already holding encryption are easy to find.' },
        { t: 'Detail page: grouped processing records (v3.0.0)', d: 'Processing records are grouped: failure / retry / WebP / compression / transcode. Each group only lists entries relevant to this file (retry count, failure reason, the channel it switched to, status and durations, why a step was skipped); empty groups are hidden.' },
        { t: 'Detail page: the three "did compression run?" cases (v3.0.0)', d: 'The compression row states exactly what happened: ① compression disabled (turned off globally / per account, or the format is in the excluded list); ② skipped because WebP ran (the file is already WebP, so it is not compressed again); ③ below the threshold (the original is smaller than the compression threshold).' },
        { t: 'Detail page: instance / encryption / expiry / share thumbnail (v3.0.0)', d: 'The detail page adds "instance" and "file encryption" rows; expiry moved to its own line above the divider (next to redirect and processing records, much easier to scan); share card thumbnails are fixed to a 3:4 ratio.' },
        { t: 'Lightbox: auto-hide / long-press 3x / directory (v3.0.0)', d: 'Lightbox controls fade out after 2 seconds of inactivity (any touch or movement brings them back); long-press an image to browse at 3x speed and release to restore; a new Directory button at the top jumps to the image list of the current page; in "actual size" mode the image is centred and pinned to the top; the back key / Esc closes the lightbox.' },
        { t: 'Folder sharing loading rule (v3.0.0 R3)', d: 'Folders shared "to users" no longer appear in the normal list automatically - sharees must use Filter > User sharing > Shared with me to load them (sub-folders included). Shared files show a Shared badge at the bottom-right of cards and after the channel short name in list view; sharees can open shared files without hitting the 401 admin-preview check.' },
        { t: 'Search / filter auto-expand (v3.0.0 R3)', d: 'Submitting a search or filter while in "show folders" mode automatically switches to "expand files"; switching back to folders manually is remembered and will not be overridden again.' },
        { t: 'Mobile file management (v3.0.0 R3)', d: 'Enter in the search box now submits on mobile (fixed missing key events); New folder / Register file / History are icon-only buttons; the instance badge on the Page switcher floats on the icon corner instead of squeezing the title.' },
        { t: 'Batch settings (v3.0.0 R3)', d: 'The combined Expiry / Redirect / Password batch dialog is renamed "Batch settings" with tab order Expiry > Password > Redirect.' },
        { t: 'Detail page item order (v3.0.0 R3)', d: 'Fixed order: Name, Type, Size, Dimensions, Category, Tags, Status, Instance, Storage channel, Backup channels, Upload user, Upload source, Duration, Speed, IP, Views, Upload time, MD5, Encryption, Redirect. Closing the detail dialog now stops any playing video / audio.' },
        { t: 'Lightbox swipe (v3.0.0 R3)', d: 'On mobile, when an image is in "actual size" or zoomed in, horizontal swipe pans the image instead of switching photos; swiping switches photos only in "fit window" mode.' },
        { t: 'Register file: URLs with query strings (v3.0.0 R3)', d: 'Query strings (e.g. .../api/thumbnail?key=abc&size=preview&c=1&edited=true) are preserved end-to-end - issued links keep all parameters; when the path segment is an action word (thumbnail / preview / original), the real file name is also looked up in query values (key=2026/abc.webp > abc.webp).' },
        { t: 'Shared badge on both sides (v3.0.0 R7)', d: 'The Shared badge now shows for the initiator and the sharee alike — on folder cards and file rows (card bottom-right / after the channel short name in list view), with the owner visible on hover. The sharee badge was missing because the frontend dropped the shared fields computed by the backend; fixed. Badges also survive the "all instances" scope.' },
        { t: 'One-click reset via the stats button (v3.0.0 R7)', d: 'The "total files" readout at the top-right is now a button: with no search / filter / tag / user condition it just shows the count; once any condition exists (button lights up), one click clears the search box, #tags, -tags, filter dialog conditions and user filter, and leaves search mode (inside the trash it returns to the full trash list), with a success toast.' },
        { t: 'Hover to expand the directory dropdown (v3.0.0 R7)', d: 'On desktop, hovering the directory navigation for ~0.3s expands the dropdown and loads all site-wide folders — no click needed; it closes on leave or after picking a folder. Touch devices and viewports ≤1023px keep click-to-open.' },
        { t: 'Toolbar badges & state colors (v3.0.0 R7)', d: '① The trash button gains an orange-red dot in trash mode, with a light red background and red icon while active; ② the tag button uses a larger font and a more visible orange-red dot; ③ the filter badge is smaller on phones; ④ the AND / OR switch at the bottom of the mobile filter dialog is left-aligned.' },
        { t: 'Mobile second-row panel (v3.0.0 R7)', d: 'The glass panel behind the mobile toolbar row (checkbox / views / sort / directory / new) has a 5px radius, 4px vertical and 3px horizontal padding, and sits closer to the top bar; expanding the mobile search box moves the search area into the first row and pushes the second row down, so they no longer overlap.' },
        { t: 'Lightbox: mistouch guard / full-screen PDF / tables (v3.0.0 R7)', d: '① txt, PDF, audio, spreadsheet and other non-media viewers now fill the screen with a transparent backdrop; tapping empty space only restores the controls instead of closing the lightbox (use close or Esc to exit); ② the PDF area is truly full-screen with a floating gradient toolbar; ③ CSV / TSV files render as scrollable tables (sticky header) inside the lightbox, and text preview applies too.' },
        { t: 'Folder sharing: switch + read-only / editable (v3.0.0 R8)', d: 'The Share block in folder properties is now a switch: turn it on, pick the users, then pick a permission - Editable lets them enter the folder and change properties but never delete it; Read-only hides the selection circle and the properties entry entirely (tapping the name just enters the folder, with a read-only toast). No sharee can delete a shared folder: the button is hidden for UX, and the backend rejects the request naming the owner. The owner is unaffected - their own folders and files can still be deleted; the restriction only applies to sharees.' },
        { t: 'File rating and level (v3.0.0 R8)', d: 'The detail dialog gains two rows: Rating (five stars, half-star steps, clearable) and Level (five hearts, 1-5, tap again to clear). Both are dedicated columns rather than note metadata and are stored immediately. The permission matches notes: the uploader or an admin can edit, other sharees are read-only.' },
        { t: 'Rating filter tab (v3.0.0 R8)', d: 'The filter dialog gains a Rating tab: quick chips for rating (5 stars / 4+ / 3+ / unrated) and level, plus custom 0-5 ranges (rating supports 0.5 steps). Unrated means exactly 0 (set both range boxes to 0); leaving the boxes empty means no restriction. Works in the list and in the trash.' },
        { t: 'Seven lightbox improvements (v3.0.0 R8)', d: '① Markdown files get an outline panel that scrolls the text to the chosen heading; ② PDFs keep a fixed close row at the top (never auto-hidden) and show a document navigation strip at the bottom on desktop; ③ closing the lightbox on mobile no longer bounces the page up one folder; ④ audio autoplays on open and when switching tracks; ⑤ a Detail button sits left of Close in every mode; ⑥ Actual size / Fit window moved to a centred bar above the thumbnail strip, flanked by zoom-out / zoom-in buttons (10% per click); ⑦ videos gain a snapshot button that saves the current frame as PNG. (R8.1) Images, video and audio no longer show the extra copy / open / detail block - that generic panel only appears for file types that cannot be previewed.' },
        { t: 'Mobile lightbox no longer goes up a folder (v3.0.0 R8)', d: 'Closing the lightbox used to occasionally navigate one folder up on phones. Closing calls history.back() to drop the lightbox history sentinel, which fires a popstate that the page treated as a user back press. The lightbox now stamps a timestamp before doing so, and the page ignores such programmatic popstate events for half a second.' },
        { t: 'Storage settings and the three-domain model (v3.0.0 R10)', d: '"Upload data settings" is renamed "Storage general settings", and "Custom access domain" becomes "Signing domain" — every link issued by this site uses it, falling back to X-Forwarded-Host → Host → localhost when empty. It never overrides a channel public domain. The three domains now have distinct jobs: signing domain (site /file output), file load domain (per channel: internal domain first in proxy mode, otherwise public domain) and public domain (storage/backup links in file details, 302 target).' },
        { t: 'Links store only the tail (v3.0.0 R10)', d: 'Each copy now stores objectPath (URL without scheme://host) and urlQuery (file-level query such as Immich key/size/edited); the domain is never persisted. URLs are built as dynamic domain + frozen path + query, so changing a domain takes effect immediately while changing a bucket, prefix, name template or album id does not break existing files. Special characters and extension-less links are encoded per segment, never double-encoded.' },
        { t: 'Dedup clones instead of borrowing links (v3.0.0 R10)', d: 'A dedup hit clones a record (and copy rows pointing at the same remote object) for the current uploader or instance. Password, expiry, redirect, link permission and view counts are fully independent, and remote objects are deleted only when the last reference is purged.' },
        { t: 'Registered files strip the domain (v3.0.0 R10)', d: 'The source URL is compared by URL.host against the channel load domain (or the signing domain for local storage); the matched domain segment is removed and only the tail is stored. Deleting a registered record still never touches the remote file.' },
        { t: 'Built-in local-files channel 999990 (v3.0.0 R10)', d: 'The system creates a built-in local file browser channel with code 999990 at startup. Its root is fixed to the built-in uploads directory and it cannot be deleted or re-pointed; administrator-created local-file channels keep working independently.' },
        { t: 'Channel deletion is stricter (v3.0.0 R10)', d: 'A channel cannot be deleted while any copy references it, including trash items and registered files across all users and instances. The message breaks down totals, trash and registered counts.' },
        { t: 'Admin thumbnails use proxy + resize (v3.0.0 R10)', d: 'File manager cards/lists, history and recent uploads now request /file?thumb=320: the server fetches through the internal domain, resizes with sharp and caches for 30 days. Local storage thumbnails are resized too, and nothing depends on the admin browser reaching an internal address.' },
        { t: 'Local storage honours the name template (v3.0.0 R10)', d: 'Fixed: local storage ignored the custom prefix / name template because it used the legacy key branch. It now follows the same placeholder rules as other channels, defaulting to {hash} when empty.' },
        { t: 'EasyImages / Lsky remote delete (v3.0.0 R10)', d: 'Delete credentials from the upload response are now kept: EasyImages uses the signed del URL, Lsky calls DELETE /api/v1/images/:key with the stored data.key. Both previously lacked credentials, so remote files were left behind.' },
        { t: 'Storage prefix & user archiving (v3.0.0 R11)', d: 'The {user} placeholder now renders the current account username directly (no random digits), and the quick-insert buttons are Channel ID / Username / Year / Month / Day, appending /{ID}, /{user}, /{y}, /{m}, /{d} to the input. Local storage defaults to {user}/{ID}/{y}/{m} when the prefix is empty; the custom local channel storage path is a plain input (autocomplete no longer forced off).' },
        { t: 'Delete links drop the domain too (v3.0.0 R11)', d: 'The EasyImages delete URL used to be stored with its domain, breaking remote deletion after a domain change. Only the path and query (deletePath/deleteQuery) are persisted now and the URL is rebuilt from the current channel domain; existing records get the same treatment.' },
        { t: 'Local-files channel creation fixed (v3.0.0 R11)', d: 'Creating a local-files channel no longer fails with a bogus rootPath requirement: the browse directories (rootPaths, one per line) are validated instead, and the host mapping stays optional. The built-in 999990 channel shows its browse directory read-only.' },
        { t: 'Immich registered-file thumbnails fixed (v3.0.0 R11)', d: 'Registered Immich files failed to render thumbnails/previews because the share-auth query (?key=…) was dropped when building fetch candidates. Fetching now uses the same dynamic domain + frozen path + full query as detail links.' },
        { t: 'Frontend concurrency (v3.0.0 R11)', d: 'A new "Frontend concurrency" setting (in Other settings → upload config, right above Auto retry) controls how many files the browser uploads at once; empty means 3. It refreshes automatically each time you click Upload / Transfer.' },
        { t: 'Mobile toolbar spacing (v3.0.0 R11)', d: 'On mobile the second toolbar row (select-all / view toggle) sits 8px below the header and 10px above the file area; when stuck it keeps the same 8px gap and exactly the same width as normal. Scrolling down hides it with the header; it resets when you scroll back. Header bars on all admin pages turn fully opaque (glass blur off) once the page is scrolled, and return to glass at the top.' },
        { t: 'Detail page address semantics (v3.0.0 R11)', d: 'In the file detail dialog the Storage / Backup channel links use the public access domain (the external address), the "Source" uses the file loading domain (the address the server actually fetches from), and the preview loads via the site-issued signed link.' },
        { t: 'Lightbox: bigger images, snapshot, stacked detail (v3.0.0 round 9)', d: '① Images now use the whole area between the title row and the thumbnail strip (the zoom bar no longer takes its own row) and the zoom-out / size-toggle / zoom-in buttons float above the image; ② the PDF document strip hides together with the other controls while the close row stays visible; ③ the video snapshot button moved from the bottom-right to the top bar, left of Detail, and More settings / Table of contents now line up vertically with the next / previous arrows; ④ snapshots are saved under the original file name, with (1) (2) suffixes on duplicates; ⑤ after saving, the viewer asks whether to upload the snapshot to the image bed in one click; ⑥ Detail no longer closes the lightbox - the detail dialog is stacked above it and the lightbox (including video playback) is kept when the dialog closes.' },
        { t: 'Channel Settings rename and trash icon (v3.0.0 round 9)', d: 'The admin Upload Settings tab is now called Channel Settings (related hints updated too); Object prefix is renamed Custom storage prefix (optional) in every channel type; the trash Restore button finally shows an icon (the undo icon had never been registered).' },
        { t: 'File manager: rating filters and card badges (v3.0.0 round 9)', d: '① Rating / level quick filters now offer six steps (five stars / four and up / three / two / one / unrated; five hearts / four and up / three / two / one / unrated); ② the Rating tab moved right after Tags; ③ cards show an empty star and heart at the bottom-left with the value overlaid when set, and the eye button / hover preview was removed everywhere; ④ the channel-name filter no longer lists Local Files; ⑤ the top sentinel auto-loader is gone - only the Load more button loads more; ⑥ the directory nav button now shows the full path (the desktop breadcrumb was removed); ⑦ the second row spacing is halved and the mobile count / history buttons share one height (28px).' },
        { t: 'Local Files: duplicated paths fixed (v3.0.0 round 9)', d: 'Fixes a path duplication introduced by the multi-root support: files inside sub folders got their full relative path repeated (lf-test/sub/sub/inner.txt), so previews returned 404 and the tree showed phantom folders. The list endpoint now returns paths relative to the current folder plus bare folder names, and the client joins them. On mobile the folder button uses a folder icon in the first row, and thumbnails are square (1:1).' },
        { t: 'Upload page and sharing (v3.0.0 round 9)', d: '① The mobile camera dialog is full screen (100dvh), the shutter moves into an auto-hiding bar toggled by tapping the frame, and the rear lens is the default; ② the upload settings button shows the selected owner-instance number in a badge (default instance = 0); ③ share recipients (read-only or editable) no longer see edit / delete in the detail dialog and batch delete is blocked; ④ email verification codes accept six letters or digits (backend validation relaxed to match).' },
      ]
    },
    {
      id: 'history',
      title: '8. History & Status',
      items: [
        { t: 'History', d: 'Top-right "More" → History on the upload page; File Management also has a History button. Records live in the local browser (localStorage) and can be viewed as grid/list, copied, deleted individually or cleared.' },
        { t: 'System status', d: 'File totals plus channel, upload method, user, file type and status distributions. The upload trend can be grouped by channel type, channel name, user, upload method and file type, with a selectable date range. "Recent uploads" lists the latest 20 records, followed by today / yesterday / week / month / year counts, total space used and folder count (click a count to open History).' },
        { t: 'Upload method (v2.8.6)', d: 'Every file records the entry it came from: Default = legacy web uploads before v2.8.6; Upload = the upload page in "file" mode; Fetch = the upload page in "link" mode (saved from URL); WebDAV / API-Web / API-S3 = external channels. The file detail "upload method" field, the file manager filter and the status page distribution all use these values.' },
        { t: 'Logs', d: 'Records writes (upload / save / delete) plus 4xx, 5xx and slow requests, with level/scope/keyword filters and export.' },
        { t: 'Mobile (v2.8.6)', d: 'Upload trend tabs scroll horizontally when they overflow; History / Access log top bars scroll away with the page instead of staying pinned.' },
        { t: 'Access log date filter (v2.8.8)', d: 'On phones the two-month range picker always overflowed the screen, so it is now a button that opens a single-month panel (the same calendar used by Status → Trend preview). With a range selected the button is highlighted and shows the start/end dates, and the small cross on the right clears it back to "all time". Desktop keeps the original range picker.' },
        { t: 'History instance names (v3.0.0 R7)', d: 'With "All instances" selected, each record now shows the instance it really belongs to (the backend returns the instance id and name with the list) instead of labelling everything "default instance"; records of the default instance still read "default instance".' }
      ]
    },
    {
      id: 'security',
      title: '9. Security',
      items: [
        { t: 'Two auth layers', d: 'Separate passwords for the user side and the admin console.' },
        { t: 'Whitelist mode', d: 'Only whitelisted files stay reachable; other requests get the whitelist notice image.' },
        { t: 'Allowed source hosts', d: 'One "host:port" per line, e.g. 192.168.1.3:5505 or img.example.com:8443. Matching is exact on the source host + port; paths and query strings are ignored, and the same host on another port counts as a different source. Pasting a full URL works too — only the host part is kept.' },
        { t: 'Image review & IP lookup', d: 'Optional review provider tags uploads so you can block rejected content.' },
        { t: 'Public share permission (v3.0.0)', d: 'The admin decides which accounts may create public shares in the Share permission section; the account-level switch lives in the Public sharing module of the user edit page. When it is off the account sees no share entry and existing shares stop being publicly reachable (records are not deleted — turning it back on restores them).' },
        { t: 'API tokens', d: 'Issue scoped, expiring tokens for scripts and third-party tools; revoke any time. Both "S3 protocol" and "Web generic" access are supported.' },
        { t: 'compress field (Web generic)', d: 'Send compress=true or 1 in the custom Body to compress (images via sharp, video/audio via ffmpeg, GIF skipped); omit it to upload as-is — the global "default compression" setting does not apply to this channel. compressPercent optionally sets the target size (10-100 % of the original).' }
      ]
    },
    {
      id: 'instances',
      title: '10. Instances (v3.0.0)',
      intro: 'An instance is an isolated grouping of files: one account can create several instances to organise files by purpose, while channels and global settings stay shared.',
      items: [
        { t: 'Create / invite / join', d: 'In User edit → Instance management: create an instance (name required and unique; the note is visible to the owner only). The owner issues an 8-character invite code; anyone can join by entering the code and can then upload into that instance.' },
        { t: 'Data isolation', d: 'Every instance has its own file space: files, trash and history are isolated per instance, and regular members only see instances they joined. The built-in local channel also separates directories by username / instance.' },
        { t: 'Shared configuration', d: 'Storage channels, upload-related settings and system settings remain global / account-level; switching instances never changes them. Only the file layer is isolated.' },
        { t: 'Deletion precondition', d: 'An instance that still contains files (trash included) cannot be deleted; you must empty it first. Deleting an instance removes only the grouping, never member accounts.' },
        { t: 'History instance filter', d: 'The history page can filter by instance and defaults to "All instances" (no instance filter, and the last choice is no longer remembered); picking one shows only records of that instance. Pagination at the bottom is a manual "Load more" button instead of infinite scroll. The page loads only your own records by default; an admin arriving from User management → Collect by user → View records lands here with that user in a new tab.' }
      ]
    },
    {
      id: 'structure',
      title: '11. Code Structure',
      intro: 'Frontend and backend are separated: NestJS + Prisma + SQLite on the server, Vue3 + Vite + Element Plus on the client.',
      items: [
        { t: 'backend/src/main.ts', d: 'Entry point: global middleware, static assets and link routes (/file, /dav), HTTP server on port 3619.' },
        { t: 'backend/src/app.module.ts', d: 'Module wiring: registers every controller/service into the Nest container under the /api prefix.' },
        { t: 'backend/src/upload/', d: 'Upload core. upload.controller.ts implements the HTTP contract (/upload, /api/fetchRes, chunked upload); upload.service.ts handles channel resolution, dedup, compression, primary upload, backup and persistence.' },
        { t: 'backend/src/adapters/', d: 'Storage adapters (strategy pattern): adapter.factory.ts creates an instance per channel type; each adapter implements upload / delete / buildDirectUrl. Adding a channel type means adding one adapter and registering it in the factory.' },
        { t: 'backend/src/channels/', d: 'Channel management: CRUD, secret encryption (CryptoService), connection test, quota stats, main/backup uniqueness, plus the plaintext refill endpoint used by the edit dialog (GET /api/manage/channels/:id/plain).' },
        { t: 'backend/src/files/', d: 'File management and link distribution: list query (filters / search type / sort / paging), detail, delete, batch actions, redirect, backup-all, system logs and status statistics; LinkController serves external links (white/black lists, whitelist mode, domain filter → proxy or 302; proxy supports Range and image resizing).' },
        { t: 'backend/src/users/', d: 'User management: account CRUD, permissions (editable / deletable / enabled), grouping by account or by IP; the built-in admin is not in the users table — its nickname / channels / enforcement live in the admin profile (sysConfig:adminProfile).' },
        { t: 'backend/src/tokens/', d: 'API tokens: issuing and authorising S3 and Web tokens (token-api.controller.ts).' },
        { t: 'backend/src/webdav/', d: 'External WebDAV: mounts the image bed as a network drive (OPTIONS / PROPFIND / GET / PUT / MKCOL / DELETE); configured under Settings → Others.' },
        { t: 'backend/src/settings/', d: 'Settings centre. sysconfig.service.ts reads/writes whole config sections (page / security / upload / others / ai); settings.service.ts provides key-value access with an in-memory cache.' },
        { t: 'backend/src/auth/', d: 'Authentication: unified account check (super → users table → security settings → env vars), HttpOnly cookie sessions, three route guards.' },
        { t: 'backend/src/common/', d: 'Shared utilities: Prisma client, log centre (app-log.ts, 7-day retention), access control and file view serialisation (file-view.ts), rate limiting.' },
        { t: 'frontend/src/views/', d: 'Pages: UploadHome, AdminDashBoard, CustomerConfig (users), SystemConfig, HistoryPage, Login / SuperAdmin, PublicBrowse, DocsPage.' },
        { t: 'frontend/src/components/upload/', d: 'Upload page components: UploadForm, UploadFileItem, UploadSettingsDialog.' },
        { t: 'frontend/src/components/config/', d: 'Settings sections: SysCogStatus, SysCogUpload (channels), SysCogSecurity (security / tokens), SysCogLog, SysCogOthers (includes WebDAV), SysCogPage, SysCogAI.' },
        { t: 'frontend/src/utils/', d: 'Utilities: fileManager (list query params), clipboard (compatibility layer), fetchWithAuth, upload/urlBuilder (link formats).' },
        { t: 'backend/src/common/record-link.ts (v2.9.0)', d: 'Link rules for registered files: recordDomainCandidates collects the three channel domains (internal / public / API endpoint), matchRecordSource matches by content segment and strips it to get the path, recordLoadOrigin decides which domain is used when reading (internal first, falling back to public / endpoint), and joinRecordUrl builds the final link.' },
        { t: 'frontend/src/components/dashboard/MediaPreviewOverlay.vue (v2.9.0)', d: 'Media viewer: image lightbox (slideshow, actual size, thumbnail reel), video player (speed, loop single / shuffle / sequential), audio playlist for the current page, and a generic dialog for other types; controls auto-hide after two seconds. FileCard / FileListItem only emit the previewMedia event and never build links themselves.' },
        { t: 'backend/src/instances/* (v3.0.0)', d: 'Multi-instance: instances.controller.ts exposes the /api/instances endpoints (list / create / rename / delete / invite codes / join / member management); instances.service.ts owns instance & membership data and validates deletion preconditions (instances with files, trash included, are refused).' },
        { t: 'backend/src/files/folder-meta.service.ts (v3.0.0)', d: 'Folder metadata service: persistence and validation for renaming, encryption, notes, sharing and guest-gallery properties of folders.' },
        { t: 'frontend/src/components/dashboard/FolderPropsDialog.vue (v3.0.0)', d: 'The Folder properties dialog: rename / encrypt / notes / share / guest gallery in one place.' },
        { t: 'frontend/src/components/dashboard/ShareDialog.vue (v3.0.0)', d: 'The Share dialog: builds a share card with thumbnail and expiry and copies the share link.' },
        { t: 'frontend/src/components/dashboard/TagModePanel.vue (v3.0.0)', d: 'The tag management panel: drag ordering, tag locking, merging and batch apply / remove.' },
        { t: 'backend/src/shares/* (v3.0.0)', d: 'Public sharing: shares.controller.ts exposes the /api/shares endpoints (list / create / edit / batch enable·disable·password·delete) plus the visitor side /api/shares/public/access and /api/shares/public/list. shares.service.ts handles password checks, deadline evaluation, instance numbering and path resolution, and sets the gohub_share_pw cookie (httpOnly, 7 days) once a password check passes.' },
        { t: 'backend/prisma/compat-sync.js (v3.0.0)', d: 'Schema upgrade compatibility script: before db push it cleans up historical duplicate data that would trip unique constraints (duplicate tags merged into one, duplicate names suffixed) and retries automatically when db push still reports a unique-constraint warning — so upgrades no longer need --accept-data-loss.' },
        { t: 'frontend/src/views/ShareRecordsPage.vue (v3.0.0)', d: 'Share records page: enable, disable, encrypt and delete shares one by one or in bulk, filtered by user and instance; it reuses the shares API instead of keeping its own copy of the data.' }
      ]
    },
    {
      id: 'roadmap',
      title: '12. Development Outline',
      intro: 'Suggested reading and change order for secondary development.',
      items: [
        { t: 'Step 1: run it', d: 'Backend: npm run start:dev. Frontend: npm run dev (Vite proxies /api and /upload to 3619). Verify you can upload and get a working link.' },
        { t: 'Step 2: understand one upload', d: 'Start from POST /upload, then follow upload.controller.ts → upload.service.ts upload(): channel resolution → dedup → compression → primary upload → backup → FileRecord / FileCopy.' },
        { t: 'Step 3: add a channel type', d: 'Add an adapter under backend/src/adapters/, register it in adapter.factory.ts, add config fields and labels in channel-schema.js, and add the type to CHANNEL_TYPES in SysCogUpload.vue.' },
        { t: 'Step 4: add a setting', d: 'Settings use section JSON: add defaults in sysconfig.service.ts defaults(section), then read/write it from the matching SysCog*.vue — no database change needed.' },
        { t: 'Step 5: change the schema', d: 'Edit backend/prisma/schema.prisma → npx prisma db push → npx prisma generate, then restart the backend. Since v3.0.0 db push first runs backend/prisma/compat-sync.js (duplicate tags merged, and so on) and retries on failure, so --accept-data-loss is no longer needed.' },
        { t: 'Step 6: add a page', d: 'Create the page in frontend/src/views/, then register the route in router/index.js with the proper guard (userAuthGuard / manageAuthGuard / adminAuthGuard / superAuthGuard).' },
        { t: 'Convention (important)', d: 'Field names for channel types, roles and settings must stay identical across frontend and backend. Channel display names are duplicated in backend/src/common/file-view.ts (CHANNEL_LABEL) and frontend/src/components/config/channel-schema.js (CHANNEL_SHORT_LABEL).' }
      ]
    },
    {
      id: 'deploy',
      title: '13. Deployment',
      intro: 'Docker Compose is recommended, but plain Node works too.',
      items: [
        {
          t: 'Option A: Docker Compose (recommended)',
          sub: [
            'Copy .env.example to .env and at least change CONFIG_SECRET (channel secret master key)',
            'Optionally set ADMIN_USER / ADMIN_PASSWORD (initial admin account)',
            'Optionally set SUPER_ADMIN_USERNAME / SUPER_ADMIN_PASSWORD to enable the super admin (password recovery)',
            'Run docker compose up -d --build',
            'Open http://server-ip:3619 and sign in with the admin account'
          ]
        },
        {
          t: 'Option B: without Docker',
          sub: [
            'Install Node.js 18+ (20 / 22 recommended)',
            'Backend: cd backend && npm install && npx prisma db push && npm run build && node dist/main.js',
            'Frontend: cd frontend && npm install && npm run build (output goes to frontend-dist in the project root)',
            'In production keep the backend alive with pm2 / systemd and serve the static build through Nginx, proxying /api, /upload, /file and /dav',
            'Default port is 3619, overridable with the PORT environment variable'
          ]
        },
        { t: 'Persist these', d: 'backend/data (SQLite database) and backend/logs (logs, automatically pruned to the last 7 days). Mount ./data when using Docker.' },
        { t: 'Upgrading', d: 'Docker: docker compose pull then docker compose up -d --build. Non-Docker: rebuild the backend and restart it, then rebuild the frontend and replace the static directory.' },
        { t: 'Database upgrade (v3.0.0)', d: 'Since v3.0.0 db push runs compatibility clean-up first (duplicate tags merged and similar), so no manual --accept-data-loss is required. If a unique-constraint warning still appears the script retries automatically and normally needs no manual intervention.' },
        { t: 'Reverse proxy notes', d: 'Forward Host, X-Forwarded-For and X-Forwarded-Proto. WebDAV needs non-standard methods (PROPFIND / MKCOL / PUT) to pass through — Nginx allows them by default, some cloud gateways need explicit rules.' }
      ]
    },
    {
      id: 'accounts',
      title: '14. Accounts & Permissions',
      intro: 'Three account roles exist; all sign in with username + password.',
      items: [
        { t: 'Administrator (admin)', d: 'The fallback account comes from ADMIN_USER / ADMIN_PASSWORD (default admin / gohub). It can access all of User Management and System Settings. Change the password right after deployment.' },
        { t: 'Super administrator (super)', d: 'Defined only by SUPER_ADMIN_USERNAME / SUPER_ADMIN_PASSWORD; disabled by default. Its purpose is recovering a forgotten admin password: after signing in it can only reset the admin username / password and is not visible in User Management.' },
        { t: 'Standard user (user)', d: 'Created by an administrator in User Management. Can upload files, see its own files/folders and its own history; no access to user or system management. The administrator can toggle edit/delete permission, disable the account and assign main/backup channels.' },
        { t: 'Settings precedence', d: 'Upload settings: frontend upload settings > account-level channels in User Management > global defaults, falling back step by step.' },
        { t: 'Security advice', d: 'Always change CONFIG_SECRET in production, enable HTTPS with secure session cookies, revoke unused API tokens and never expose the database file publicly.' }
      ]
    },
    {
      id: 'faq',
      title: '15. FAQ',
      items: [
        { t: '"Pasted URL request failed"?', d: 'Make sure the server can reach the URL (avoid login-protected private addresses). localhost and private ranges are allowed, but the target must respond.' },
        { t: 'Link returns 404?', d: 'Check whether the file was deleted or blacklisted, and whether the channel config (domain, bucket permissions, WebDAV path) is correct.' },
        { t: 'Does the extension break anything?', d: 'No — it is purely cosmetic. Proxy, 302 and access-source switching all work off the File_ID.' },
        { t: 'Uploads feel slow?', d: 'The main channel uploads synchronously. Prefer a faster channel, or offload via the backup channel. For large files use object storage (COS / MinIO / R2 / S3).' },
        { t: 'Why does the thumbnail no longer open the detail page?', d: 'Since v2.9.0 thumbnails and covers are for viewing (lightbox / players) while the file name is for managing (detail page). Click the name to rename, tag or copy links.' },
        { t: 'Registration says the source URL does not belong to the channel?', d: 'None of the domains configured on that channel appear in the URL. Check that the right channel is selected and that the URL contains the channel\'s internal domain, public domain or API endpoint (ports and paths are fine, the host must match). Nothing is recorded when all three miss — the record would not be loadable anyway.' },
        { t: 'Are instances isolated? Do settings need to be redone?', d: 'Files (including trash and history) are isolated per instance and regular members only see instances they joined. Storage channels and upload settings stay global / account-level and are shared by every instance — nothing to configure twice.' },
        { t: 'Why does "All" mode return nothing when I pick images + videos?', d: '"All" means every condition group must match, but a single file has exactly one type — it cannot be both an image and a video. Use "Any" for mixed results, or multi-select within the file type group.' },
        { t: 'Lossless or lossy WebP?', d: 'Lossless (default) is pixel-identical to the original — best for screenshots and design assets. Lossy is typically 20-40% smaller, ideal for photos. Either way, if the converted file is not smaller the original is kept automatically.' },
        { t: 'Changed a local channel\'s object prefix — do old files still work?', d: 'Yes. The prefix only affects where NEW uploads are stored. Existing records keep their actual stored path, so links keep working; old and new files simply live at different path levels.' },
        { t: 'A folder / tag is password-protected — why does the file link still ask for a password? (v3.0.0)', d: 'Since v3.0.0 a /file link only honours the file\'s own encryption. A folder or tag password only gates browsing inside the guest gallery / share page and no longer applies to the link. If the link still asks for a password, that single file is encrypted — decrypt it from the file detail page.' },
        { t: 'A public share link does not open — where to look? (v3.0.0)', d: 'Check three things in order: ① the Public sharing switch of that folder / tag is still on (it may also be turned off globally by the account\'s Public sharing module or the admin Share permission); ② the deadline has not passed (the share records page shows it); ③ the instance number in the URL is correct — 0 is the default instance and 1..n follow instance creation time, so after switching instances an old URL points at another instance and the link must be copied again under the current one. If a password was set, it must be entered too.' },
        { t: 'Upgrading shows a unique constraint error — what now? (v3.0.0)', d: 'Do not add --accept-data-loss. Since v3.0.0 db push runs compat-sync first (duplicate tags merged into one, for example), and a unique-constraint warning during the push triggers an automatic retry. Only a repeatedly failing upgrade needs the log inspected to find the table with duplicate data.' }
      ]
    },
    {
      id: 'localFiles',
      title: '16. Local Files (new in v3.0.0)',
      intro: 'The Local Files page browses files that already exist on the server (or in a mounted directory). It is read-only by default; selected files can be copied into the image bed as normal records.',
      items: [
        { t: 'Create the channel', d: 'System settings → Upload → New channel, type "Local files". Only the browse root (a path inside the container, e.g. /data) is required — map a host directory there when running in Docker. Host mount directory is documentation only and is never read or written. This type never takes part in uploads: it is filtered out of every channel dropdown and cannot be set as main / backup channel or enabled in the pool. Since v3.0.0 (R5) the Local Files channel is admin-only and no longer supports authorisation.' },
        { t: 'Who can see it', d: 'The Local Files entry in the page switcher is always visible to admins (even before any channel exists — the page then prompts to create one); regular users never see it. Since v3.0.0 (R5) the channel no longer supports per-user authorisation.' },
        { t: 'Browsing', d: 'Collapsible folder tree, breadcrumbs, double-click to enter a folder, type filter (images / videos / audio / text / PDF / other), sorting by name / size / modified time, search by name or path, and pagination. Browse settings (top right) control items per page (default 48), max entries per folder (default 500) and inline preview limit (default 500 MB).' },
        { t: 'Top bar & scroll behaviour (v3.0.0 R7)', d: 'The toolbar holds the page switcher (with instances), a channel dropdown (remembered across refreshes and revisits; falls back automatically if the channel is deleted or disabled), then Upload to image host, search, type filter, sort, asc/desc, refresh, settings and the day/night toggle. Scrolling down slides the bar out of the way; scrolling up snaps it back immediately. The folder tree fills the remaining viewport height and stays pinned while the page scrolls, and its collapse button is now a fixed-size square that no longer squashes.' },
        { t: 'Video thumbnails & multi-select (v3.0.0 R7)', d: 'Videos show a real frame as the thumbnail (the browser seeks to 0.5s once metadata loads) instead of a grey icon; every file has a checkbox at its top-left for batch "Upload to image host", and clicking the checkbox never triggers the preview.' },
        { t: 'Preview and download', d: 'Images, videos (seekable via Range requests), audio, PDF and text files (txt, md, json… truncated beyond 200 KB) preview inline; other types download when their thumbnail is clicked. The preview endpoint only accepts a channel ID plus a relative path, requires a logged-in session and is excluded from file access statistics.' },
        { t: 'Upload to the image bed', d: 'After selecting files, choose the target channel / instance / upload folder. Every file runs through the normal upload chain (MD5 dedup → compression or transcode → write to channel → record → issue link) and the source file is left untouched. The result dialog lists the file ID and link (one-click copy), duplicates skipped, and failures (one-click retry).' },
        { t: 'In-library badge', d: 'Files already uploaded show an "In library" badge: sizes are compared first and only matching files are hashed, so a page never hashes everything. Hovering shows the matching file ID. Detection is read-only.' },
        { t: 'Drawer and paging on phones (v3.0.0 R8)', d: 'On phones the folder tree moves into a left drawer; the toolbar becomes two rows (page switcher and channel, then search / type / sort / refresh) and the search box collapses behind a button. Lists load 50 items per page with a 200-item cap per folder and a Load more button; file names elide in the middle (head + tail) so the extension is always visible.' },
        { t: 'Safety boundaries', d: 'The root must exist and be a directory and is re-checked with realpath before use (symlink escapes are refused). Every relative path rejects ".." and hidden segments and is rejected when it escapes the root. .env, .git, node_modules and names starting with "#" are never listed or served. The page is read-only: the only write path is "upload to image bed".' }
      ]
    },
    {
      id: 'whatsnew',
      title: '17. What is new in v1.0.0',
      intro: 'v1.0.0 adds no new modules. It is about isolation, the media lightbox, back-button layering and when settings are saved. Everything stays backward compatible: an existing database keeps working without manual migration.',
      items: [
        { t: 'Folders and tags are now isolated by user and instance', d: 'Empty folders created with "New folder" were stored per account only (settings.extraFolders) with no instance dimension, so a folder created in instance A also showed up in instance B. The storage key is now "account::instance"; the default instance keeps the old key, so existing data needs no migration. Tags work the same way: the tags table gained an owner column and the unique key changed from (name, instance) to (name, instance, owner). Listing, renaming, deleting, merging and splitting all stay inside your own tags.' },
        { t: 'The directory picker only loads the current instance', d: 'The tree button in Upload settings and in the record-file dialog now sends the current instance (localStorage gohub_instance_id) to /api/directoryTree. The "Pick upload directory from tree" tooltip has been removed, leaving only the icon button.' },
        { t: 'Filter / tag management / batch tagging / popular tags', d: 'All four used to call the API without an instance (one even hard-coded an empty instanceId), so tags from every instance and every account were offered. They now pass the current instance and filter by tag owner.' },
        { t: 'Lightbox steps within the same file type only', d: 'Previous / next, arrow keys and the slideshow all cycle inside the current file type: an image lightbox only walks images, a video lightbox only videos, and PDF / text / audio stay separate. The arrows are hidden when the current type has a single file. Swipe-up random switching is also restricted to the same type.' },
        { t: 'Pinch to zoom in the image lightbox', d: 'Two fingers pinch-zoom the image on phones (0.2x to 5x) around the midpoint between the fingers; after zooming, drag with one finger to pan, and releasing below "fit to window" snaps back. Pinch gestures never trigger paging or taps.' },
        { t: 'Silent video auto-advance and a visible cursor', d: 'When a video ends and the next one starts, the lightbox stays silent (no custom controls, no cursor change) while the native playback bar keeps working. Previously the whole overlay switched to cursor:none after auto-advance, so the pointer vanished and the controls were unreachable; the video lightbox now always keeps the system cursor.' },
        { t: 'Upload settings save on blur', d: 'The upload directory and the "do not compress" extension list now only update a local draft while typing; the value is saved (and confirmed) when the field loses focus, on Enter, on clear, or when the dialog closes. No more "one save and toast per keystroke". Switches and sliders still save immediately.' },
        { t: 'Consistent save button on the user edit page', d: 'The save action on /customerConfig/edit/ is the same floating bottom-right button used by System settings → Page settings (identical on desktop and mobile), and a successful save returns to the user list at /customerConfig.' },
        { t: 'Pinch to zoom in the video lightbox too', d: 'Same gesture set as the image lightbox: pinch with two fingers to zoom the video picture (0.2x to 5x) around the midpoint between them, snapping back if you release below the original size. Zoom resets when switching files, closing the lightbox or changing the screen orientation, so it never carries over.' },
        { t: 'No more back-swipe animation at the screen edge on mobile', d: 'A horizontal swipe starting at the left or right screen edge is treated by WebKit / Chromium as a back gesture and draws a stretch animation at the edge. It is now suppressed everywhere: only a gesture that starts inside the 16px edge band and is dominated by horizontal movement is swallowed, so in-page horizontal toolbars (search bar, breadcrumb button row, filter tabs) still scroll. Applies to the dashboard background and every dialog / lightbox.' },
        { t: 'Back and Esc close one layer at a time', d: 'The lightbox and the file detail dialog stacked above it each pushed their own history sentinel and each listened for popstate, so one back press was consumed by both and both layers closed. They now share a single layer stack: the mobile back key / edge swipe and the desktop Esc close only the topmost layer — the detail dialog first, then the lightbox on the next press.' },
        { t: 'Tag management is scoped to each user on each instance', d: 'In tag management every account only manages the tags it owns inside the current instance: split, merge, rename, note, encryption, public sharing and delete are all checked against (user + instance), and administrators no longer manage other people\'s tags. Two privilege leaks were fixed as well: tag public sharing can no longer match a same-named tag owned by someone else, and the tag filter / autocomplete endpoints no longer return the whole instance when no one is signed in.' },
      ]
    },
    {
      title: '18. What is new in v1.0.1',
      intro: 'v1.0.1 turns automatic tagging from hard-coded rules into configuration, tightens the local storage channel, completes trash restore, and adds keyboard control to the lightbox. No database changes — a straight overwrite upgrade works.',
      items: [
        { t: 'Automatic tags are now configurable in the backend', d: 'The hard-coded rules (file type / extension / channel short name / upload source / year, plus #hashtag extraction) are gone. They live in System settings → Other settings → File tag rules, right after Image transform. Three parts: (1) Placeholders compose tag names with {mime}, {ext}, {channelName}, {uploadSource}, {y}, {m}, {d}, {width} and {height}; separate with commas or newlines, one tag per segment, and placeholders without a value are skipped. (2) Extract from file name maps ["text":"tag"] so any file name containing the text gets the tag. (3) Custom rules take one regular expression per line and use capture group 1 as the tag name (the default is the old #hashtag rule). All three can be combined, results are de-duplicated (20 chars per tag, 30 tags at most), and invalid regexes are skipped and written to the system log.' },
        { t: 'Local storage path must be a mapped directory', d: 'Storage path (in-container path) is now a filterable dropdown instead of a free-text field. Options come from the container\'s real mount points (/api/manage/channels/mounts parses /proc/self/mountinfo and filters out pseudo mounts such as /proc, /sys, /dev and /etc/hosts). Unmapped paths never appear and cannot be selected, because files written there live only in the container writable layer and vanish when the container is rebuilt. An amber warning appears when the current value is not in the list.' },
        { t: 'Sync a local storage channel into Local files', d: 'A new switch sits right after the storage path. When enabled, that storage directory shows up in the channel picker of the Local files page (/localFiles) for browsing, previewing and batch upload; disabling it removes the entry without touching uploaded files. No separate "local files" channel is needed.' },
        { t: 'Restoring from trash brings the folder back', d: 'Deleting a folder also clears its folder registration and properties, so restoring a single file left the folder itself in the trash and its properties lost. Restoring files (single or batch) now reinstates every ancestor folder that is still in the trash: it re-registers the folder, restores its property snapshot and removes it from the trash folder list.' },
        { t: 'Empty directories are reclaimed after a permanent delete', d: 'When a file on a local storage channel is permanently deleted and its directory becomes empty, the directory is removed as well and the cleanup walks upward until it hits a non-empty directory or the channel root (the root is never deleted). Only directories that read as empty are removed, concurrent writes are unaffected, and a failure is logged without blocking the delete.' },
        { t: 'Permanent delete shows a spinner too', d: 'Besides the card / row overlay used by soft delete, the Restore and Delete-permanently buttons inside the file detail dialog now spin and disable as well — previously the overlay was hidden behind the dialog, so clicking gave no feedback at all.' },
        { t: 'Folders can no longer be selected', d: 'In the dashboard folders are never selectable: cards and list rows no longer show a checkbox, "Select this page" and Shift range selection only apply to files, and the mobile long-press "Select" action tells you to open the folder instead. Folders can still be entered, inspected, copied, moved and deleted through their own entry points.' },
        { t: 'Moving across instances copies tags', d: 'When a file moves from one instance to another, its tags are copied into the target instance while the source instance keeps its own tags and links. An existing tag with the same name in the target instance is reused instead of duplicated, and ownership follows the original tag. Folders moved across instances copy the tags of every file inside them.' },
        { t: 'Lightbox keys: ↓ random, ↑ details', d: 'On desktop, in the image / video lightbox, ↓ jumps to a random file of the same type and ↑ opens the file details while pausing the running video / audio (closing the details keeps the lightbox open). ← → still step through in order, and Esc is still handled by the layer stack.' },
        { t: 'Browser history works again for the upload directory field', d: 'The upload directory inputs on the home page and in Upload settings now carry a stable name plus autocomplete="on", so the browser remembers and suggests directories you typed before.' },
        { t: 'Release layout', d: 'From v1.0.1 on, all Docker-related files (Dockerfile, compose files, deploy scripts, image tarballs) live in the docker/ directory at the project root; dist/ only holds the sanitized production sources that can be published to Git.' },
      ]
    },
    {
      title: '19. What is new in v1.0.2',
      intro: 'v1.0.2 withdraws the temporary "folders are not selectable" limit from v1.0.1 and fixes the root causes behind it (moves silently doing nothing, cross-instance folder moves losing the folder, trash restores not bringing the folder back). Tag identity also moves from "name + instance + user" to "instance + type + name". The database gains one column automatically, so a straight overwrite upgrade works.',
      items: [
        { t: 'Folders are selectable again, and batch actions really work', d: 'Cards, list rows, Select-this-page, Shift range selection and the mobile long-press menu all support folders again: selecting a folder means selecting everything inside it. Moving takes the whole folder (with all its files) to the new location, and deleting puts the whole folder into the trash. Read-only shared entries still cannot be selected.' },
        { t: 'Folders in the trash restore as a whole package', d: 'A folder deleted as a package appears as a single "folder" entry in the trash, and expanding it shows exactly what went in with it. Restoring brings the files and the folder back to their original place. If a folder with the same name already exists there, the two are merged — nothing is lost and no duplicate folder is created.' },
        { t: 'Moving a folder with a duplicate name across instances now merges', d: 'Previously, moving a folder into another instance that already had a folder with the same name failed on the folder-properties unique constraint. It now merges: the target instance keeps its own folder properties, files land inside that folder, and no error or duplicate folder appears.' },
        { t: 'Reclaimed empty directories drop their registration and property snapshot', d: 'When a permanent delete leaves a directory empty and it gets removed from disk, its entry in the Added directories list and its property snapshot are removed as well, so no ghost folder is left behind. Cleanup walks upward from the deepest level, stops at the first directory that still has content, and never touches the channel root.' },
        { t: 'Tags are identified by instance + type + name', d: 'Uniqueness moved from "name + instance + user" to "instance + type + name": one tag per name per instance, shared by all accounts, with the creator kept on owner for auditing only. The tag table gains a type column (currently file, reserved for notes / articles / todos / navigation later), and login, upload, sharing, batch tagging, merge and split all go through the same lookup. Duplicate historical tags are merged once at startup — idempotent and safe to run again.' },
        { t: 'Custom tag rules are now three plain fields', d: 'Instead of writing a regular expression, you now fill in three inputs: the start characters (such as # or @ and &), the stop characters (space, comma, full stop, dash and so on), and the maximum length. When several start characters appear in a row the last one wins, over-long matches are dropped, and whitespace always stops a match. The defaults reproduce the old #hashtag behaviour, so nothing needs re-configuring after the upgrade.' },
        { t: 'The channel short name always comes from the main channel', d: 'With main + backup dual write, a file exists on both channels, and the channel tag used to follow whichever channel actually stored the file — so a batch could end up with mixed tags. As long as dual write is allowed the tag now always uses the main channel; only when backup is explicitly disabled does it follow the channel that really stored the file.' },
        { t: 'Changing the local storage path requires the admin password', d: 'Editing Storage path (in-container path) on a local storage channel after it has been saved now asks for the current admin password first. Only a successful check is written to the database, and the change is recorded in the system log. This prevents the storage root from being silently pointed elsewhere.' },
        { t: 'Permanent delete from the trash shows a spinner', d: 'While a permanent delete (single or batch) runs, the whole page shows an overlay with "Deleting…" and locks interaction; it closes automatically when the operation finishes, so it no longer looks frozen.' },
        { t: 'Inside the lightbox, back closes the details first', d: 'With file details opened on top of the image / video lightbox, the back button, edge-swipe back and Esc now always close the details first and only the next press closes the lightbox. The two layers used to fight over the same event, leaving the details dialog behind after the lightbox was gone.' },
        { t: 'Two inputs became multi-line', d: 'Host mapping directories (optional) on local file channels is now a multi-line text box — one directory per line, matched to Browse directories in order. Extract from file name in Other settings is multi-line too, so longer rule sets can be written one per line instead of scrolling horizontally.' },
        { t: 'Session lifetime settings now really apply', d: 'Fixed "set 90 days in user management but still logged out several times a day". First, any single unauthenticated response used to clear the session immediately — a backend restart, a momentary 502 or a proxy hiccup all counted; the client now re-confirms with the server and only logs out when the session is genuinely gone. Second, the cookie issued at login uses the largest of the account settings, and saving a new value re-issues it under the new lifetime.' },
      ]
    },
    {
      title: '20. What is new in v1.0.3',
      intro: 'v1.0.3 does three things: it scopes the file manager to each account, adds moving files between local and third-party channels, and gives the trash a real folder hierarchy. Two index changes and one column are applied automatically, with duplicate data merged before the upgrade — a straight overwrite works.',
      items: [
        { t: 'The file manager only shows your own files', d: 'Previously, when an administrator opened the dashboard without picking a user, the list showed every account\'s files — and allowed renaming, moving and deleting them. Now every account, administrators included, only lists the files it uploaded; batch actions, the trash, the folder tree and folder navigation are all scoped to the signed-in account. For read-only cross-account access use folder sharing or public sharing.' },
        { t: 'New Move to Local / Move to Remote: switch storage without changing the link', d: 'A new button after Download in the file details: files on a local storage channel offer Move to Remote, files on a third-party channel offer Move to Local. Pick the target channel and the file is transferred byte-for-byte — no compression, no transcoding, no WebP conversion, same name. The issued link, name, type, size, category, tags and upload time all stay the same; only the channel, the resolved address and the delete target change.' },
        { t: 'Source handling when moving', d: 'Moving from a third-party channel back to local requires a choice: keep source (download and update the data only) or delete source (remove the original channel file after a successful move, irreversible). Moving from local to remote always deletes the local file, otherwise the same data would occupy local disk twice. Registered files — records whose bytes were never uploaded here — can never have their source deleted, because the source lives outside GoHub.' },
        { t: 'The trash browses by folder', d: 'The trash is no longer one flat list: the root shows deleted folders plus files that were deleted from the root, and you enter a folder to see what was deleted inside it. The banner shows the current folder with an Up one level button. Folder entries restore or purge as a whole package, including folders that only lost their files.' },
        { t: 'Moving shows a full-screen overlay', d: 'While a move runs (single or batch), the page shows "Moving…" and locks interaction, then closes automatically — no more "clicked and nothing happened".' },
        { t: 'Back navigation inside the lightbox is stable now', d: 'The same file-details dialog used to be registered twice — once by the component, once by the automatic overlay watcher — so the fallback entry ended up on top. Back then went through the "click the close button / dispatch Esc" path, and when there was no clickable close button the press was simply swallowed, which is exactly the "sometimes it works" symptom. Each dialog is now registered once: back / Esc reliably closes the details first and the lightbox second, while open dropdowns inside the dialog still collapse first.' },
        { t: 'Day / night switch time is configurable', d: 'System settings → Page settings → Global settings now has Day / Night Switch Time right below Background Opacity. Leave it empty for 08:00—20:00 (day at 08:00, night at 20:00). With the theme set to Auto it is evaluated against this range instead of the OS colour scheme, and a page left open all day flips at the boundary on its own.' },
        { t: 'Tag uniqueness moved into the database', d: 'The tag key is now instance + type + name; the old name + instance + creator key is gone. One tag per name per instance, so the "tag exists but some files are missing from the filter" case disappears. Historical duplicates are merged before the upgrade, so it cannot fail on existing data.' },
        { t: 'Folder categories gained a type dimension', d: 'The folder properties table now carries a type field with the same semantics as tags: file categories today, and independent note / article / todo / navigation categories later, each able to keep its own properties for the same path.' },
        { t: 'Super admin sessions are fixed at 1 day', d: 'The environment-configured super administrator is an emergency recovery role, so its session is fixed at one day, ignoring the per-account setting and offering no configuration. Regular administrators still follow the days configured on their own account.' },
      ]
    },
    {
      title: '21. What is new in v1.0.4',
      intro: 'v1.0.4 adds no features — it closes the gaps left by the previous release: where a moved file actually lands and how many copies it leaves behind, the three-part tag rule actually taking effect, mobile back navigation matching desktop, the wait before a large preview appears, plus a cache header that marked login-only content as publicly cacheable. No schema change; a straight overwrite upgrade is enough.',
      items: [
        { t: 'A moved file lands on the target channel and copies stop multiplying', d: 'In v1.0.3, moving a remote file to local with Keep source put the result on the backup channel, left the original primary record untouched, and made the detail panel show two backup channels. The cause was three different notions of "which copy is primary" living side by side — the copy table flag, the channel-level main flag, and simply taking the first array element — with nothing reconciling them. There is now a single resolver: primary and usable, then primary, then the copy on the main channel, then the first element. Serving, the detail panel and the random list all use it.' },
        { t: 'Moving now relocates the primary copy in place', d: 'Each move used to demote every copy and insert a new one, so copies grew with every transfer and never matched the displayed channel. The source copy row is now rewritten onto the target channel — including regenerating its key from that channel\'s own settings — keeping the total unchanged. If the target channel already holds a copy of the same file, that row is overwritten and the source row removed, so one file never has two rows on one channel.' },
        { t: 'Backup channels now lists only real backup channels', d: 'The detail panel used to define backup channels as "every usable copy except the primary", which swept ordinary copies in — that is where the second backup channel came from. Only copies on a channel flagged as backup are listed now; ordinary copies are reported separately as other copies.' },
        { t: 'Keep source means: primary moves, the old channel keeps a fallback', d: 'The semantics are explicit now. Whichever direction you move, the primary copy always ends up on the channel you moved to; Keep source simply leaves an ordinary copy behind as a fallback. Nothing inside the backup channel is touched.' },
        { t: 'Tag rules now actually apply', d: 'Three fixes. The default stop-character value was in the wrong format — splitting on commas produced multi-character tokens that could never match a single character, so the rule silently did nothing when no stop characters were configured. Leaving the start field empty now means "from the beginning of the file name", and only at position zero, so it cannot turn every segment into a tag. And a tag that runs to the end of the file name has its extension stripped, so no more "landscape.png" results eating into the length limit. Whitespace is always a stop character, hardcoded and not configurable.' },
        { t: 'Browse directories no longer asks for the admin password on file channels', d: 'The admin password requirement for changing a storage path stays, but it is now scoped to local storage channels only. Browsing a directory just lists what is inside; it writes nothing and changes no path, so it no longer asks for a password.' },
        { t: 'Mobile back navigation matches desktop', d: 'The previous release fixed the root cause of back navigation skipping a layer, but it was only verified on desktop. Mobile had its own "is this a phone" check, written three times with different criteria, which is why back on a phone dropped straight to the page behind. The check is now unified around touch capability, back sentinels are re-synced on orientation change, and narrowing a desktop window no longer misclassifies it as a phone.' },
        { t: 'Large previews no longer sit on a blank screen', d: 'Two causes. Every session check recomputed an expensive key derivation (about 120 ms), so a screen of thirty thumbnails wasted three seconds before anything appeared; that result is now reused within the process. Separately, video and images load differently by nature: video streams progressively and shows a first frame from the opening bytes, while an image must arrive whole before it can decode — and the image may live on a third-party channel across the public internet. The lightbox now paints a blurred layer from the already-cached list thumbnail and fades the full image in over it, so there is something on screen the moment you open it.' },
        { t: 'Login-only content is no longer marked publicly cacheable', d: 'The admin preview declared its response private, but the streaming code further down overwrote that with public, cacheable for a day. With a shared cache or reverse proxy in front, that content could in principle be cached by someone else. Defaults are now written only when no value is set: private stays private, public links stay public.' },
      ]
    },
    {
      title: '22. What is new in v1.0.5',
      intro: 'The headline of v1.0.5 is that a file can still be tidied up after it is uploaded: images can be cropped, compressed or converted to WebP in place, videos can be transcoded or compressed, audio can be compressed — and the issued link never changes. Alongside that, several interaction gaps are closed (upload from inside the lightbox, mobile back returning to the parent folder, a refresh button on the detail panel, rotation in the crop dialog), the tag rule is now written as one readable sentence, and local file channels can be authorized to other accounts. No schema change; a straight overwrite upgrade is enough.',
      items: [
        { t: 'Edit in place from the detail panel: crop / compress / convert to WebP', d: 'When the primary copy lives on a local storage channel, three buttons appear after Move-to-remote in the detail panel. Which of them show is decided by a server-side probe rather than by guessing from the extension. Three hard rules: it only applies to the primary copy on a local storage channel (you cannot rewrite someone else\'s object storage); the disk path, file name and extension never change, which is the only thing that keeps issued links valid; only size, MD5, type, dimensions and the edited timestamp are updated, nothing else. Cropping reuses the same dialog as upload (rotation included) and posts the cropped image back; compression targets a percentage of the original size; WebP conversion offers lossy or lossless.' },
        { t: 'Video transcode / compression and audio compression', d: 'Video is probed first: anything already in a browser-friendly codec (H.264) is answered with needs no transcoding, so you are not left waiting minutes on a file that already plays. Only codecs like HEVC are actually converted. Both compression and transcoding respect the compress and transcode time limits, measured as actual execution time rather than an estimate. On timeout the job is abandoned and written to the system log, and the file is left byte-for-byte untouched — no more "it said it failed but the file is already damaged".' },
        { t: 'Compressing twice asks first', d: 'If the actual size differs from the original size, the file has been compressed before. The front end asks for confirmation before proceeding, then retries with an explicit confirm flag; the server validates it as well. Images that are already WebP no longer show the convert button, and the server rejects the request too.' },
        { t: 'Auto-tagging after upload moved to its own queue', d: 'Auto-tagging and the IP-location lookup used to share one serial queue. The lookup calls an external service, so a network hiccup blocked every tag job behind it — which is why tags sometimes appeared late. The two queues are now fully separate; a slow lookup no longer delays tagging, and upload speed is unaffected.' },
        { t: 'The tag rule is now one readable sentence', d: 'Instead of a string of symbols, you configure From [ ] as the start, cut at [ ], take at most [ ] characters. An enable checkbox sits in front and the whole block moved below Extract specified content in Settings → Others. Four rules are fixed and no longer configurable: whitespace always cuts; consecutive start markers mean the last one wins; a result longer than the limit is dropped entirely rather than truncated; and a tag that runs to the end of the file name has its extension stripped. Existing installs upgrade automatically only if all three values are still the old defaults.' },
        { t: 'Upload from inside the lightbox without closing it', d: 'On the local files page, an upload icon now sits left of the close button in the lightbox. Pick a channel, instance and folder and the upload runs in the background while the preview stays open. When it finishes, a result bar offers Done (stay in the lightbox) and View details (close the lightbox and open the file detail).' },
        { t: 'Mobile back returns to the parent folder', d: 'Previously, pressing back deep inside a folder on a phone exited the whole page. It now behaves like the file manager: back goes up one level, and only leaves the page at the top. Three kinds of false triggers are filtered out — an open overlay, the app dismissing its own history sentinel, and the lightbox dismissing its own — so internal bookkeeping no longer drags you up a folder.' },
        { t: 'Refresh in the detail title, real disk path in Source', d: 'A refresh button next to the title reloads the metadata without closing the dialog, and is disabled while spinning. Separately, when the primary copy is on a local storage channel, Source now shows the actual server-side path and stored file name instead of the issued link.' },
        { t: 'Rotation in the upload crop dialog', d: 'The crop dialog gains rotate-left, rotate-right, current angle and reset. Photos taken upright on a phone can be straightened directly. Rotation is always re-rendered from the original file and the angle is absolute rather than cumulative, so rotating four times returns you to an image byte-identical to the original — no generation loss.' },
        { t: 'Local file channels can be authorized, and the entry follows the authorization', d: 'The Authorize button is back next to More on the channel card, letting an administrator open one local direction to specific accounts (administrators need no authorization). A regular account does not see the local files entry in the page switcher at all until an authorized channel exists for it. In the upload dialog, Target channel lists only that account\'s usable main channels (backup channels excluded) and Owning instance lists only that account\'s own instances.' },
        { t: 'Backup channels can no longer be chosen as a move target', d: 'The candidate list for moving a file used to include backup channels. Selecting one promoted that copy to primary and permanently changed what backup channel means. The list now excludes them, and a second check at submit time catches the case where a channel role changed while the dialog was open.' },
        { t: 'Menu entries completed', d: 'On the upload home the more-menu gains My account after System management; in the file manager it gains My account and System management (admins only) after the language switcher. Both open in a new tab, on both desktop and mobile menus.' },
      ]
    },
    {
      title: '23. What is new in v1.0.6',
      intro: 'The main thread of v1.0.6 is a full rebuild of external WebDAV: it no longer borrows the image-bed upload pipeline and is now a real network drive — files are stored exactly as uploaded, with no renaming, compression or transcoding, no file type or size limits, and nothing appears in Image Files or History. Each regular account gains its own WebDAV management (create a channel, rename, change the note, regenerate the key, delete) plus a WebDAV entry inside Local Files that supports renaming and deleting. The rest are refinements: the tag rule is now a plain symbol string and actually works, converting to WebP renames the extension and keeps the data in sync while issued links drop the extension entirely, the Local Files batch bar and menus are tidier, and the old "browser comes back to a blank page" bug is fixed.',
      items: [
        { t: 'WebDAV rebuilt: username stays, only channel keys are accepted', d: 'The old version let an account password log in over WebDAV, which exposed the web login secret to a second protocol. The username is still the account name, but the password must be the access key of a channel created under WebDAV management (16 letters and digits, regenerable at any time with the old key dying immediately). Account passwords no longer work over WebDAV, and admin accounts are not allowed to use WebDAV at all.' },
        { t: 'WebDAV rebuilt: a real drive, no longer an image bed', d: 'PUT used to be handed to the image-bed upload pipeline, so a naming rule renamed the file and compression, transcoding or WebP conversion could kick in. Files now land byte-for-byte following the standard WebDAV protocol in the server webdav directory (/app/backend/webdav/{username}/{channel path}); file type and single-file size limits are gone. Because no file record is written, WebDAV files never show up in Image Files or History, and no page (including file details) offers crop, compress, transcode, convert to WebP or move-to-remote for them.' },
        { t: 'WebDAV rebuilt: several drives per account', d: 'An account can create several WebDAV channels (the limit is set by the administrator, 2 by default), each with its own name, storage path, access key and note. The name is editable but unique per account; the storage path supports multiple levels (such as /files/work), cannot be changed after saving, and its first-level folder must be unique per account — otherwise two drives would point at the same tree and files get deleted by accident. Clients mount /dav/ and the server resolves which channel a request belongs to from the key.' },
        { t: 'WebDAV rebuilt: one switch turns everything off', d: 'When the External WebDAV switch under System management → Security is off, every /dav request returns 403 and the WebDAV entry in Local Files disappears as well, because the requirement is that all WebDAV files become inaccessible, not just the protocol endpoint. That block of settings lives in the Others section while the old code read the Security section, so the switch never actually took effect; this release fixes it. The root path prefix and read-only mode fields are gone too: the mount point is always /dav/ and a drive is writable by nature.' },
        { t: 'The WebDAV entry in Local Files can rename and delete', d: 'An account with WebDAV enabled gets a WebDAV Files entry in Local Files that shows the real contents of its own webdav directory. Cards and rows have a More menu offering rename (same folder only; an existing name is refused) and delete (confirmed, permanent, folders go with their contents). The server allows writes on this virtual channel only — other local file channels point at the original directories on the user\'s machine and stay read-only — and it refuses to touch the channel root.' },
        { t: 'A Local default files entry in Local Files', d: 'Every account also gets a Local default files entry pointing at uploads/_user/{username}/999999, which is exactly where files land when uploaded through the built-in local storage channel. Those files used to be visible only in Image Files with no way to reach the directory on disk; now they can be browsed, previewed and batch-downloaded. The directory is created on demand, so a brand-new account sees an empty list rather than an error.' },
        { t: 'Tag extraction: plain symbols, and it actually works', d: 'The start and stop fields are now plain symbol strings (for example #@&) where each character is one marker and consecutive start markers mean the last one wins; leaving them empty falls back to the defaults (#@& as the start, common Chinese and English punctuation and brackets as the stop). The root cause of "looks right in settings but extracts nothing" is fixed too: the old version stored the defaults as a JSON array string while the parser split on commas, producing multi-character markers that could never match a single character. The front end now renders legacy JSON values as plain symbols, and the server migrates untouched legacy defaults once at startup while leaving any customised value alone.' },
        { t: 'WebP conversion renames the extension, links drop it entirely', d: 'Converting an image on a local storage channel to WebP now renames the file on disk, the channel storage key and the displayed original name to .webp, with the data updated to match. So that this cannot break links already handed out, issued links no longer carry an extension at all — the extension was only ever decoration, and the server looks a file up both with and without it.' },
        { t: 'Auto-authorize all users on a channel', d: 'Every channel\'s authorization dialog gains an Auto-authorize all users switch, off by default. When on, the channel is open to every account including accounts created later — authorized the moment they exist, with no manual ticking. The built-in local storage channel (code 999999) has this switch forced on and locked, otherwise a new account would have nowhere to store uploads. Its custom storage prefix and custom file naming fields are read-only as well and always use the defaults.' },
        { t: 'Inputs remember recently used paths', d: 'The upload folder field in Upload settings and the category field in Register file now remember recent values in the browser: focus the field and the last five entries are listed, pick one to fill it in. The data stays in that browser and is never uploaded.' },
        { t: 'No more blank page after the browser has been idle', d: 'Closing the browser or leaving it idle and then switching back to GoHub used to leave a blank page that needed a manual refresh. The revive logic treated "framework mounted but rendering an empty shell" as "already rendered" and therefore never rescued the page. It now checks whether anything was actually painted, adds two more triggers (page visible again, dynamic import failure) and shortens the first-paint guard from 12 seconds to 9.' },
        { t: 'Detail panel polish', d: 'The compress dialog defaults to 75%, gains a line showing the current actual file size, and the "already compressed" warning is two steps larger; pressing Start compression switches the button to Compressing and disables it, then to Done, and the dialog closes. The video transcode confirmation shows the current codec immediately. Source is now a dialog with a copy button. Move to remote is renamed, and the volume button moved after Download. On mobile the detail panel width goes from 95% to 96% of the backdrop layer for tighter side margins.' },
        { t: 'The Other menu on the home page and the Local Files batch bar', d: 'In link mode, External is folded into a new Other button — hover on desktop, tap on mobile — and a Download item sits above External to fetch the pasted link straight to disk (a Blob download when allowed, a new window when CORS blocks it). In Local Files the batch bar is shortened to count / Cancel / Upload and gains Download; on mobile it scrolls horizontally without wrapping, and the duplicate Upload button in the top bar is gone.' },
      ]
    },
    {
      title: '24. What is new in v1.0.7',
      intro: 'v1.0.7 ships no database changes. It is mainly about correcting UI paths that did not do what they promised: Download in link mode no longer jumps to the image, tag settings no longer vanish, issued links drop the extension completely, viewing details from the lightbox keeps the lightbox, snapshots can choose channel and folder, and the WebDAV module and folder entry are no longer hidden by silent conditions. Two real performance improvements ride along: file streaming now sends ETag and answers 304, and WebDAV directory listing moved from sequential stat calls to bounded concurrency plus a short cache. The crop dialog also starts at the full image so rotating and saving cannot trim pixels.',
      items: [
        { t: 'Link mode: Download no longer jumps away', d: 'Pasting an external image URL and clicking Other - Download used to just open the image in a new tab, because a site without CORS headers leaves the front end with no bytes to save. The server now fetches the file and returns it with an attachment header, so the same-origin request always triggers a real save and the page stays put. Only http/https is accepted, and links over 2 GB are refused with a hint to open the source directly.' },
        { t: 'Tag settings no longer disappear', d: 'Turning off Enable automatic tags used to hide the three rule groups entirely, which looked like the configuration had been wiped and left no way to edit it. The rules are now always visible and editable; when the switch is off a single hint line explains that the rules are saved but inactive, so you can prepare them first and enable the switch later.' },
        { t: 'Issued links carry no extension by default', d: 'Newly copied links look like https://your-domain/file/xxxx with no .jpg tail. The extension was only ever decoration there - the server resolves a file with or without it - and dropping it means converting to WebP or transcoding a video no longer breaks links that were already handed out. Old links with an extension keep working.' },
        { t: 'Faster previews: small image first, original second', d: 'The image preview in the file detail panel now paints a 640 px thumbnail first and swaps in the original once it arrives, so a slow external connection no longer shows a blank spinner. The lightbox already worked this way: the list thumbnail shows first and the full image covers it later.' },
        { t: 'Second visit to the same image costs almost nothing', d: 'File streaming now sends ETag and Last-Modified and honours conditional requests: the browser asks whether the file changed, and when it has not, the server sends nothing at all. In proxy mode the check is forwarded upstream, so a 304 from the source becomes a 304 to the browser.' },
        { t: 'Viewing details from the Local Files lightbox keeps the lightbox', d: 'After an upload started inside the lightbox, View details now stacks the detail panel above the lightbox. Closing the panel leaves you on the same image with the browsing position intact, instead of the lightbox being torn down first.' },
        { t: 'Video snapshots can pick channel, instance and folder', d: 'Snapshot uploads used to go to the default channel and default folder with no choice. Upload now opens the same target picker used by the Local Files page - target channel, owning instance, upload folder - and remembers the values for next time. Snapshots still carry the Video snapshot tag automatically.' },
        { t: 'WebDAV: the module and the folder entry are visible', d: 'The WebDAV card in user editing used to require three conditions at once and vanished silently if any was missing. It is now always shown for regular accounts, with a hint naming the missing piece (global switch off, or the account is not authorized) and a disabled create button. The WebDAV entry in Local Files now appears as soon as the account is authorized instead of requiring an existing channel first.' },
        { t: 'WebDAV: large folders open faster', d: 'Listing a folder used to stat every entry sequentially, which stalls Finder or Explorer on directories with thousands of files. Entries are now read with a bounded concurrency pool and cached for three seconds; any write (upload, delete, create, move, copy) invalidates the cache immediately, so a stale listing is never served. The listing also carries an ETag, so repeated requests can be answered with 304.' },
        { t: 'Crop dialog starts at the full image', d: 'The crop selection now covers the whole image when the dialog opens. Rotating and saving therefore never trims pixels by accident, and that no-crop case skips re-encoding entirely: JPEG keeps its quality and PNG does not grow. Drag the corners when you do want to crop.' },
        { t: 'Detail panel button names', d: 'Move to local is now Store to local, and Move to remote is now Send to remote, matching what the buttons actually do: the first pulls a file from a third-party channel back to local storage, the second pushes a local file out to a remote channel.' }
      ]
    },
    {
      title: '25. What is new in v1.0.8',
      intro: 'v1.0.8 ships no database changes. This release closes the loop on three issues that were reported fixed but were not: the empty tag settings block was a message-format clash with the @ and | characters, the snapshot dialog could not show its dropdowns because half of the layering was hardcoded, and the WebDAV master switch reported off simply because a regular account was denied the read and the failure was treated as false. It also tightens the mobile spacing to 2px, gives already-imported files a Details button in the Local Files lightbox, and adds video snapshots there.',
      items: [
        { t: 'Tag settings finally render', d: 'The previous two releases assumed the block was hidden by a condition. In fact the helper text in that block contained @ and | - the syntax markers for linked messages and plural branches - so parsing failed and the whole settings block stopped rendering, down to the enable switch. The strings are escaped now, so all three rule groups, the switch, the inputs and the placeholder chips render, and the #@& examples in the prose read normally.' },
        { t: 'Folder name validation hint', d: 'The hint that lists forbidden folder name characters contained the same pipe symbol and is fixed as well.' },
        { t: 'Snapshot upload: the channel and instance dropdowns are visible', d: 'In the upload dialog opened from a video snapshot, the dropdown could be clicked but its list stayed invisible: the list was rendered under the dialog, because the dialog used a hand-set fixed z-index while the list used the incrementing one from the component library. Both now come from the same manager, so whatever opens later is always on top.' },
        { t: 'WebDAV master switch: regular accounts read the real value', d: 'A regular user opening their own account page read the master switch through an admin-only endpoint. The request was denied, the front end turned that failure into "switch is off", and the page kept saying the master switch was not enabled while an administrator saw everything fine on the same page. A dedicated endpoint now returns only the caller own data, so the state is read correctly and the misleading hint is gone.' },
        { t: 'WebDAV: users manage their own channels', d: 'Once an administrator enables WebDAV for an account, the user can create channels, rename them, change notes, rotate the access key, and delete their own channels without an administrator doing it for them. The quota is still set by the administrator, and administrator accounts still cannot use WebDAV.' },
        { t: 'Layered hints are for administrators only', d: 'The two hint lines that name the missing layer reveal administrative configuration, so they now appear only when an administrator opens another account. A regular user viewing their own page just sees the channel list and the create button.' },
        { t: 'Mobile header sits closer to the top', d: 'The backend header on phones moves from 6px to 2px from the top edge.' },
        { t: 'Mobile second row: 2px both static and stuck', d: 'The select-all and view-toggle row on the file dashboard moves from 8px to 2px away from the header, and stays at 2px when it sticks below the header while scrolling, so there is no extra gap the moment it sticks.' },
        { t: 'Local Files lightbox: imported files show Details', d: 'When the file being previewed in Local Files already exists in the library, the lightbox shows Details instead of Upload. It opens the file detail panel in the library on top of the lightbox, and closing it leaves you on the same image. Files not yet in the library still show Upload.' },
        { t: 'A More dropdown in the lightbox', d: 'A More dropdown next to the button offers the same action - View details when the file is in the library, Upload to library otherwise - which is easier to reach on narrow screens.' },
        { t: 'Videos in Local Files can be snapshotted', d: 'Snapshot used to exist only on the file dashboard lightbox. Both places are the same now: open a video, hit the camera icon, and either upload the frame with the target channel, instance and folder picker added in v1.0.7, or download it directly.' }
      ]
    },
    {
      title: '26. What is new in v1.0.9',
      intro: 'v1.0.9 ships no database changes. The two themes are recoverable channel transfers and a handful of lightbox fixes. A transfer is now registered before any bytes move, so a failure halfway leaves a Retry transfer action in the detail panel instead of a few hundred megabytes stranded on the target channel; reading and writing both stream with retries and integrity checks. On the lightbox side the redundant three-dot menu is gone, and snapshot view, upload progress, pausing on upload and pull-down-to-details all behave as expected. Horizontal swipe no longer triggers browser back or the edge stretch animation anywhere, and a custom storage prefix can no longer start its first segment with an underscore.',
      items: [
        { t: 'Failed transfers can be retried', d: 'Moving a file between channels used to have a fragile middle: if anything failed (restart, database transaction timeout, dropped remote connection) you could end up with a large object sitting on the target channel while the database still pointed at the source, and someone had to clean it up by hand. A transfer now first writes its intent into the source copy metadata (target channel, direction, attempt count), records the staged object once it has been written to the target, and only then switches the data. Any failure keeps that record, so the detail panel button becomes Retry transfer and states where the last attempt stopped. When the object already sits on the target channel, retry only completes the data switch instead of transferring the bytes again.' },
        { t: 'Large transfers are steadier and lighter', d: 'Both directions stream now: local files are read straight from disk, remote files are streamed into a temporary file before being written to the target, so a few hundred megabytes no longer has to fit in memory. Downloads retry three times and verify the written length against Content-Length and the recorded MD5; uploads retry three times as well, and local targets get one more size check. A length mismatch aborts the switch instead of writing a record that only looks successful.' },
        { t: 'Occasional external link 404 / 502 fixed', d: 'The rule that decided whether a copy had any content only recognised the channel-scoped key and a full URL, and missed the stored addressing path. Some copies (registered files, some post-transfer copies) carry only that path, so they were treated as unusable, the link returned 404 and proxy mode surfaced a 502. Any of the three forms now counts, and the case is written to the system log so it can be diagnosed next time.' },
        { t: 'Renamed default item in Local Files', d: 'Default local files became Local user default files. The item has always pointed at the signed-in account own default upload directory (uploads/_user/<account>/999999); the old name read like a shared directory for everyone.' },
        { t: 'Lightbox buttons and feedback', d: '(1) The three-dot dropdown next to the close button is gone - it duplicated Upload / Details and made the top bar look like it had two upload buttons. (2) View in the video snapshot panel now opens the detail page of the frame just uploaded; it used to pass the file name as if it were the file ID. (3) A progress notice appears at the bottom of the page while an upload submitted from the lightbox or from a batch selection is running. (4) Pressing Upload in a lightbox pauses the playing video or audio first. (5) Swiping down on a file that is already in the library opens its library detail page.' },
        { t: 'Details no longer fails after an upload from the lightbox', d: 'After a successful upload the page marked the list item as imported. It used to store a boolean true, so the top bar switched to Details and then looked up metadata for the id true. It now stores the real file ID returned by the upload.' },
        { t: 'Custom storage prefix cannot start with an underscore', d: 'The first segment of the custom storage prefix (after stripping leading slashes) may not begin with an underscore: directories starting with _ are reserved by the system (_user, _avatars, _ipdata). Both the server and the form reject it, and the form reports it before submitting. The built-in channel (999999) keeps its read-only prefix as in v1.0.8, so the check applies to custom local channels.' },
        { t: 'No more swipe-back or edge stretch anywhere', d: 'A horizontal swipe on a phone used to be taken as back navigation and drew a stretch preview at the screen edge. The page now owns horizontal gestures: edge swipes and clearly horizontal mid-page swipes are consumed, while vertical scrolling, horizontally scrollable toolbars and thumbnail strips, and form controls (inputs, sliders, switches) are left alone. The upload area of the file mode on the home page additionally only accepts vertical gestures.' },
        { t: 'Public WebDAV: same-name upload overwrites', d: 'The /dav upload path was reviewed: bytes go to a temporary file in the same directory, are fsynced, and then atomically renamed onto the target name, so an existing file is replaced. A client that disconnects halfway only leaves a temporary file behind and the original is untouched.' }
      ]
    },
    {
      title: '27. What is new in v1.1.0',
      intro: 'v1.1.0 has no database changes (uploadSource is a string column, so new values need no migration). The theme is recording transfers properly: once a file has moved between a local and a remote channel, its Upload Method says whether it was stored in or stored out, and the filter dialog offers both values while the unused WebDAV entry is gone. This release also fixes the closing order of the detail page versus the lightbox, the character rules for {filename}, the data a deduplicated upload should take from the newest file, and the occasional blank page after a tab has been idle in the background.',
      items: [
        { t: 'Upload Method gains StoreIn and StoreOut', d: 'When Store in local moves a file from a remote channel to a local one, its Upload Method becomes StoreIn and the detail page shows Remote Store-in (StoreIn). When Store out to remote moves a file from a local channel to a remote one, it becomes StoreOut and shows Local Store-out (StoreOut). The value is written in the same database transaction that switches the channel copy, so there is no window where the copy has moved but the method still shows the original entry point. Moving the same file repeatedly keeps the last successful direction, and a failed transfer leaves the value untouched.' },
        { t: 'Filter dialog: two upload methods added, one removed', d: 'In the file manager filter dialog the Upload Method list is now Default, Upload, Fetch, StoreIn (remote store-in), StoreOut (local store-out), API-Web, API-S3, Record, so you can filter for files that arrived through a transfer and for which direction. The WebDAV entry is removed as requested; existing WebDAV records are unaffected and still show their value in the detail page and in the upload-method distribution of System Status.' },
        { t: 'Detail page over the lightbox: back and Esc close the detail first', d: 'Opening the file detail from the lightbox in Local Files used to close the lightbox first on a mobile edge swipe (leaving the detail page on screen) and behaved the same way with Esc on desktop. The detail page is now its own layer on top of the lightbox: one back gesture closes only the top layer, and a second one closes the lightbox; on desktop Esc closes the detail page first and only closes the lightbox when no detail page is open.' },
        { t: 'Character rules for the {filename} placeholder', d: 'When {filename} in a custom file naming template produces the stored file name, the original name is sanitized first: only letters, digits (including CJK characters), "-", "_" and "." survive, every other symbol is removed, leading and trailing spaces are trimmed, and inner spaces become "-". Stored names therefore stay safe for object storage, downloads and transcoding. The sanitizing applies to the stored name only — originalName in the database and everywhere in the UI still shows the untouched original file name.' },
        { t: 'Deduplicated uploads take the newest file data', d: 'With upload dedup on, uploading identical content again does not consume extra storage; a record is cloned for you instead. That clone now reflects the newest upload: originalName is the name you just uploaded (not the old record name), tags are the union of the old record tags and the tags produced by the file tag rules (deduplicated), the upload time is the current one, and the processing record gains a Duplicate clone group listing the source file name, its File_ID and the clone time. Everything else (channel copies, size, MD5, folder) is copied from the existing record; link password, views, rating and note remain personal to the new record.' },
        { t: 'No more blank page after a long idle tab', d: 'Returning to a tab that had been in the background for a long time (or after the phone screen was off) occasionally showed a completely blank page that needed a manual refresh. Coming back now runs three checks (1.2s, 3s and 6s) and reloads if the page is still blank at any of them, plus a 9s watchdog for the case where the page stays stuck in a loading state. The old "at most 3 revives per session" rule became "at most 3 within 10 minutes, reset after 2 minutes of healthy running", so normal pages are never disturbed while long sessions keep the ability to recover.' }
      ]
    },
    {
      id: 'notes-moment',
      title: '28. What is new in v1.1.1',
      intro: 'v1.1.1 starts the notes area with the one type that needs no editor: Moments - a bit of text plus a few photos, kept the way a social feed keeps a day. It is the foundation for articles and the editor that come next. Four new tables (notes / note_moments / note_assets / note_tags) are added; nothing existing is altered, and upload, file management, tags and sharing are untouched. On the public side there is exactly one new entry point, Moments; the note lobby and public reading pages come later.',
      items: [
        { t: 'A new Notes page, plus a Moments entry on the home page', d: 'In the page switcher at the top left of the admin, Notes now sits right below File Management. The page has two rows: the first holds the page switcher, the instance picker and New Moment; the second holds the type tabs (All / Moment / To-do / Nav / Article / Collection), search, media type, sort, trash and refresh. Sorting exists in exactly one place, on the second row - two competing sort controls are a classic source of confusion, so there is only ever one here. To-do, Nav, Article and Collection are placeholders for now and say so when opened. On the upload page a Moments tab sits next to the upload-method tabs; it is the only public-facing addition in this release.' },
        { t: 'Writing a moment', d: 'The title is prefilled with a date and time such as 2026-11-10 Tue 00:27 and can be replaced with anything (moments keep the title inside metas rather than taking a column of their own). Seven mood emoji and seven weather icons toggle on click. The body is capped at 500 characters (configurable between 50 and 20000 in settings) with a live counter. Up to 50 attachments can be dragged into order, nudged with the arrow buttons, with the first one used as the cover. Tags can be picked from existing ones or typed to create new ones; note tags are typed as note, so they never mix with file tags. Public visibility shows a badge on the card, but this version is still self-publish and self-view only - the public list is not wired up yet.' },
        { t: 'How characters are counted', d: 'Only letters (including Chinese), digits and kana count. Punctuation, spaces, line breaks and emoji do not - writing 500 characters and then a wall of punctuation will not trip the limit. Counting walks code points, so an emoji or a rare character is never counted as two. The frontend uses its copy for the live counter and the over-limit hint, the backend does the authoritative check, and the two implementations are line-for-line equivalent: any drift shows up as the frontend saying fine while the backend rejects it. Verified: 501 characters rejected, 500 characters plus 360 punctuation marks accepted.' },
        { t: 'The nine-cell grid and the lightbox', d: 'One attachment is a single large image (4:3, about 62% of the card width, centred); two sit side by side; three fill a row; four to nine wrap automatically in three columns (4 = 3+1, 5 = 3+2, 7 = 3+3+1). Past nine, only the first nine are shown and the ninth carries a +N badge - the lightbox still shows everything. Videos are not preloaded; they render as a cover card with a play badge and the file name and only play inside the lightbox. Audio renders as a music icon, the file name and the duration, where the duration is read from the file metadata by the browser (three at a time, eight-second fallback, cached per URL) so the backend needs no extra column.' },
        { t: 'Long text collapses: ten lines without attachments, five with', d: 'A Read more link appears only when the text actually overflows, expanding to the full text and collapsing again on demand. The decision is made by briefly removing the CSS clamp after mount, measuring the real height and comparing it with line-height times the allowed line count - -webkit-line-clamp truncates but never reports whether it truncated, so CSS alone would either put Read more on every card or hide it on the one card that needs it. Measurements are re-run on window resize with a debounce. Because the body is capped at 500 characters and a wide desktop line holds around eighty, the rule in practice only fires on phones.' },
        { t: 'Trash: permanent delete removes the note, never the file', d: 'The delete action on a card moves the moment to trash, where it can be restored at any time; Delete permanently inside the trash is what actually drops the record. It never touches the image in the file library - the file stays listed and its link keeps working. This is also why note_assets deliberately has no foreign key to files: deleting an image should not be blocked by a note that references it, and should not cascade a note out of existence either. Rendering resolves the still-active files in one batch and silently skips tiles whose file is gone, so one missing image never takes a whole card down.' },
        { t: 'Attachments store a file ID, so renames follow through', d: 'An attachment stores files.id - not objectPath, not remoteKey, and certainly not a full URL. files.id never changes, while objectPath and remoteKey change whenever a file is transferred between channels, and a full URL pins the domain into history. Rendering builds /file/&lt;name&gt; from the current FileRecord.name, so renaming nana.png in the admin immediately points the moment at the new name: the new address returns 200, the old one 404. This was verified end to end.' },
        { t: 'Instance isolation and permissions', d: 'Like files, moments belong to an instance: instanceId is the first condition of every query, and an empty string means the default instance rather than no filter - otherwise the default instance would quietly become every instance. Moments from another instance are invisible, switching instances switches the list, and opening another instance by URL returns 404. Sign-in is required; regular users see and edit only their own; administrators see everything inside the current instance. Hiding a control is only courtesy - the backend is the actual boundary.' },
        { t: 'What this release does not do', d: 'Article, Collection, To-do and Nav are placeholder tabs. The note lobby and public reading pages are not built - the Moments entry leads to the same admin page. There is no rich-text editor yet: a moment is plain text that preserves line breaks and repeated spaces, escaped by Vue interpolation, so no XSS surface. The visibility field and its UI exist, but nothing is published publicly yet.' }
      ]
    },
    {
      id: 'notes-moment-112',
      title: '29. What is new in v1.1.2',
      intro: 'v1.1.2 turns Moments from working into comfortable. The round trip between the editor and the image host is now smooth (what you upload while writing becomes an attachment, a pasted link can be transferred in, closing the editor keeps the draft), the actions on a card fold into a single More menu with comments added, and file references are finally visible - a file that a note points at can no longer be deleted out from under it. The database only grows: one new table (note_comments) and two new columns on note_moments (moodName / weatherName). Upload, file management, tags and sharing are untouched.',
      items: [
        { t: 'Notes page: the top bar buttons were reordered', d: 'Right to left the top bar now reads: More menu, publish, trash, refresh, tag management, search. Trash moved in front of publish and refresh in front of trash, so the destructive control is always one more step to the right. Search is a real input on desktop and collapses to a magnifier on phones: tapping expands a search row underneath, tapping again clears the keyword and folds it away. On a phone the bar is a single line, and a permanently visible input squeezes the type tabs into two rows.' },
        { t: 'The publish button label follows the current type', d: 'All and Moment read New Moment; To-do reads Add to-do; Nav reads Add nav; Article reads Publish article; Collection reads Add collection. The button always sits left of the type dropdown, so the eye does not travel while choosing a type and then publishing. Types that are not implemented are disabled with a notice instead of silently doing nothing.' },
        { t: 'Phones: swipe sideways to cycle through the types', d: 'A horizontal swipe over the content area walks All, Moment, To-do, Nav, Article, Collection and wraps around at either end, so the tabs never have to be tapped. A swipe only counts when it moves more than 60px, when the horizontal component is at least 1.5 times the vertical one, and when it does not start inside an input, a select, the type tab strip or anything marked no-hswipe-guard - otherwise selecting text or scrolling the tab strip would page through types. Swipes starting within 30px of an edge are left to the system back gesture.' },
        { t: 'Phones: both bars hide on a short scroll, with the same easing', d: 'The second row used to hide and return with a default transition while the header used a slightly springy curve, so one bar lagged the other. Both now share a single transition. The threshold also got a separate set of mobile numbers (12px, decided by a 1px delta) because a phone screen is short: waiting for 60px makes the bar feel broken.' },
        { t: 'Instance switching moved into the page dropdown', d: 'It used to be a standalone button on the notes page, which looked different from the admin home page. It is now an item inside the page dropdown, below the page list and separated by a rule; each entry carries its instance number (the default instance has none) and the current one is ticked. The choice is written to localStorage under gohub_instance_id, and both the list and anything published afterwards follow it.' },
        { t: 'A More menu at the end of the top bar', d: 'A three-dot button now sits right of publish: my account, system management, a divider, sign out, and finally the colour-mode switch. Desktop and phones share the same menu; on a phone these items no longer live inside a drawer, where finding Sign out meant opening the drawer and scrolling.' },
        { t: 'Tag management: switch by category, merge, split and edit properties', d: 'A tag icon in the top bar opens the tag manager: a list with checkboxes on the left, properties for the selected tag on the right - rename, note, save. Selecting two or more allows Merge, which moves every note under the merged tags onto the target, adds the counts up and drops the old tags. A single tag can be Split into several new names, with the existing notes linked to the new tags as well. Delete only removes the links; the notes themselves are untouched. A File tags / Note tags switch keeps the two kinds fully separate: file tags never appear on a note and merging across the two is refused.' },
        { t: 'The refresh button used to look broken', d: 'The cause was that refresh called a full page reload, which also dropped the current tag filter and search keyword. Sitting on page two of one tag and pressing refresh took you back to page one of all types, which reads as nothing happened while the content changed completely. Refresh now clears the list, resets to page one and re-fetches using the current filters, leaving the filter bar and search box as they were; inside the tag manager it reloads the tag list instead.' },
        { t: 'The moment editor is 96% of the window, and titles drop the time', d: 'The dialog is a flexible 96vh layout where the body stretches and the attachment area scrolls on its own, so a taller screen gets more room to write. The prefilled title lost the clock: 2026-11-10 Tue instead of 2026-11-10 Tue 00:27. Moments are several entries across one day, and a timestamp makes two entries from the same day look like different days. A title that was already edited by hand is never overwritten.' },
        { t: 'Mood and weather: a name pops up on tap and is stored on publish', d: 'Seven mood emoji and seven weather icons are hard to tell apart by sight - is that cloud overcast or merely cloudy? Tapping now shows the name in a bubble above the icon for two seconds, which does not interrupt picking several in a row. On publish the Chinese name is written into moodName / weatherName on note_moments alongside the code. That column exists so that filtering by rainy day or bad mood still works later, which it would not if only the code was stored and the icon set changed.' },
        { t: 'The body limit went from 500 to 1000 characters', d: 'The counting rule is unchanged: only letters (including Chinese) and digits count, while punctuation, spaces, line breaks and emoji do not. The limit lives in one constant on each side; verified that 1001 characters is rejected with a message naming both numbers, and 1000 characters plus 500 punctuation marks passes. Comments have their own limit of 500 characters and do not affect the body.' },
        { t: 'The location field stays, and the browser remembers it', d: 'Location is a free-text field with autocomplete: opening it lists the last twenty locations, most recent first and de-duplicated, and typing filters them. The memory is per instance and lives in localStorage; a successful publish moves that location to the top. Keeping the field rather than replacing it with a fixed list is deliberate - a location is free text, and a fixed list would force the user into configuration to record a new place.' },
        { t: 'Image host picker and link import inside the editor', d: 'Choose from image host was renamed Image host picker, and Link import sits next to it: paste an http(s) link, the server fetches it, pushes it through the same upload path and inserts it as an attachment on the moment being written. Both paths first open the target channel / instance / folder picker and only start once that is confirmed, and both record the upload source as Attachment, so the file detail page later shows at a glance that the image arrived with a note.' },
        { t: 'Closing the editor, Esc included, no longer loses the draft', d: 'While writing, the current state (title, mood, weather, location, body, attachments, tags, visibility) is written to browser storage every 400ms. Reopening the same moment offers to restore the unpublished draft, with a one-click discard. It is cleared on a successful publish or when the draft is explicitly discarded. This matters most on phones: a phone call or an app switch can get the page reclaimed, and half a moment disappears with it.' },
        { t: 'Image host picker: 96% tall, infinite scroll, video thumbnails', d: 'The panel matches the editor at 96vh, and the Load more button is gone in favour of loading when the scroll nears the bottom (160px). A short first page triggers another fetch so the panel never opens empty. The type tabs are now exactly Image, Video, Audio and Other, defaulting to Image; All was removed because it mixed video and audio into image picking. Other means anything that is none of the three - documents, archives. Video tiles now show a real thumbnail: the frontend seeks a video element to 0.1s and draws the frame to a canvas (two at a time, nine-second timeout, 480px on the long edge, cached per URL), falling back to the old cover card when that fails.' },
        { t: 'The little eye on each thumbnail: hold to preview, release to close', d: 'An eye icon sits at the bottom-left of every thumbnail. Holding it (or pressing the mouse) opens a 300px preview over the grid, and releasing closes it. The preview picks a side by the button position on screen - open to the left when the button is near the right edge, to the right when near the left, centred otherwise - so it never spills off screen. Touch ignores the first 300ms and tolerates 10px of drift, because a finger press always moves slightly and a tighter threshold would cancel the hold.' },
        { t: 'The upload folder defaults to /瞬间/year/month', d: 'Uploads started from the moment editor prefill the current year and month (for example /瞬间/2026/11) in the target picker, so the path does not have to be typed every time. The folder travels with the upload and the file tree files it under 瞬间, then 2026, then 11. One false alarm worth recording: a Chinese folder name is perfectly usable - the 400 seen during command-line testing came from sending raw, unencoded Chinese in the query string (browsers always encode via URLSearchParams), while the properly encoded request returns 201 and stores the folder correctly.' },
        { t: 'The target picker became a shared helper for every upload path', d: 'The channel, instance, folder and confirm flow was lifted out of the moment editor into a reusable helper that accepts a default folder, and every upload path uses it: local file upload, lightbox upload, moment attachments, and later uploads inside articles. Uploading itself is also unified into three entry points - single file, staged or chunked, and link transfer - each responsible only for getting the bytes, while folder, instance and source label come from the caller. This is how a missing instance on one entry point stops happening twice.' },
        { t: 'Moment cards: four attachments now sit two by two', d: 'Four used to flow through three columns as 3+1, leaving a hole in the bottom right that looked like a missing image. Four now always form a two-by-two square; one, two, three and five through nine keep their previous layout.' },
        { t: 'Video tiles: a thumbnail with a modest play badge', d: 'A video on a card is no longer a black block with a filename: it shows the first frame with a 30px translucent play badge in the middle. The badge is deliberately small, since its only job is to say this is a video and a large one would cover the frame.' },
        { t: 'Card actions: a More menu after delete, holding edit and delete', d: 'The bottom-right is now a three-dot menu: edit, comment, delete, with delete last and separated. Edit and delete used to be two flat icon buttons, and mis-tapping delete was a real risk - it only went to trash, but the mis-tap itself should not happen. Cards in the trash keep restore and delete permanently as flat buttons because those two are frequent and need to be explicit; their More menu only holds comment.' },
        { t: 'Comments: up to 500 characters each', d: 'More then Comment opens the comment panel: post, delete your own, and pages that load in chronological order. Counting matches the body - letters and digits only, capped at 500 with a live warning that disables posting. Comments live in the new note_comments table (noteId, content, charCount, author, instanceId, createdAt, indexed on noteId and createdAt) and follow the note into the trash and out of existence; they are never exposed on their own.' },
        { t: 'Lightbox: the detail button sits left of the divider, before close', d: 'The top-right of the lightbox was already a group of icons, a divider and close. Detail now sits left of the divider and right next to close, for every media type. It does not close the lightbox - the detail dialog stacks above it thanks to the Element Plus layer order, and closing the dialog leaves the lightbox on the same item, so nothing has to be found again. Opening the detail pauses any playing video or audio.' },
        { t: 'Lightbox: pull down for detail on phones, and a layered back', d: 'Pulling down inside the lightbox (over 60px, vertically dominant) acts as the detail button and opens the file detail for that image; pulling up jumps to a random item of the same kind. Back and edge swipes are handled by the shared layer stack: one back closes only the top layer - detail first if it is open, then the lightbox, and only then the page. This was missing on the notes page, where the detail dialog was never registered so one back closed the lightbox and left the dialog on screen; this release fixes it.' },
        { t: 'File detail: a new Attachment upload source', d: 'Files that arrive through content publishing - the moment picker, link import, local upload - now record their upload source as Attachment, shown as Attachment in the detail page. Both paths previously carried a stagingId and were therefore always recorded as Fetch, which made it impossible to tell afterwards that an image came in with a note. An explicitly declared source inside the allowlist now wins over the old staging-means-Fetch rule, with no effect on existing callers: the upload page declares nothing and stays Default, and callers that declare Fetch get Fetch.' },
        { t: 'File detail: file real name and file references', d: 'Two more rows follow the original file name. File real name shows the remoteKey as actually written to the channel, without the path - once storage naming rules change, this is the only line that says what the file on the server is called. File references shows how many notes point at the file, with a View button that opens the reference list in a new tab: every referencing note with its title, type, status, author and time, and clicking a title jumps to that note. It is a page rather than a dialog because the list can run long and scrolling inside a dialog is unpleasant.' },
        { t: 'Deleting a referenced file is now blocked', d: 'Deleting a single file, or a folder containing a referenced file, is refused with a message that names the notes: this file is referenced by notes and cannot be deleted, listing the titles and asking you to delete those notes first. The old behaviour deleted the image and left a broken tile in the note, which the user only discovered later. Batch deletes list every blocked file at once instead of deleting half and then failing. To remove the file, delete the note or drop the attachment from it first.' },
        { t: 'Home page: Moments became five actionable tiles', d: 'Moments used to be a link into the notes page, which was a detour. It is now a dashed action area holding five square tiles side by side: Moment, To-do, Nav, Article, Collection. Tapping Moment opens the moment editor right there, and a successful publish puts the new entry in the list below immediately, clearing only on a page refresh - so the result can be checked on the spot without switching to the admin. The other four editors do not exist yet, so those tiles are shown desaturated with a notice instead of opening an empty page.' },
        { t: 'Smaller padding on the three home tabs, and one divider removed', d: 'The File, Link and Moments tabs got a step less padding on phones so all three fit on one row without crowding. The vertical rule between Link and Moments is gone, because Moments is no longer a page jump but a mode switch inside the same page, and the rule made them look like different kinds of thing.' },
        { t: 'Database changes: additive only', d: 'One new table, note_comments, for comments, plus moodName and weatherName on note_moments (defaulting to empty, so existing rows are unaffected). No column was modified or dropped and none of the upload, file management, tag or sharing tables were touched. The entrypoint table list already includes note_comments, so containers created from this image fill it in on start.' }
      ]
    },
    {
      id: 'notes-settings-1121',
      title: '30. What is new in v1.1.2.1',
      intro: 'v1.1.2.1 does two things. It adds Note settings, so the size and alignment of the attachment area can be tuned per instance, and it widens file reference counting from notes only to every reference type (notes and share links). No new tables: settings live in the existing settings table, and upload, file management, tags and sharing are untouched. This release ships source only, with no image build.',
      items: [
        { t: 'Settings entry: the More menu, right above Sign out', d: 'The More menu now reads My account, System management, Note settings, a divider, Sign out, theme switch. Note settings sits directly above Sign out because both are things you reach for on your way out of a page, and keeping them together beats scattering them to two ends of a menu.' },
        { t: 'Settings are per instance, and instances do not affect each other', d: 'A set of settings belongs to one instance. Set the attachment area to left aligned at 40% in the default instance and another instance still shows that instance own layout; switch back and the tuned one is there again. This matches the isolation used for files, tags and notes. The value is stored in the settings table under note-settings:<instance id> (~default for the default instance) as JSON, so adding to-do, nav, article and collection settings later only means adding keys to the same JSON - no schema change.' },
        { t: 'Attachment area size: default or a custom ratio', d: 'Default keeps the current grid exactly as it is, down to the pixel. Custom ratio reveals a max-share-of-page-height field (5% to 80%, default 30%). That ratio is the total height when three rows are shown; two rows use 80% of it and one row uses 60%. Row count follows the attachment count: three rows for seven or more, two rows for four to six, one row for one to three. Four attachments are always two by two; everything else uses up to three per row.' },
        { t: 'Cells stay square, width follows height', d: 'Every attachment stays 1:1. The total height comes from page height times ratio times the row factor; subtract the gaps, divide by the number of rows to get the row height, which is also the cell width, and derive the block width from the column count. So at 30% the attachment area really occupies 30% of the page height on three rows, regardless of each image own aspect ratio. On narrow screens the computed width can exceed the card, in which case it fills 100% and the cells shrink proportionally - the requirement is a maximum ratio, and smaller is allowed.' },
        { t: 'Page height means the viewport, and the settings page shows the maths live', d: 'Page height is the browser viewport height (window.innerHeight) rather than any container height, so the notes page and future public pages measure the same way and switching devices does not produce two different answers. Under the input the settings page shows the resulting sizes for the current window (three rows, two rows, one row in pixels), updating as the ratio changes so there is no need to save and go look at the list.' },
        { t: 'Those numbers are cached in a cookie, so they are not recomputed every load', d: 'The sample sizes (ratio plus viewport height to three heights) are written to a browser cookie: when neither the ratio nor the window height changed, reopening the settings page shows the previous result without recomputing. Clearing cookies or resizing the window recomputes and rewrites it. The settings themselves are cached in a cookie too, so the page can lay the attachment area out at the right size on first paint and then fetch the authoritative value from the server - no flash of the default layout before it snaps to yours. The server remains the only source of truth; the cookie only covers that first frame.' },
        { t: 'Attachment alignment: centered by default, or left aligned', d: 'Default keeps the current centred layout; left aligned puts the attachment area flush with the text. A single image (62% wide and centred in the default layout) follows it too, and in custom ratio mode the block is narrower to begin with, so the difference is most visible there.' },
        { t: 'To-do, nav, article and collection settings are not open yet', d: 'The settings page lists five categories but only Moment settings is clickable. The other four are dimmed and marked coming soon; they do nothing when clicked, and no empty panel is faked to fill the space. Those categories only make sense once the corresponding editors exist.' },
        { t: 'File references now count every reference type', d: 'The reference count in file details used to mean how many notes use the file as an attachment. Share links now count too: a file inside a shared folder, or carrying a shared tag, is one reference. Each row in the reference list is labelled with its source (note or share), the totals break down as notes and shares, and the detail page shows that breakdown when both kinds are present.' },
        { t: 'Only note references block deletion', d: 'A share reference is a filter: if a file is covered by a folder share, deleting it merely removes one file from that share and breaks nothing. A note attachment is a hard reference - delete it and the note loses an image. So the delete check only honours notes. Otherwise sharing the root folder once would mark every file in the library as referenced and you could not even replace an image. This is a deliberate trade-off: block what breaks, not what only removes an entry point.' }
      ]
    },
    {
      title: '31. What is new in v1.1.2.2',
      intro: 'v1.1.2.2 only changes how a moment looks: a single attachment now follows its original aspect ratio, Note settings gains a layout style and an attachments-per-rows option, and body text is truncated by height instead of by line count. No database changes, no new tables, and the rest of the image host is untouched. This release ships source only, with no image build.',
      items: [
        { t: 'A single attachment follows its own aspect ratio instead of being cropped square', d: 'A lone image used to be forced into a 1:1 cell, so portraits and panoramas lost both ends. It now keeps its own aspect ratio: total height is page height times the configured ratio times 70% (three rows use 100%, two rows 80%, one row 60%, and a single attachment 70% - all derived from the same ratio), and width is height times the aspect ratio. Until the image loads, a 4:3 box holds the place and is corrected the moment the real size arrives, so it settles once. The default layout has no configured ratio to follow, so it keeps the previous "about 62% of the card" width, derives height from the aspect ratio, and caps it at 45% of the viewport - otherwise a portrait would be 800px tall and fill the screen.' },
        { t: 'Two or more stay square, but shrink to the available width when needed', d: 'Cell size still comes from total height divided by the number of rows, keeping 1:1. The difference is a width check: if the computed row width exceeds the width available in the card, the cell is derived from the available width instead and stays square, so nothing overflows the card and nothing is stretched into a rectangle. That available width is measured from the card itself and recomputed when the window resizes; it is not a hard-coded number.' },
        { t: 'New Content layout: default or divider', d: 'Default keeps the current bordered card around each note. Divider removes the border entirely and draws a single line underneath each note, in the same colour as the border used to be; the card background and shadow go with it, otherwise two blocks of colour would show between neighbours and it would not read as a separator. The last item in the list gets no line, so the list does not end on a dangling divider.' },
        { t: 'New Attachments loaded: three rows, two rows or one row', d: 'This only decides how many are shown, not how big they are: three rows shows up to 9 (the previous behaviour), two rows up to 6, one row up to 3. Anything beyond that still collapses into a +N badge on the last cell, and the lightbox still shows everything. Sizes always follow the attachment area size above it.' },
        { t: 'Tighter gaps, and 5px corners for both attachments and cards', d: 'The grid gap goes from 4px to 3px so attachments sit closer together. Attachment corners go from 8px to 5px, and the note card border radius from 12px (10px on mobile) to a unified 5px - consistent at both ends, and no more mismatch between a very round card and a very square image inside it.' },
        { t: 'The moment title now uses the same colour as the time', d: 'The title used body-level dark text while the time was muted grey, so the two sitting side by side fought for attention. They now share a colour and rely on size and weight to establish hierarchy, which reads more quietly.' },
        { t: 'Plain-text bodies are truncated by height (30% of the page) instead of by line count', d: 'Truncation used to be by line count (10 lines without attachments, 5 with), but the same number of lines occupies very different heights across screen widths - on a narrow screen one long post could eat most of the view. It is now a fixed rule: the body area may not exceed 30% of the page height, and only beyond that does a Show full text button appear. The ratio is fixed and is not exposed in Note settings; it counts only the body itself, not the title, mood, weather, attachments or buttons.' },
        { t: 'Saving settings now merges within each category', d: 'Previously, if the submitted object omitted a field, that field was treated as unset and reset to its default. Each category is now merged on the server as well: submit only the field you changed and the rest stay as they are. That keeps new settings - or a page that only flips one switch - from wiping the other options in the same category.' },
        { t: 'Database and everything else', d: 'No new tables and no new columns: layout style and row count are new keys inside the JSON already stored in the settings table. Rows written before this release have neither key and fall back to default layout plus three rows, exactly as before, so no migration is needed. Upload, file management, tags and sharing are untouched.' }
      ]
    },
    {
      title: '32. What is new in v1.1.2.3',
      intro: 'v1.1.2.3 settles the default look of a moment: the factory defaults become custom ratio 35% / left aligned / divider style / two rows, attachment heights are re-derived from the number of items, and comments move out of a dialog into the bottom of the card - where clicking any comment replies to it, the way Moments works. No database changes, no new tables, and the rest of the image host is untouched. This release ships source only, with no image build.',
      items: [
        { t: 'Every factory default changed', d: 'Attachment area size now defaults to Custom ratio (the other option, previously Default (keep current layout), is now Auto ratio); the max share of page height goes from 30% to 35%; alignment defaults to Left; content layout defaults to Divider; attachments loaded defaults to Two rows (up to 6). Reset to default restores exactly this set: custom ratio / 35% / left / divider / two rows. Radio options are now ordered with the current default first, so the active choice is the first thing you see.' },
        { t: 'Saved settings survive the upgrade', d: 'A default only applies when the key is missing or invalid. Any value that was explicitly saved is kept as-is: someone who picked Bordered plus three rows on v1.1.2.2 still has bordered plus three rows after upgrading. To move to the new defaults, press Reset to default in the settings dialog.' },
        { t: 'Attachment heights now depend on how many are shown', d: 'In Custom ratio mode the factors are: one in a row 80%, two in a row 70%, three in a row 60%, two rows (4-6) 80%, three rows (7+) 100%. The rule uses the number actually shown, not the number attached: with Two rows, nine attachments show six and use the two-row 80%, because the collapsed ones take no height. At the default 35% on a 900px viewport: three rows 315px, two rows 252px, one row 189px.' },
        { t: 'A single attachment: 70% to 80%', d: 'A lone attachment still keeps its original aspect ratio instead of being cropped square, but its total height goes from viewport height times ratio times 70% to 80% - about 14% taller at the same 35% ratio. Auto ratio mode is untouched and still uses about 62% of the card width capped at 45% of the viewport.' },
        { t: 'Attachment corners unified at 3px', d: 'Each cell in the grid goes from 5px to 3px, while the card border keeps its 5px radius, so the boundary between card and attachment is clearer.' },
        { t: 'The text block is capped from the card edge down to the Show full text row', d: 'The old rule capped the body itself at 30% of the page height. It now covers the whole text block: measured from the top border or divider of the card down to the Show full text / Collapse row, including the title row, mood and weather, the body and that button. Attachments, the action row and comments are excluded. Attached and plain-text moments share the same rule, so a long photo post can no longer push its attachments off screen.' },
        { t: 'Comments live in the card instead of a dialog', d: 'More then Comment used to open a separate dialog. Comments now render inside the card, right below the row holding the more (three dots) button, one line each in the style of Moments: the commenter name comes first in its own colour, followed by a colon and the content. A moment with no comments renders nothing - a permanent no comments yet line under every card would be noise.' },
        { t: 'The comment area takes at most 20% of the page height', d: 'When comments run long, the area is capped at 20% of the viewport and a More comments (N) button appears; expanding it reveals everything, and Collapse tucks it back. For a single moment with more than 100 comments, pressing the button first fetches the rest from the server and then expands, so you never see 100 of 200.' },
        { t: 'Click any comment to reply to that person', d: 'Clicking a comment opens the composer with a Reply to @name placeholder, and the posted content starts with Reply to @name. On display that prefix is parsed out and the name is highlighted in the same colour as commenter names instead of blending into the text. No parentId column was added to the comments table: Moments itself stores the reply-to inside the comment text, and adding a column would mean a migration every deployment has to run for a purely cosmetic gain.' },
        { t: 'The comment input is no longer squeezed on mobile', d: 'The input is a fixed width: 100% with box-sizing: border-box, following the card content width; on phones the font is 14px and padding is tightened, so long comments wrap normally instead of leaving a big empty gap to the right of a half-width box. Enter inserts a newline, Ctrl or Cmd plus Enter sends.' },
        { t: 'Comments arrive with the list, not one request per card', d: 'The list endpoint now returns each moment comments (ascending, up to 100 per moment) plus the total. One query fetches the whole page and groups by note, so a page of 20 costs two extra queries instead of 20 requests - which is what made the list feel sticky when scrolling. Posting and deleting update the card in place without a full reload; a list refresh always takes the server as the source of truth.' },
        { t: 'Database and everything else', d: 'No new tables, no new columns, no migration: comments still live in the note_comments table added in v1.1.2, and the reply relation is carried in the comment text. Upload, file management, tags and sharing are untouched; only the existing note_comments table is read.' }
      ]
    },
    {
      title: '33. What is new in v1.1.3',
      intro: 'v1.1.3 does three things at once: it renames the Local files family to Mounted files / Mount Management, rebuilds the file picker into a two-source panel (library files and mounted files) with the full filter set and search scopes, and adds a switch password you can put on an instance. The home page Record mode joins the swipe cycle, and several notes-page rough edges are aligned with the library page. On the data side there is exactly one change: a moment title moved out of the extension field into its own column.',
      items: [
        { t: 'Renaming: Local files becomes Mounted files / Mount Management', d: 'The Local files channel is now Mounted files, and the built-in channel starts as Mounted files - default. The Local Files page title and the page switcher label become Mount Management, and the switcher Library files becomes Library Management. Only human-facing strings changed: the channel type value, API paths and database columns are untouched, so old configurations and old links keep working. On existing deployments the built-in channel is renamed automatically if it still carries one of the historical default names; a name you changed yourself is never overwritten.' },
        { t: 'Notes page: toolbar and search', d: 'The toolbar order is now Publish, search, tag management / refresh / trash, more menu, all buttons share one height, and the theme switch moved above My account. The desktop search box copies the library page: the scope select sits inside the input, clear and search icons on the right, and the box widens a little on focus. Search accepts #tag and -#tag for exclusion; parsing happens on the server so the web UI, the API and any future client share one meaning. New scopes: All / Title / Content / Tag / Other; omitting the scope behaves like All, so old requests are unaffected.' },
        { t: 'Notes page: the search row on phones', d: 'Tapping the search icon on a phone now opens the box as its own row under the toolbar, with the same scope select as desktop (All / Title / Content / Tag / Other) plus clear and search buttons. The header is now laid out vertically: the first row (page switcher plus button group) is its own container and the search row is a sibling, so opening it never re-flows the first row - previously both lived in one wrapping flex container and the search row pushed the buttons around. The same fix also repairs a height sync that had never worked: the template starts with a comment, so Vue treats the component as a fragment and returns a comment node as its root, which has no style - the height variables were never written and the second toolbar row always used the 60px default. With the search row open the header grows to 95px, so the type tabs sat underneath it. Reading the page element directly makes the two rows line up again.', },
        { t: 'Notes page: publishing and type', d: 'While the type tab sits on All, the button reads Publish note and opens a type chooser (Moment / To-do / Nav / Article / Collection); the last four are listed but greyed out with a note because they are not implemented yet. The type dropdown placeholder Please select became All types - the root cause was the select treating an empty string as nothing selected. Plain text was renamed Text.' },
        { t: 'Notes page: three visual fixes', d: '(1) The instance switcher no longer falls outside the dropdown sheet: the sheet height is computed by the dropdown itself from the page count plus extra items, and the mobile instance badge moved from the top right to the top left of the icon. (2) A hairline gap between the two toolbar rows no longer appears after switching instances and scrolling back - heights are measured with getBoundingClientRect instead of the rounded offsetHeight, and measured again once layout settles. (3) Clicking a comment no longer makes the whole moment disappear: the comment area is not force-expanded, focusing no longer scrolls the page, and the card is only nudged into view.' },
        { t: 'Notes page: loading and lightbox', d: 'The file detail opened from the lightbox now uses the same builder and the same dialog as the library page, so download, delete and rename all work and no field is missing. Thumbnails get a disk cache (each image is processed once, concurrent requests are merged), the front end retries in three steps, and the lightbox preloads its neighbours - which is what caused the occasional load failure that a refresh fixed, and the sluggish paging.' },
        { t: 'Moment editor', d: 'The placeholder reads Say something, or post a photo and is left aligned. Attachments can be reordered by long-pressing (about 0.3s on touch, with a short vibration). Mood and weather names show above the icon, the selected tile is more visible, and on phones they become two dropdowns (Set mood on the left, Set weather on the right) with icon plus name, two per row. The three upload buttons on phones get tighter margins and scroll sideways so they stay on one row.' },
        { t: 'File picker: two sources', d: 'The Choose from library button is now Choose file. Two source buttons sit above the type tabs: Library files is the original mode and the default; Mounted files browses the Mount Management directories and, on upload, first asks for the target channel, owning instance and upload folder, then uploads and adds the files to the attachments. Switching source clears the selection, because the two sources identify files differently.' },
        { t: 'File picker: filters and search scopes', d: 'In Library files mode the search scope is embedded at the start of the search box with exactly the same options as the library page (All / Title / Tag / Category / User / Note / Other), and a filter button sits after the box opening the same filter dialog (file type, access status, black and white lists, review result, tags, date, size, dimensions, rating) with a badge counting the active conditions. To make that truly one implementation, the filter evaluation was extracted into a shared module used by both pages.' },
        { t: 'File picker: the eye preview', d: 'The preview shows the file name at the top; videos autoplay with sound; audio gets an eye too and autoplays; the preview box follows the file aspect ratio (square only when the ratio cannot be read); and the popup picks whichever side of the thumbnail has the most free space, guaranteed to sit outside the eye button rather than covering it.' },
        { t: 'Owning instance fills itself in', d: 'When uploading from the device or from mounted files, the owning instance is pre-set to the instance you are currently in, and the request falls back to it even if the field is left untouched.' },
        { t: 'Home page: Record joins the swipe cycle', d: 'Swiping cycles File, Link and Record, where it used to flip between the first two only - and sliding away from Record works too. The three action areas share exactly the same size and position, so switching no longer moves the tab buttons or adds a scrollbar, and the Link paste box no longer leaks into Record. Record icons are smaller and scale with the area width: four per row on desktop, three on phones, with a short last row centred. A moment published in Record mode lands in the file list below and the list expands to show it.' },
        { t: 'Instance attributes and switch password', d: 'Each instance row gains an Attributes button after Invite, and the old Rename action moved into that page. The page holds the name, the note and a switch password - one of the account password, a two-step verification code, or a custom instance password. Once enabled, switching to the instance from the home page, the library page or the notes page asks for verification first; after verifying on any one page the others will not ask again on refresh. Leaving the custom password empty means keep the current one, so renaming does not force a re-entry.' },
        { t: 'Video lightbox: zoomed video pans instead of paging', d: 'After pinching a video larger, swiping moves the picture instead of switching to the previous or next video, and no longer triggers the swipe-up random jump. Zooming back to the original size restores the normal behaviour.' },
        { t: 'Dropdowns close on scroll', d: 'Six mobile dropdowns now close themselves when the page scrolls: the notes page type select, sort select and the more menu at the top right, the admin page switcher at the top left, and the library page sort and directory path selectors.' },
        { t: 'Database: a moment title gets its own column', d: 'A moment title used to sit inside the note row extension field (JSON), so the Title scope could only run a LIKE over the whole blob - which may match unrelated fields and cannot use an index. It now lives in note_moments.title (default empty string), and writing, reading and the Title scope all use that column; the All scope still matches the extension field so old data stays reachable. Upgrading needs no manual step: the container entry script runs the compatibility pass first, which adds the column and backfills titles from the old JSON before the schema sync, and the backfill is idempotent. Clearing a title works too - there is deliberately no fallback to the old JSON, otherwise the stale value would come straight back.' }
      ]
    },
    {
      title: '34. What is new in v1.1.4',
      intro: 'v1.1.4 closes the loop: shared files get a clear permission boundary (other people shares are read-only), notes become strictly private (user plus instance, admins included), the corrupted mounted-video upload is actually fixed, and the mobile lightbox, dropdowns and moment cards get their rough edges sanded down. No new tables, no new columns, no migration - and apart from that upload fix the storage pipeline is untouched.',
      items: [
        { t: 'Shared files: edit tools belong to the owner', d: 'On a file somebody else shared with you, the detail page keeps only the read actions (preview, download, direct link). Cropping, compression, WebP conversion, cross-channel copy, store-to-local - the whole media editing block - plus the transfer button are hidden for non-owners, and their two data requests (transfer targets, media info) are not fired either, so nothing is hidden-but-still-called. The decision reads the shared / sharedSelf flags the API already returns.' },
        { t: 'Home page: the camera is gone', d: 'The camera button in the bottom-left quick toolbar is removed together with the whole capture dialog, front/back switching, zoom and system-camera fallback code, and the matching global styles. Picking from the photo library or the file picker is unaffected - the web page simply no longer drives the camera.' },
        { t: 'Notes are private: user plus instance', d: 'Listing, detail, editing, deleting, comment deletion, tag suggestions and the tag manager counts are all narrowed unconditionally to the signed-in user and the current instance. Being an admin grants no wider visibility - the admin notes page shows your own notes only. The rule sits on the server, so calling the API directly returns nothing extra. Existing notes simply become visible to their author alone; no migration needed.' },
        { t: 'Mobile notes lightbox: the edge swipe closes the lightbox', d: 'Swiping in from the left or right edge used to leave the lightbox open while the page navigated back. Now the edge swipe (26px to start, 64px to trigger) closes the lightbox and swallows the gesture so the page does not go back - one gesture, one action. Gestures starting on inputs, selects or the type tab strip are left alone.' },
        { t: 'Moment cards: videos lose the frame and background', d: 'When a video cover already has a poster, the extra background and padding are dropped so the poster fills the cell like an image does. The placeholder background only remains when there is no poster.' },
        { t: 'Moment cards: the More button sits at the end of the text', d: 'When the body exceeds its height limit, More no longer starts a new line at the bottom left; it floats at the end of the last text line (an inline spacer shortens that line and the button is positioned there), so the paragraph reads as if it ends naturally. Collapse still gets its own line.' },
        { t: 'Moment editor: the upload folder fills itself in', d: 'After picking files with Upload from device, the upload target page already has /notes/瞬间/{year}/{month} filled in; uploading mounted files to the library fills the same path. The year and month come from the current time, matching the folder habit used by notes.' },
        { t: 'Mounted video arrives corrupted (the headline fix)', d: 'A video uploaded from Mounted files showed up in the library with the right name and size but returned 404 and refused to play. The post-processing (compress / transcode) output reused the object key of the original file, because the default naming template takes the MD5 of the source and compression does not change that MD5. Local storage uploads are hard links, so writing the same name modified the source file, and the following delete-the-old-object step removed the freshly written output, leaving only an orphan on disk. Three fixes: a colliding output key is renamed to a unique one; the old object is not deleted when the keys match; the local adapter probes the target before writing, switches to a unique name if it exists, and retries once on EEXIST before falling back to a copy.' },
        { t: 'The eye preview reuses the cached thumbnail', d: 'In Mounted files mode the eye preview used to download the original again even though the cell thumbnail had already loaded. It now reuses that cached thumbnail and appears instantly.' },
        { t: 'Upload from device accepts any file type', d: 'The device picker inside the moment composer no longer restricts itself to images, videos and audio - any file can be chosen and continues to the upload target page.' },
        { t: 'Only the upload-method row swipes horizontally', d: 'Only the row holding Choose file / Upload from device / Extract from link can be swiped sideways; every other area (body, attachments, mood and weather) no longer accepts horizontal swipes, so writing in the body does not drag the whole page.' },
        { t: 'Home page: no more flicker when switching to File mode', d: 'The fade-in feedback used opacity 0.35 to 1 while the card base opacity is 0.7; the animation pushed it to 1 and it snapped back to 0.7, which read as a single flash of the dashed frame. It now uses filter: opacity(), which multiplies with the base opacity, so there is no jump at either end.' },
        { t: 'Home page: File and Record match Link in light mode', d: 'The Link panel is an el-card and inherits the global glass surface (white at 45%) on top of its 0.7 opacity - about 31% white. File and Record are plain divs using solid #FAFAFB at 0.7 - about 70% grey, visibly heavier. In light mode both now use the same glass surface, so all three match exactly (Record has no element opacity, so it multiplies by 70% with color-mix). Dark mode is untouched.' },
        { t: 'Channel settings: a floating add button', d: 'Add channel moved from the page header to a fixed circular button in the bottom-right corner that shows a plus by default; on desktop hovering expands the label, while on mobile it stays an icon and clears the safe area. The old header button is gone, and the dialog is the same one.' },
        { t: 'Video lightbox remembers where you stopped', d: 'Closing the video lightbox stores the position in localStorage (keyed by name and URL). The next time that video opens, a line appears between the table of contents and the settings column saying you last watched at 12:34, with a Jump button to continue and a Dismiss button to hide it for this visit. Positions within the first or last three seconds are not stored, so pointless prompts never appear. Paging, pausing and closing all flush the position.' },
        { t: 'Mobile admin: the more menu closes on scroll too', d: 'The previous release already closed six dropdowns on scroll, but the top-right more menu stayed open on share and account pages. It is now covered in the shared admin header component used by every backend page, and the listener was upgraded from scroll-only to scroll plus touch drag plus wheel, because iOS does not dispatch scroll during momentum scrolling and the sheet otherwise hung on screen until the finger lifted. Drags inside the sheet itself are ignored, and the first 60ms after opening are skipped so Element Plus positioning cannot close it immediately.' },
        { t: 'Database and everything else', d: 'No new tables, no new columns, no migration: making notes private only adds an author condition on columns that already exist, the shared-file decision uses the existing flags, and the playback position lives in the browser. Deploying the code is enough - old data, old links and old shares keep working.' }
      ]
    },
    {
      title: '35. What is new in v1.1.4.1',
      intro: 'v1.1.4.1 does one thing: on phones, the two toolbar rows at the top of the file manager now stretch edge to edge as a single block. Both rows used to have rounded corners, a small gutter on each side and a few pixels of vertical spacing, which made them look like two cards floating above the page. Now they run from the very left edge to the very right edge, the first row sits flush against the top of the screen, and the second row follows immediately underneath, so the two read as one surface. Desktop, tablet and every other backend page keep their previous header - nothing about data or APIs changed.',
      items: [
        { t: 'First row (header): square, flush to the top, full width', d: 'On phones the header had a 14px radius, a 4px gutter on both sides and sat 2px below the top edge. It now has no radius, spans the full screen width and sits flush against the top. The glass backing layer (the one with a 1px outline and shadow) loses its radius too and pulls its 1px outward overhang back in, so the full-bleed bar does not overflow the viewport by a pixel.' },
        { t: 'Second row (the one with select-all): square, flush, attached', d: 'The second row had a 5px radius and was inset 10px on each side. It now has no radius, spans edge to edge, and the gap to the first row is gone, so the two stack as one panel. Its vertical padding grows by 2px (4px to 6px) so the buttons and icons inside do not look squeezed.' },
        { t: 'Content inside the rows: row one unchanged, row two closer to the edges', d: 'Once the backgrounds go full bleed, the space previously provided by the header gutter and the content area padding disappears, and without compensation the page switcher on the far left of row one and the select-all box on the far left of row two would sit right against the screen edge. So the header horizontal padding goes from 0 to 4px, keeping every button in row one at exactly the same position as before; row two keeps only 2px of horizontal padding as requested, so its buttons sit closer to both edges and the scrollable area grows from 364px to 386px.' },
        { t: 'The 1px line that survived the first pass', d: 'After the first build the geometry already measured zero - header at top 0, gap between rows 0 - yet a faint line was still visible. The header element itself carries a 1px transparent border, while the glass backing is a pseudo element positioned against the padding box, so that 1px ring can never be covered. With rounded corners it was intentional breathing room; once the bar is flush it becomes a hairline of page background along the very top edge. On top of that, the header drops its shadow onto the top of row two, adding a soft gradient band. Both are gone now: the border ring is zeroed, the backing fills the whole border box with no downward shadow, and the only outline left is the bottom edge of row two, so the two rows are continuous from background to seam.' },
        { t: 'Sticky position follows the new layout', d: 'On phones the second row sticks below the header once you scroll. Since the static layout is now flush, the sticky offset changes from header bottom plus 2px to just the header bottom, the width and left offset become the full-bleed values, and the horizontal margins are cleared while stuck - otherwise the row would jump 2px on scroll or get pushed off-screen by the negative margins.' },
        { t: 'Scope', d: 'Only the file manager page at phone widths (up to 768px): every rule is scoped under that page marker, so other backend pages - which share the same header component - never match them, and desktop plus tablet keep their current look. No new tables, no new columns, no API changes.' }
      ]
    },
    {
      id: 'en-whatsnew-115',
      title: '36. What is new in v1.1.5',
      intro: 'v1.1.5 does two things. First, the move dialog now asks whether you want to move or copy: copying gives the target instance its own record with its own link while both records keep pointing at the same physical file, so no storage is duplicated. Second, the reference count and the share count are now completely separate concerns - one decides whether the record may be deleted, the other decides whether the stored file may be deleted - and every delete entry point enforces both.',
      items: [
        { t: 'Batch actions: pick move or copy first', d: 'After selecting files or folders and clicking Move, the first step still asks for the receiving instance, and a new Action section appears underneath with two choices: Move (the source is not kept) and Copy (the source is kept and the target gets an extra record). Neither is preselected, you must pick one before Next becomes clickable, and the dialog forgets the choice every time it opens. Once picked, the dialog title and the badge on step two change accordingly, so you always know which operation you are running.' },
        { t: 'A copy has its own link, not its own file', d: 'Copying creates a new record in the target instance, so it gets its own public link, name and tags, but it still points at the same object in storage - nothing is duplicated on disk. The relationship is recorded in the share count: from then on the two records are shared copies of one file, deleting either one only removes that record, and the stored file is removed only when the last record is gone.' },
        { t: 'Reference count: decides whether the record may be deleted', d: 'If a file is referenced - attached to a note as an attachment or cover, or its folder is shared with other users - the record cannot be deleted, not even moved to the trash. Deleting it would break those notes with a failed image and cut off the people it was shared with. The blocking message tells you exactly who is using it: note titles when notes reference it, or a hint to remove the folder sharing first.' },
        { t: 'Share count: decides whether the stored file may be deleted', d: 'Every extra record pointing at the same physical file adds to the share count. While it is above zero, deleting only removes your own record and leaves the file for the others; when it reaches zero (you are the last one) and nothing references it, purging it from the trash also removes the file from storage. Registered-only files are the exception - their file lives on another system and is never deleted from here.' },
        { t: 'The four deletion cases', d: 'Referenced with shared copies: the record cannot be deleted. Referenced without shared copies: the record cannot be deleted. Not referenced but shared: the record can be deleted and purged, the file stays. Not referenced and not shared: the record can be deleted, and purging removes the file too. The same decision path is used by single delete, folder delete, trash restore and purge, and batch actions, so no entry point can bypass it.' },
        { t: 'Upload dedup: same instance reuses the link, other instances get a new one', d: 'When an upload matches an existing file by content, the same instance simply returns the existing link without creating another record, so no share relationship is created. A match in a different instance creates a new record in the current instance with its own link, and counts as a shared copy of the same file. Physical identity is decided by the storage object identifier, so copies, cross-instance uploads and dedup hits all resolve to one file.' },
        { t: 'Detail page: Refs(xx) | Shared(xx)', d: 'The reference row in the file detail now prints two numbers, for example Refs(2) | Shared(1). Hovering explains what each one means; zeros are dimmed; and as soon as either is non-zero a View button appears that opens the reference page in a new tab. The old per-source breakdown is kept, but only shows when both sources are present.' },
        { t: 'Reference page: two sections', d: 'The page shows Refs(xx) | Shared(xx) at the top and then splits into two lists. The reference list shows which notes, folder shares or tag shares use the file, with type, time and author. The shared list shows which other records share the same physical file - which instance, who uploaded it, whether it is in the trash, and whether it was copied from yours. That section only appears when at least one shared copy exists.' },
        { t: 'Three bugs fixed along the way', d: '1) The reference page used to always claim the file was not referenced anywhere; the request URL was wrong and never returned data, it now lists correctly. 2) The reference number in the detail dialog was always zero because that data only comes from the detail endpoint and was never merged back; it now matches reality. 3) Opening the reference page in development produced a blank screen because the request was routed to the backend by mistake; the proxy rule is fixed.' },
        { t: 'Database and everything else', d: 'Three columns are added to the file table: reference count, share count and the source record (which record this one was copied or cloned from). All three have defaults, so old rows need no backfill - values are computed the first time a record is opened or deleted. Existing images, links, shares and note attachments are untouched.' }
      ]
    },
    {
      id: 'en-whatsnew-116',
      title: '37. What is new in v1.1.6',
      intro: 'v1.1.6 is a fixes-and-polish release. Two symptoms with one root cause are gone - the lightbox opening the first attachment instead of the one you clicked, and an edge swipe going back in the browser instead of closing the lightbox. Note tags are now truly isolated per account and instance, and a batch of interaction details in the moment editor and moment cards were aligned with the requested behaviour. It also adds file view history: closing the lightbox records the moment, and the history page can filter by today / yesterday / two days ago / last 7 days. The sort button, day-night default, site title placeholders and a few settings entries changed as well.',
      items: [
        { t: 'Why the lightbox only worked sometimes', d: 'The parent usually sets the preview list and opens the lightbox in the same render pass, so the component is created already open. That creation path never runs the open routine, leaving the internal index at the first item and the keyboard, edge-back gesture and history sentinel unbound. Clicking the third attachment showed the first, and an edge swipe navigated back instead of closing. Mounting now runs the open routine once, and both symptoms disappear together.' },
        { t: 'Note tags isolated per account and instance', d: 'Tag identity used to be name + instance + type, so two accounts using the same tag name shared one row and could see each other. Tags now carry an owner dimension: file tags leave it empty, note tags store the author account name, and uniqueness is judged on the four-part key. On startup, historical tags shared by several accounts are split per author automatically, so no manual migration is needed. Only the author can rename or merge a note tag, and admins cannot see other users\' note tags at all.' },
        { t: 'Picking files when publishing a note', d: 'The file picker used to list every file on the server for admins. It now lists only the files of the current account in the current instance, matching what the file manager shows.' },
        { t: 'Six moment editor details', d: '1) The body field is at least 30% of the viewport height. 2) The permanent "write something, or add a photo" hint left of Cancel is gone (the input placeholder stays). 3) While files are uploading, that spot reads "Uploading files". 4) The link-extract prompt is two rows taller. 5) Videos in the built-in file picker now show thumbnails. 6) Mood and weather show their names on hover on desktop, and phones now pick them by tapping icons instead of using dropdowns.' },
        { t: 'Moment layout', d: 'When the text overflows, the Full text / Collapse button now sits at the end of the last line and has a background instead of taking its own row. In divider style, attachments have no rounded corners and a 2px gap, and the title, text and attachment areas are exactly as wide as in bordered style - they used to be 32px wider, so switching styles made the content jump sideways.' },
        { t: 'Edit the publish time afterwards', d: 'The time next to a moment title is now clickable and opens a picker, so you can correct the real publish time (for example to record something from yesterday). The list sorts and groups by publish time, and the change takes effect immediately; a wrong value can be corrected again at any time.' },
        { t: 'New: file view history', d: 'Viewing a file in the lightbox - in the file manager or the note manager - records that moment on the file when the lightbox closes, including every file you swiped past. Only lightbox views count; opening the detail page or clicking a link does not. The history page gains a Recent views dropdown after File type with all / today / yesterday / two days ago / last 7 days, unfiltered by default.' },
        { t: 'File manager', d: 'The sort button is now a labelled button - down arrow with Descending, up arrow with Ascending - and on desktop hovering opens the menu and moving away closes it. Filters gain File references (referenced / not referenced) and File sharing (shared / not shared). When the move target is the current instance, only Move is allowed; copying into the same instance is disabled.' },
        { t: 'Settings and home page', d: 'The default day / night switch time is now 07:00 - 19:00 (manual settings are untouched). The site title accepts {host} (current domain), {user} (signed-in user) and {pagename} (current page); the latter two stay hidden when signed out and no stray separators are left behind. Disabled mounted-file channels no longer appear on the local files page. The Account permissions block is removed from the create-user dialog - new accounts start with defaults and are adjusted in the edit page afterwards. The home page drops the evergreen hint, widens the icon row spacing and adds a Notes button above the Files button in the bottom right corner.' },
        { t: 'Permissions and logging', d: 'Super admins can now delete or purge files owned by other accounts (regular users still only delete their own, unchanged). Failed uploads are written to the system log with the original file name and channel to make troubleshooting easier.' }
      ]
    },
    {
      id: 'en-whatsnew-117',
      title: '38. What is new in v1.1.7',
      intro: 'v1.1.7 is mostly a request-by-request alignment release: note settings gain a General tab (page loading mode and body font size), the moment editor gets a long list of interaction fixes, and Crop in the file detail page becomes Edit - with a real brush and text tool. On top of that, view history is narrowed to your own account and instance, edge swipes no longer navigate back, an empty site title now defaults to "GoHub page name", Collection is renamed Log, and the four modules on the user management page have new names.',
      items: [
        { t: 'Note settings: new General tab', d: 'A General entry now sits before Moment settings and holds two things. Page loading: Auto (default) keeps appending as you reach the bottom; Manual shows a Load more button instead. Font size: applies to the body text only - titles, dates and comments are untouched - and defaults to the shipped value (14.5px on desktop), so nothing changes visually for people who never touch it. Settings are stored per instance.' },
        { t: 'Moment card layout', d: 'In divider style the line is now exactly as wide as the content area - it used to be the box border, which stuck out by the left and right padding. Attachment gaps are 1px in both styles, and rounded corners in bordered style drop from 3px to 2px.' },
        { t: 'Comments: long-press delete, expand / collapse, no jumping', d: 'The always-visible delete cross after a comment is gone; long-press a comment (or right-click) to get a menu with Delete. When comments exceed the height limit a More button appears below and toggles to Collapse; a reload starts collapsed. After posting, the page stays on the moment you were reading. About the reported "a moment with attachments disappears when you tap someone else\'s comment": the post/reply scroll compensation and the long-press menu were rewritten so scrolling can no longer run away, but every comment in the local environment belongs to the signed-in account, so the original situation could not be reproduced.' },
        { t: 'A dozen moment editor details', d: 'Mood Sad uses a crying icon and the label reads 伤心; the location field no longer uses browser autofill - focusing lists recent values of the current instance and typing filters the database (same feel as the tag box, current instance only); Space commits a tag just like Enter; the tag dropdown always opens upwards; a spinner now precedes "Uploading files"; the attachment count moves left of Cancel (uploading state takes the same slot); the Upload to image host dialog only closes via its buttons or Esc; the editor and the file picker are 98% wide and tall on phones; the body field is at least 45% of the viewport with a free resize handle; the link-extract box is two rows taller; the title is no longer filled in automatically and its placeholder reads Title (optional).' },
        { t: 'The file picker remembers where you were', d: 'Loaded lists are cached in the browser per instance, type / channel and directory (24-hour expiry, with count and size caps). The next visit paints from the cache first and refreshes in the background instead of showing a blank list. The chosen source, type, mount channel and opened directory are remembered too.' },
        { t: 'Publish time: centred, weekday, original timestamp', d: 'On phones the time picker opens centred on screen instead of being clipped at the bottom. The time now carries the weekday, e.g. 11月11日 09:13 周三. A new first-published column is written once when a moment is created and never changes afterwards - per the request it is stored only, not sent to the client or displayed yet.' },
        { t: 'File manager: the move button picks the instance directly', d: 'The move button on folders in card view and on folders and files in list view now opens the same Choose target instance dialog used by batch operations - no need to enter batch mode first.' },
        { t: 'Crop becomes Edit, with a brush and text', d: 'Crop in the file detail page is now Edit. It is the same processing page plus two tools: a brush (free drawing, 7 colours x 3 widths, undo and clear) and text (tap anywhere to type, adjustable colour and size). Both live in image coordinates, so they rotate together with the picture and four rotations return everything to where it started; on save the image is cropped first and the overlay is burnt in, so strokes outside the crop are trimmed naturally. The page is 98% wide and tall now.' },
        { t: 'View history is per account and per instance', d: 'The view time used to be written on the file row, so an admin opening someone else\'s file showed up as "viewed yesterday" for the owner. Now only your own files record a view (others are skipped silently), and the Recent views filter always narrows to the signed-in account, even inside shared folders. The File references page likewise lists only your own files in the current instance.' },
        { t: 'Site-wide: no back-swipe, square lightbox images, 5px switcher margins', d: 'A horizontal swipe starting within 28px of the screen edge is always swallowed unless the element can actually scroll sideways or is a slider / carousel / tab strip. Swipes that started at the edge on an input or switch used to pass through and navigate back; that gap is closed. Images shown in any lightbox are no longer rounded. The page switcher at the top-left of the file and note managers gets 5px margins on phones.' },
        { t: 'Site title default and page names', d: 'An empty Site title now defaults to "GoHub {pagename}", so the default already carries the page name. The {pagename} map covers / = Home, /dashboard = Dashboard, /localFiles = Local files, /notes = Notes, /customerConfig and its sub-paths = Users, /systemConfig = Settings and /manage/history = History; it is still shown only when signed in, otherwise the title falls back to "GoHub".' },
        { t: 'Renames: Log, and four user management modules', d: 'Collection under Record on the home page and in the note manager is renamed Log (the publish button reads Add log, the settings category Log settings). On the user management page: Instance management becomes My instance space, Storage channels becomes Default storage channels, Public sharing becomes Public sharing records, and Administrator actions becomes Administrator actions area.' }
      ]
    },
    {
      id: 'en-whatsnew-118',
      title: '39. What is new in v1.1.8',
      intro: 'v1.1.8 closes the loop on details: moment cards no longer have a title at all and the publish time is back to being just a time (editable, not bold); note settings gain a page background; stacked pages are closed one layer at a time by closePageOrder for both edge swipes and Esc; text in the editor can be dragged; and the card view in the file manager gets a round of small visual fixes.',
      items: [
        { t: 'No more title on moments, publish time always editable', d: 'The title input is removed from the editor and the card no longer renders a title. The publish time no longer stands in for a title and is no longer bold, and it can be edited at any time. The default sort Newest now orders by publish time descending, with rows that have no publish time placed last and creation time as the tiebreaker.' },
        { t: 'Comments: expand and collapse, and the vanishing card fix', d: 'When comments exceed the visible height a More button appears below; it turns into Collapse when expanded and starts collapsed again after a refresh. The button used to live inside the same clipped container as the list, so it clipped itself; the container no longer clips, the list clips inside, and the button sits outside. The card disappearing after clicking a comment had two causes: the card is a multi-root component, so the element reference pointed at a comment node and the position lookup threw, skipping the whole scroll compensation; and on phones the soft keyboard shrinks the viewport, so every percentage-based size shrank at once and pushed the card off screen. The first is fixed by taking the real node through a ref, the second by ignoring viewport shrink while an input is focused.' },
        { t: 'Note settings: page background', d: 'A new multi-line field under Settings, General, takes a list of quoted URLs. With several URLs one is picked at random on each refresh; with a single one it is always used. It only applies in day mode - dark mode does not render it at all. Validation matches the per-account background field in user management: http(s) links and site paths starting with / only, up to 20 entries, and bad entries are dropped instead of failing the whole save. Leaving it empty removes the background.' },
        { t: 'Border line style: rename, 2px gaps, 3px corners', d: 'Bordered is renamed Border line in both languages. In that style attachments now sit 2px apart and have 3px corners; divider style keeps its 1px gaps and square corners. The gap constant used by the height budget follows the same style, so the computed row height matches what is actually rendered.' },
        { t: 'File picker: all types, renamed source buttons', d: 'An All tab now sits before Images and shows every file type at once (mounted mode does not filter either). The two source buttons read From library and From mounted. The last picked type is still remembered.' },
        { t: 'Editor: draggable text, taller stage on phones', d: 'With the text tool, pressing on existing text drags it (the offset from where you pressed is preserved, so it does not jump) while pressing empty space adds a new one. Hit testing measures the text with the same font used for drawing and adds a 6px finger margin, searching from the topmost text down. On phones the stage is now at least 60 percent of the viewport height. Every entry point uses the same component, and the upload page crop no longer passes allow-annotate=false.' },
        { t: 'Stacked pages close one layer at a time', d: 'closePageOrder() registers each overlay (lightbox, file detail, dialogs) with its layer and removes it on close. An edge swipe or Esc picks the topmost layer by z-index and open order and closes only that one: with the file detail stacked on the lightbox the detail closes first, and the lightbox goes on the next swipe. While fixing this a real bug turned up: swipe distance was recorded only on the decision frame (around 6 to 14px) and later frames returned early, so the 64px threshold was never reached and a real swipe could not close anything.' },
        { t: 'Lightbox: file detail still opens after scrolling', d: 'The lightbox now locks page scrolling while open and restores the scrollbar width on close, so dragging inside it no longer scrolls the list behind; paging or sorting drift can no longer make the detail lookup miss the current row, and a fallback opens it from the original row data. When the controls auto-hide, clicking empty space now only brings them back instead of closing the lightbox.' },
        { t: 'Card view: four small visual fixes', d: 'Card corners go from 12px to 5px; the selection circle moves up 2px; the hover copy and open buttons go from 32px to 28px with 12px icons; and video thumbnails get a small play badge in the bottom-right corner (not drawn when the thumbnail failed to load, so it never sits on top of the error state).' },
        { t: 'Icons registered', d: 'The convert to redirect and convert direction buttons referenced exchange-alt and right-left without registering them, which logged a missing icon warning and rendered blank; both are registered now (Font Awesome 6 resolves both names to right-left). The location-dot icon used by notes is registered too.' },
        { t: 'Footer, home tab and detail buttons', d: 'The footer on the home and login pages now ends with HQH. The Record tab on the home page is renamed Publish. Opening a file detail from the lightbox in the note manager now shows the same Tags, Blacklist and Whitelist buttons as the file manager.' }
      ]
    },
    {
      id: 'en-whatsnew-119',
      title: '40. What is new in v1.1.9',
      intro: 'v1.1.9 gets to the bottom of something the previous release thought it had fixed: in the file preview, tapping View detail sometimes did nothing. The cause was not scrolling but a z-index race between the dialog and the preview. All fifteen popups inside the file detail are now part of the layered close order, and the crop stage on phones is 70 percent of the viewport.',
      items: [
        { t: 'View detail from the preview now always works', d: 'Element Plus assigns overlay z-index values from a global counter starting at 2000, while the preview lightbox was hard-coded to 3200. Early in a session a detail dialog could land around 2001 - it did open, but sat underneath the lightbox, which read as a dead button. The overlay base is now 4000 while the lightbox stays at 3200 (still above the page header), so the detail is always on top, and closing it brings the preview back.' },
        { t: 'Fifteen popups joined the layer stack', d: 'Tags, blacklist, whitelist, rename, delete, expiry, encrypt, redirect, share, source, convert to remote or local, compress, convert to WebP and crop were never registered as layers. With one of them open, Esc or an edge swipe closed the whole file detail and left the popup floating. They are registered now, so each gesture closes only the topmost layer: popups first, then the detail, then the preview.' },
        { t: 'Confirmation boxes count as a layer', d: 'Delete, blacklist and whitelist use confirmation boxes (delete even asks you to type the confirm word), not regular dialogs, so they were completely outside the layer system. They are tracked now: pressing Esc with a confirmation open closes only that box, never the detail behind it.' },
        { t: 'Crop stage on phones is 70 percent of the viewport', d: 'Raised from 60 percent. The toolbar is pushed below the fold as a result, so the dialog body scrolls - every tool can be reached instead of being clipped.' },
        { t: 'List view thumbnails have 5px corners', d: 'Matching the card view. Previously 8px on desktop and 6px on phones.' },
        { t: 'Moment placeholder', d: 'Now reads Capture this moment, gather memories for later.' }
      ]
    },
    {
      id: 'en-whatsnew-1191',
      title: '41. What is new in v1.1.9.1',
      intro: 'v1.1.9.1 digs out the root cause of two z-index fights: pulling down inside the preview did not open the file detail, and confirmation boxes sat underneath the dialog that opened them. Fourteen more popups also joined the layered close order, the moment editor got 10px trimmed from its header and footer, and the mood and weather name tips became a floating layer that cannot be clipped.',
      items: [
        { t: 'File manager: pull down in the preview opens the detail', d: 'The previous release only fixed the Detail button. Pulling down takes another branch: for stored files it emits an open-detail event, and the file manager never listened to it, so nothing happened. The listener is wired now and shares the same handler as the button, with the row saved by the preview as a fallback when the current page has moved on.' },
        { t: 'Confirmation boxes are no longer buried', d: 'Blacklist, whitelist and delete inside the file detail, and Link extract in the moment editor, are imperative Element Plus message boxes. Their z-index base is 2000 while regular dialogs start at 4000, so they always ended up underneath - Link extract looked like a dead button. They are raised to 6200 now and always sit above the dialog that opened them.' },
        { t: 'Fourteen popups joined the layer stack', d: 'Note settings, the publish-type chooser, delete moment, filters, new folder, link format (both pages), record file with its folder picker, upload settings with its folder picker, and the instance switcher in three places are all registered layers. The folder picker sits above its host dialog, and one back gesture or Esc closes only the topmost layer.' },
        { t: 'Moment editor: name tips are no longer clipped', d: 'The mood and weather name tips used to be rendered inside the icon, but the body is a scroll container, so the little bubble above the icon fell entirely outside the clip box and was invisible. They are now a single floating layer anchored to the icon: nothing clips them and the header cannot cover them.' },
        { t: 'Editor and crop page: 10px off header and footer', d: 'Padding on the header and footer rows is reduced by 10px each, giving the text area and the image stage 20px back. Both fixed blocks measure exactly 10px shorter than before.' },
        { t: 'Upload to library: pick a folder, keep the history', d: 'A folder picker now sits left of the upload folder field and lists folders of the selected instance. The field also remembers recently used folders and offers them on focus, sharing the same history as the upload settings on the home page.' },
        { t: 'Two labels', d: 'The comment button reads Post comment instead of Post, and the moment placeholder now reads Capture the moment, gather the little things.' }
      ]
    },
    {
      id: 'en-whatsnew-1192',
      title: '42. What is new in v1.1.9.2',
      intro: 'v1.1.9.2 adds an Album view modelled on Synology Photos and Immich: square tiles with no corners, no borders and no caption area, images filling the tile, a 2px gap and the grid running edge to edge. Twenty-nine popups also join the layered close order, and a batch selection can now be cleared with Esc or an edge swipe.',
      items: [
        { t: 'New: Album view', d: 'The view switcher goes from two buttons to three, with Album after the first two and a stacked-photos icon. The page is nothing but tiles: images load their thumbnail and fill the tile, folders show an icon with the name underneath, a tap on an image opens the lightbox and a tap on a folder enters it.' },
        { t: 'Album sizing', d: 'No rounded corners, no outer border, no caption area, 2px between tiles, and the grid runs to both screen edges. Phones get 4 per row in portrait and 8 in landscape (square tiles); tablets get 6 and 12; the desktop is fixed at 8 square tiles per row, so widening the window simply makes every tile bigger while both edges stay flush.' },
        { t: 'How many the album loads at once', d: 'Phones (landscape included) start with 48 tiles, tablets and desktops with 72; reaching the bottom appends more automatically, with no Load more button.' },
        { t: 'The recycle bin follows the display mode too', d: 'The recycle bin used to be fixed to folder grouping. It now offers the same Show folders / Show files directly pair as the normal list, and in the flat mode everything is a single list with no folder cards.' },
        { t: 'Two interface details', d: 'Directly Expand Files now reads Show Files Directly, and folder cards in card view drop from 12px corners to 5px to match file cards.' },
        { t: 'Creating a folder records who created it', d: 'Folders made from Create folder used to show no creator in their properties, because a folder is only a path with no row to attach one to. The account and instance now keep a folder registry written at creation time, so the properties show the creator and the creation time, empty folders included.' },
        { t: 'Clear a batch selection with Esc or an edge swipe', d: 'With files or folders selected, pressing Esc on a desktop or swiping from the screen edge on a phone clears the selection instead of leaving the page or going up a folder. This only happens when there is no popup left to close.' },
        { t: 'Twenty-nine popups joined the layer stack', d: 'Delete from the recycle bin, folder properties, delete file or folder, batch backup, batch rename, batch tags, batch limits (expiry, encryption, redirect), blacklist and whitelist, move file, tag properties / merge / split / delete, the file picker and its filters inside the moment editor, the target folder picker during an upload, the instance join / create / invite / properties / delete dialogs in user management, the trend date picker in system status, the channel add / detail / edit / authorize dialogs, and API token create / credentials / edit / delete - one Esc or one swipe now closes only the topmost of them.' },
        { t: 'Two underlying bugs fixed along the way', d: 'First, a page that had never opened a popup did not listen for Esc at all, because the listener was only installed when a popup registered; clearing a batch selection therefore did nothing. Second, a popup closed with v-show left its layer in the stack, and such a dead layer silently swallowed the first Esc. Both the install point and dead-layer pruning are fixed.' }
      ]
    },
    {
      id: 'en-whatsnew-1193',
      title: '43. What is new in v1.1.9.3',
      intro: 'v1.1.9.3 is an alignment release: the three views (cards, list, album) now share one file-area top margin, album tiles get a real video thumbnail with a play badge, the view switcher gains its third slider position, the two header rows on desktop run edge to edge and stick together while scrolling, the lightbox opens clean, the moment editor footer always says something useful, and the mobile editing page is truly full screen.',
      items: [
        { t: 'One top margin for all three views', d: 'Card view used to sit 10px below the second row while list and album sat at 15px. The list value is the baseline now: 18px on desktop, 11px on phones, so switching views no longer jumps. On phones all three reset to zero and the parent gap supplies the 11px once, otherwise a sticky second row plus a per-view margin would double the whitespace.' },
        { t: 'The view switcher gets its third slider position', d: 'The slider is an absolutely positioned ::before moved by transform, and the offset is n x (button width + gap): 28px + 2px on desktop means 60px for album, 24px + 2px on phones means 52px. Switching to album used to leave the slider parked on the list button.' },
        { t: 'Album tiles show a real video frame', d: 'Video tiles used to be plain black. They now load with preload="metadata" plus a #t=0.1 media fragment, which forces the engine to decode the frame at 0.1s - metadata alone leaves many engines with nothing to paint. muted and playsinline keep phones from autoplaying or going full screen, and the frame fills the square tile with object-fit: cover.' },
        { t: 'A small play badge on video tiles', d: 'A 20px circle (55% black with a white triangle) sits 6px from the bottom-right corner - enough to identify, not enough to compete with the image. pointer-events: none lets taps pass through to the tile, so there is no dead spot on the badge, and the triangle is nudged 1px right because its visual centre is off.' },
        { t: 'Desktop header rows: edge to edge', d: 'Both rows lose their side gutters and run to the screen edges. Negative margins cancel the main container padding (60px on desktop, 24px on tablet) while widening the rows to match, and the corners and outer border are removed. Note that .breadcrumb-container is content-box by default, so width: calc(100% + 120px) still adds the 12px side padding - the row overshot by 24px until box-sizing: border-box was set explicitly.' },
        { t: 'Desktop header rows: no gap between them', d: 'The vertical gap is now zero. There is a hidden surplus here: the reserved-space variable --admin-header-space is measured as height plus 12px (breathing room for the shadow), so the second row cancels it per breakpoint - 20px on desktop, 16px on tablet, 28px with the compact header (1023 and below), where cancelling only 16px left an 8px slit in tablet portrait. When the recycle-bin banner sits between the rows the offset resets to zero so the banner is not dragged up with them.' },
        { t: 'Desktop header rows: sticking', d: 'Page scrolling is owned by OverlayScrollbars, so native position: sticky does nothing; the existing approach is kept - cross a threshold, switch to fixed and hold the space with a wrapper - and it is now enabled on desktop too. The threshold subtracts the first row height, otherwise the moment the second row reaches the header bottom edge has not switched yet and the first row overlaps it. Three states are verified: scrolling down hides the header and pins the second row to the top, scrolling up brings the header back and the second row sits under it, and returning to the top restores the normal flow. The stuck state uses an opaque background and a 1px bottom border so the file list cannot show through.' },
        { t: 'The lightbox opens without controls', d: 'Opening no longer shows the controls or starts the auto-hide timer; a tap shows them and another tap hides them. Clearing the timer matters: left in place it would flip the controls back to hidden two or three seconds later and force a pointless reflow, fighting the tap toggle. The native video control bar follows the same state (:controls is bound to it) - otherwise the custom controls hide and the native bar stays.' },
        { t: 'Lightbox backdrop and paging buttons', d: 'The scrim drops to 10% (a light blur is kept), and the previous / next buttons go from solid black to the same glass treatment as the close button (1px white border, 8% white fill, 16% on hover). Because the scrim is nearly transparent, anything drawn on it needs its own outline or it disappears over a light page.' },
        { t: 'Dot indicator in the lightbox', d: 'With more than one image, a row of dots appears 10px from the bottom while the controls are hidden, follows the current image, and disappears as soon as the controls show. It tracks the position of the current image inside the thumbnail set rather than the global index, because the lightbox can open from either the current folder or all images and the index bases differ. Visibility is driven by opacity on an is-idle class instead of v-if, since rebuilding N nodes on every control toggle stutters with many images. The 1px dark ring around each 5px dot exists so they stay legible on a 10% scrim.' },
        { t: 'Phone image lightbox: centred', d: 'The stage used to reserve padding for the title row above and the thumbnails below, squeezing the image into a small block. The image is now centred and no longer yields to the controls, which become absolutely positioned overlays with a gradient or solid backing so white text does not wash out on a light photo. These rules apply to images only (an is-image class on the root), so video and PDF layouts are untouched.' },
        { t: 'Phone image lightbox: three zoom buttons removed', d: 'Zoom out, size toggle and zoom in are hidden on phones - pinch zoom covers the use case and the buttons were in the way. They stay on desktop.' },
        { t: 'Smaller thumbnails', d: '72x54 becomes 64x48 on desktop and 58x44 becomes 52x40 on phones, still 4:3 - the thumb is a 4:3 box with cover, so changing the ratio would distort the image.' },
        { t: 'Moment editor: a three-state footer hint', d: 'The slot left of Cancel used to show "x attachments" only when there were attachments, so an empty draft said nothing about whether you could write there. It now shows an uploading hint with a spinner, "x attachments" when there is text or media, and "Write something, or add a photo" (65% opacity and italic to read as a hint) when there is neither. Text is trimmed first, so a few spaces do not count as content.' },
        { t: 'Divider style gaps are 2px', d: 'Raised from 1px to match the default style. Two places move together: the gap in the stylesheet and the attachGapOf() constant used for sizing. That constant feeds the height budget (total grid height divided by rows) that pagination relies on, and a mismatch shows up as images creeping upward as you scroll with the last row clipped on the final screen.' },
        { t: 'Editing page: secondary actions move to the footer', d: 'The footer splits in two. The left side switches with the mode - Reset selection in crop mode, Undo and Clear for brush and text - and the right side is always Cancel and Save. All three are text buttons gated on there being a selection or an annotation, so they cannot be tapped by accident.' },
        { t: 'Editing page: genuinely full screen', d: 'On phones the dialog used to be 374px wide (390 x 94% minus margins) because responsive.css has a global, !important dialog width cap. Going full screen means overriding it with !important in turn (width and max-width 100vw, height and max-height 100vh, zero margin and corners) and removing the default Element Plus centring offset.' },
        { t: 'Editing page: stage is at least 65vh on phones', d: 'min-height rather than height: a short image still gets a 65vh stage instead of collapsing, and a tall image can grow past it with the body scrollbar taking over instead of being cropped. A fixed height would fail on both ends. When the toolbar pushes below the fold the page scrolls, so every button stays reachable.' },
        { t: 'Label: Crop instead of Box crop', d: 'The Chinese tool label is shorter now; the English side already read Crop. The toolbar is icon plus text, and a shorter label keeps it on one line on phones.' }
      ]
    }
  ]
};

export default {
  name: 'DocsPage',
  data() {
    return {
      // 当前阅读到的章节（用于左栏目录高亮）
      activeSection: '',
      tocObserver: null,
    };
  },
  computed: {
    isZh() {
      return String(this.$i18n.locale || 'zh-CN').startsWith('zh');
    },
    dict() {
      return this.isZh ? ZH : EN;
    },
    sections() {
      return this.dict.sections;
    }
  },
  watch: {
    // 中英切换后章节数量/顺序一致，重新建立观察器即可
    sections() {
      this.setupTocSpy();
    }
  },
  mounted() {
    this.setupTocSpy();
  },
  beforeUnmount() {
    if (this.tocObserver) {
      this.tocObserver.disconnect();
      this.tocObserver = null;
    }
  },
  methods: {
    t(key) {
      return this.dict[key];
    },
    toggleLocale() {
      setLocale(this.isZh ? 'en' : 'zh-CN');
    },
    /** 左栏目录跟随正文滚动高亮当前章节 */
    setupTocSpy() {
      if (this.tocObserver) {
        this.tocObserver.disconnect();
        this.tocObserver = null;
      }
      this.$nextTick(() => {
        const els = this.sections
          .map((s) => document.getElementById(s.id))
          .filter(Boolean);
        if (!els.length || typeof IntersectionObserver === 'undefined') return;
        this.tocObserver = new IntersectionObserver(
          (entries) => {
            const visible = entries
              .filter((e) => e.isIntersecting)
              .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top);
            if (visible.length) this.activeSection = visible[0].target.id;
          },
          { rootMargin: '-10% 0px -75% 0px', threshold: [0, 1] },
        );
        els.forEach((el) => this.tocObserver.observe(el));
      });
    },
    scrollTo(id) {
      const el = document.getElementById(id);
      if (el) {
        this.activeSection = id;
        el.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    },
    goBack() {
      if (window.history.length > 1) {
        this.$router.back();
      } else {
        this.$router.push('/');
      }
    }
  }
};
</script>

