.docs-toc {
  /*
   * v3.0.0：左侧大纲粘滞固定（滚动页面时大纲不跟着滚，自身超高时可独立滚动）。
   * 顶栏高度：文档页的顶栏是普通流式头部（随正文滚走、无 fixed/sticky 顶栏），
   * 因此 --docs-topbar-height 记为 0；若日后头部改为吸顶，只需改这一个变量。
   */
  --docs-topbar-height: 0px;
  position: sticky;
  top: calc(var(--docs-topbar-height) + 16px);
  align-self: start;
  max-height: calc(100vh - var(--docs-topbar-height) - 32px);
  overflow-y: auto;
  overscroll-behavior: contain;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 14px;
  border-radius: 14px;
  border: 1px solid var(--glass-border);
  background: var(--glass-bg);
}

.toc-title {
  font-size: 12px;
  font-weight: 700;
  opacity: 0.6;
  margin-bottom: 6px;
  letter-spacing: 0.5px;
}

.toc-item {
  font-size: 13px;
  color: inherit;
  text-decoration: none;
  padding: 5px 8px;
  border-radius: 8px;
  opacity: 0.85;
  transition: background-color 0.2s ease, color 0.2s ease;
}

.toc-item:hover {
  background: color-mix(in srgb, var(--primary-color) 12%, transparent);
  color: var(--primary-color-accent);
  opacity: 1;
}

/* 当前阅读到的章节高亮 */
.toc-item.is-active {
  background: color-mix(in srgb, var(--primary-color) 16%, transparent);
  color: var(--primary-color-accent);
  font-weight: 600;
  opacity: 1;
}

.docs-content {
  min-width: 0;
}

.doc-section {
  padding: 18px 20px;
  margin-bottom: 16px;
  border-radius: 16px;
  border: 1px solid var(--glass-border);
  background: var(--glass-bg);
  scroll-margin-top: 20px;
}

.doc-section-title {
  margin: 0 0 10px;
  font-size: 17px;
  font-weight: 700;
}

.doc-section-intro {
  margin: 0 0 10px;
  font-size: 13px;
  opacity: 0.75;
  line-height: 1.7;
}

.doc-list {
  margin: 0;
  padding-left: 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.doc-list li {
  font-size: 13.5px;
  line-height: 1.75;
}

.doc-item-title {
  font-weight: 600;
}

.doc-item-desc {
  margin-left: 8px;
  opacity: 0.8;
}

.doc-sublist {
  margin: 6px 0 0;
  padding-left: 18px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  opacity: 0.85;
}

.docs-footer {
  text-align: center;
  font-size: 12px;
  opacity: 0.55;
  padding: 10px 0 0;
}

@media (max-width: 900px) {
  .docs-body {
    grid-template-columns: minmax(0, 1fr);
  }

  .docs-toc {
    /* 移动端大纲是横向折叠条（不是抽屉），保持原样式、不做 sticky */
    position: static;
    top: auto;
    max-height: none;
    overflow: visible;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 6px;
  }

  .toc-title {
    width: 100%;
    margin-bottom: 0;
  }
}
</style>

<!--
  v3.0.0：让「查看文档」页左侧大纲真正 sticky（不是 scoped，作用于 body）。
  原因：全局 OverlayScrollbars 挂在 document.body 上，给它加了 overflow: hidden auto，
  于是 body 成了一个「自身并不滚动的滚动容器」，position: sticky 相对它计算时永不移位，
  大纲就跟着整页一起滚走了（已实测：放开 body overflow 后 top 由 -1469 变回 16）。
  处理：仅当文档页挂载期间（body 内含 .docs-page）放开 body 的 overflow，
  让滚动重新由文档根元素承担，sticky 立即生效；OverlayScrollbars 的悬浮滚动条仍随滚动更新。
  两个注意点：
  1) 必须同时放开 x 与 y —— 只放开 y 时，浏览器会把 y 的 visible 折算成 auto，sticky 依旧失效；
  2) 图片预览灯箱打开时（存在 .el-image-viewer__wrapper）不做覆盖，
     保证灯箱期间背景仍被锁定、不能被滚动。
-->
<style>
body:has(.docs-page):not(:has(.el-image-viewer__wrapper)) {
  overflow: visible !important;
}
</style>
